// ══════════════════════════════════════════
// STARS
// ══════════════════════════════════════════
(()=>{
  // Three depth layers: far = distant/faint/slow, near = bright/fast
  const layers=[
    {id:'stars-far',  count:55, minSz:.3, maxSz:1.0, minA:.04, maxA:.42, speed:0.25},
    {id:'stars-mid',  count:50, minSz:.8, maxSz:1.5, minA:.10, maxA:.60, speed:0.55},
    {id:'stars-near', count:25, minSz:1.4,maxSz:2.8, minA:.20, maxA:.88, speed:1.00},
  ];
  const starsEl=document.getElementById('stars');
  layers.forEach(layer=>{
    layer.el=document.getElementById(layer.id);
    for(let i=0;i<layer.count;i++){
      const d=document.createElement('div');d.className='star';
      const sz=(Math.random()*(layer.maxSz-layer.minSz)+layer.minSz);
      const left=Math.random()*100,top=Math.random()*100;
      const a2=(Math.random()*(layer.maxA-layer.minA)+layer.minA).toFixed(2);
      const a1=(Math.random()*0.07).toFixed(2);
      const pullX=((50-left)/100*60).toFixed(1),pullY=((50-top)/100*60).toFixed(1);
      d.style.cssText=`width:${sz.toFixed(1)}px;height:${sz.toFixed(1)}px;top:${top.toFixed(1)}%;left:${left.toFixed(1)}%;--d:${(Math.random()*4+2).toFixed(1)}s;--delay:${(Math.random()*5).toFixed(1)}s;--a1:${a1};--a2:${a2};--pull-x:${pullX}vw;--pull-y:${pullY}vh`;
      layer.el.appendChild(d);
    }
  });

  // ── Mouse parallax — each layer drifts at its own speed ──
  const MAX_SHIFT=18;
  const EASE_IN=0.045;
  const EASE_OUT=0.028;
  const IDLE_MS=800;
  let targetX=0,targetY=0,lastMove=0;
  const cur=layers.map(()=>({x:0,y:0}));

  // ── Travel warp (active while body.tab-ripple) ──
  let tVel=0;              // current velocity (near-layer px/frame)
  const tOff=layers.map(()=>0);  // accumulated Y offset per layer
  const T_MAX=5.5;         // peak speed for near layer
  const T_ACC=0.16;        // acceleration rate
  const T_DEC=0.055;       // deceleration rate after ripple ends
  const T_RET=0.032;       // rate at which offset drifts back to 0

  // Cache menu element for per-frame menu-drift check
  const _mmEl=document.getElementById('main-menu');

  function tick(){
    const now_ms=Date.now();
    const idle=now_ms-lastMove>IDLE_MS;
    if(idle){targetX+=(0-targetX)*EASE_OUT;targetY+=(0-targetY)*EASE_OUT;}
    const animating=starsEl.classList.contains('pulling')||starsEl.classList.contains('restoring');
    const ripple=document.body.classList.contains('tab-ripple');
    // Menu is visible — apply depth-parallax Lissajous drift (near faster, far slower)
    const isMenu=_mmEl&&_mmEl.style.display!=='none';

    // Ramp velocity up during ripple, decay it after
    tVel+=(ripple?(T_MAX-tVel)*T_ACC:(-tVel)*T_DEC);

    const cap=window.innerHeight*0.36;  // safe buffer (star layers are 180% tall)
    layers.forEach((layer,i)=>{
      cur[i].x+=(targetX*layer.speed-cur[i].x)*EASE_IN;
      cur[i].y+=(targetY*layer.speed-cur[i].y)*EASE_IN;
      // Accumulate upward travel offset
      tOff[i]-=tVel*layer.speed;
      const lCap=cap*layer.speed;
      if(tOff[i]<-lCap) tOff[i]=-lCap;
      // When velocity has decayed, smoothly return offset to zero
      if(Math.abs(tVel)<0.12) tOff[i]+=(0-tOff[i])*T_RET;
      // Menu-parallax drift — Lissajous sinusoid, each depth layer moves at its own rate
      const mDX=isMenu?Math.sin(now_ms*0.00028*(0.50+i*0.32))*22*layer.speed:0;
      const mDY=isMenu?Math.cos(now_ms*0.00021*(0.50+i*0.28))*16*layer.speed:0;
      if(!animating) layer.el.style.transform=`translate(${(cur[i].x+mDX).toFixed(1)}px,${(cur[i].y+tOff[i]+mDY).toFixed(1)}px)`;
    });
    requestAnimationFrame(tick);
  }

  document.addEventListener('mousemove',e=>{
    lastMove=Date.now();
    targetX=(e.clientX/window.innerWidth -0.5)*2*MAX_SHIFT;
    targetY=(e.clientY/window.innerHeight-0.5)*2*MAX_SHIFT;
  },{passive:true});

  requestAnimationFrame(tick);
})();

