function isMainMenuVisible(){
  const menu=document.getElementById('main-menu');
  return !!menu&&menu.style.display!=='none';
}

function isGameplayPaused(){
  return _pauseOpen&&!isMainMenuVisible();
}

const __nativeSetTimeout=window.setTimeout.bind(window);
const __nativeClearTimeout=window.clearTimeout.bind(window);
const __nativeSetInterval=window.setInterval.bind(window);
const __nativeClearInterval=window.clearInterval.bind(window);
const __pauseAwareTimeouts=new Map();
const __pauseAwareIntervals=new Map();
let __pauseAwareTimerId=1_000_000_000;

window.setTimeout=(handler,timeout=0,...args)=>{
  if(typeof handler!=='function') return __nativeSetTimeout(handler,timeout,...args);
  const id=++__pauseAwareTimerId;
  const entry={nativeId:0,cleared:false};
  const runner=()=>{
    if(entry.cleared) return;
    if(isGameplayPaused()){
      entry.nativeId=__nativeSetTimeout(runner,16);
      return;
    }
    __pauseAwareTimeouts.delete(id);
    handler(...args);
  };
  entry.nativeId=__nativeSetTimeout(runner,timeout);
  __pauseAwareTimeouts.set(id,entry);
  return id;
};

window.clearTimeout=id=>{
  const entry=__pauseAwareTimeouts.get(id);
  if(entry){
    entry.cleared=true;
    __nativeClearTimeout(entry.nativeId);
    __pauseAwareTimeouts.delete(id);
    return;
  }
  __nativeClearTimeout(id);
};

window.setInterval=(handler,timeout=0,...args)=>{
  if(typeof handler!=='function') return __nativeSetInterval(handler,timeout,...args);
  const id=++__pauseAwareTimerId;
  const nativeId=__nativeSetInterval(()=>{
    if(isGameplayPaused()) return;
    handler(...args);
  },timeout);
  __pauseAwareIntervals.set(id,nativeId);
  return id;
};

window.clearInterval=id=>{
  const nativeId=__pauseAwareIntervals.get(id);
  if(nativeId!==undefined){
    __nativeClearInterval(nativeId);
    __pauseAwareIntervals.delete(id);
    return;
  }
  __nativeClearInterval(id);
};

