// ══════════════════════════════════════════
// CANVAS SETUP
// ══════════════════════════════════════════
function resizeCanvases(){
  if(!area) return;
  [els.pCanvas,els.swCanvas].forEach(c=>{
    if(!c) return;
    c.width=area.clientWidth;
    c.height=area.clientHeight;
  });
}
function syncUILayoutMetrics(){
  const headerHeight=document.getElementById('main-header')?.offsetHeight||78;
  document.documentElement.style.setProperty('--header-height',`${headerHeight}px`);
}
window.addEventListener('resize',()=>{
  resizeCanvases();
  syncUILayoutMetrics();
  if(els.fusionChargeCvs){els.fusionChargeCvs.width=area.clientWidth;els.fusionChargeCvs.height=area.clientHeight;}
  if(mode==='puzzle')buildWalls(puzzleLevel);
});
resizeCanvases();
syncUILayoutMetrics();
window.addEventListener('load',syncUILayoutMetrics);

// ══════════════════════════════════════════
// PARTICLES
// ══════════════════════════════════════════
function spawnParticles(x,y,color,n=40,speed=5){
  for(let i=0;i<n;i++){
    const a=Math.random()*Math.PI*2,spd=Math.random()*speed+1;
    particles.push({x,y,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,r:Math.random()*4+1.5,life:1,decay:Math.random()*.03+.01,color});
  }
}
function spawnSparks(x,y,color,n=12){
  for(let i=0;i<n;i++){
    const a=Math.random()*Math.PI*2,spd=Math.random()*8+3;
    particles.push({x,y,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,r:Math.random()*2+1,life:1,decay:.04+Math.random()*.04,color,spark:true});
  }
}

function updateParticles(){
  if(!els.pCanvas) return;
  const ctx=els.pCanvas.getContext('2d');
  ctx.clearRect(0,0,els.pCanvas.width,els.pCanvas.height);
  particles=particles.filter(p=>{
    p.x+=p.vx;p.y+=p.vy;p.vy+=p.spark?.06:.13;p.vx*=.97;p.life-=p.decay;
    if(p.life<=0)return false;
    ctx.save();ctx.globalAlpha=p.life;
    ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
    ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=p.spark?14:8;ctx.fill();
    ctx.restore();return true;
  });
}

// ══════════════════════════════════════════
// SHOCKWAVES
// ══════════════════════════════════════════
let _lastSwSfx=0;
function spawnShockwave(x,y,color='rgba(255,180,50,',maxR=250,speed=6){
  shockwaves.push({x,y,r:0,maxR,speed,color,life:1});
  const now=Date.now();
  if(now-_lastSwSfx>320){_lastSwSfx=now;SFX.shockwave();}
}

function updateShockwaves(){
  if(!els.swCanvas) return;
  const ctx=els.swCanvas.getContext('2d');
  ctx.clearRect(0,0,els.swCanvas.width,els.swCanvas.height);
  shockwaves=shockwaves.filter(sw=>{
    sw.r+=sw.speed;sw.life=1-sw.r/sw.maxR;
    if(sw.life<=0)return false;
    ctx.save();
    ctx.beginPath();ctx.arc(sw.x,sw.y,sw.r,0,Math.PI*2);
    ctx.strokeStyle=sw.color+sw.life*.8+')';
    ctx.lineWidth=3+sw.life*4;
    ctx.shadowColor=sw.color+'0.6)';ctx.shadowBlur=15;
    ctx.stroke();ctx.restore();
    return true;
  });
  // Knock circles if shockwave from boss hits them
  if(bossAlive){
    shockwaves.forEach(sw=>{
      if(sw.fromBoss){
        [els.red,els.blue,els.green].forEach(e=>{
          if(!e) return;
          if(e.classList.contains('fading'))return;
          const c=getCenter(e);
          const d=Math.hypot(c.x-sw.x,c.y-sw.y);
          if(Math.abs(d-sw.r)<30){
            const ang=Math.atan2(c.y-sw.y,c.x-sw.x);
            const force=25;
            let px=parseFloat(e.style.left)||0,py=parseFloat(e.style.top)||0;
            px+=Math.cos(ang)*force;py+=Math.sin(ang)*force;
            px=Math.max(0,Math.min(cW()-R*2,px));
            py=Math.max(0,Math.min(cH()-R*2,py));
            e.classList.add('knocked');
            setPos(e,px,py);
            setTimeout(()=>e.classList.remove('knocked'),350);
          }
        });
      }
    });
  }
}

// ══════════════════════════════════════════
// UTILS
// ══════════════════════════════════════════
function getCenter(e){const ar=area.getBoundingClientRect(),r=e.getBoundingClientRect();return{x:r.left+r.width/2-ar.left,y:r.top+r.height/2-ar.top,rad:r.width/2}}
function isTouching(a,b){const ca=getCenter(a),cb=getCenter(b);return Math.hypot(ca.x-cb.x,ca.y-cb.y)<ca.rad+cb.rad+6}
function setPos(e,x,y){e.style.left=x+'px';e.style.top=y+'px'}
function getPos(e){return{x:parseFloat(e.style.left)||0,y:parseFloat(e.style.top)||0}}
function cW(){return area.clientWidth}function cH(){return area.clientHeight}

function resetPositions(){
  const w=cW(), h=cH();
  if(w<10||h<10){
    // Layout not ready yet — retry after paint
    requestAnimationFrame(resetPositions);
    return;
  }
  [els.red,els.blue,els.green].forEach((e,i)=>{
    const cx=w/2, cy=h/2;
    setPos(e,cx+startOffsets[i].dx-R, cy+startOffsets[i].dy-R);
    e.classList.remove('fading','hidden','knocked');
    ['opacity','transform','pointerEvents','transition','zIndex'].forEach(p=>e.style[p]='');
  });
  gravVels=[{x:0,y:0},{x:0,y:0},{x:0,y:0}];
}

function hideGold(){
  clearDiamondFusionSequence();
  if(orbPersonalityTimer){clearInterval(orbPersonalityTimer);orbPersonalityTimer=null;}
  clearGoldSkinAmbient();
  els.gold.classList.remove('visible');els.gold.style.pointerEvents='none';
  els.gold.dataset.perfect='0';
  els.gold.dataset.specialFusion='';
  els.gold.dataset.diamond='0';
  els.gold.onclick=null;
  els.gold.style.marginTop='';
  els.gold.style.animation='';
  els.gold.style.filter='';
  els.orbText.style.color='';
  els.orbIcon.style.color='';
  els.hole.classList.remove('visible');els.hole.style.boxShadow='';
  els.ring.classList.remove('show');
  blackHoleActive=false;
}

function setStatus(txt,cls=''){
  if(!els.status) return;
  els.status.textContent=txt;
  els.status.className=cls;
}
function setPips(rb,bg,rg){
  els.pr?.classList.toggle('active',rb||rg);
  els.pb?.classList.toggle('active',rb||bg);
  els.pg?.classList.toggle('active',bg||rg);
}

function flashScreen(color='rgba(255,220,80,.38)',duration=160){
  if(!els.flash) return;
  els.flash.style.background=color;
  els.flash.classList.add('pop');
  setTimeout(()=>els.flash.classList.remove('pop'),duration);
}

function shake(level='sm'){
  document.body.classList.add('shake-'+level);
  setTimeout(()=>document.body.classList.remove('shake-'+level),level==='lg'?750:level==='md'?520:370);
}

function showMsg(title,sub,color='var(--gold)'){
  if(!els.fusionTitle||!els.fusionSub||!els.fusionMsg) return;
  els.fusionTitle.textContent=title;els.fusionSub.textContent=sub;
  els.fusionTitle.style.color=color;
  els.fusionMsg.classList.add('show');setTimeout(()=>els.fusionMsg.classList.remove('show'),2400);
}

function toast(txt,color='var(--gold)'){
  const t=document.createElement('div');t.className='discovery-toast';
  t.style.color=color;t.style.borderColor=color;t.textContent=txt;
  (els.discoveryLog||document.body).appendChild(t);setTimeout(()=>t.remove(),2800);
}

function forceHideOperationsUI(){
  if(typeof OPS!=='undefined'&&OPS&&typeof OPS.hide==='function'){
    OPS.hide({restore:false});
    return;
  }
  if(els.opsOverlay) els.opsOverlay.classList.remove('show');
  document.getElementById('ops-btn')?.classList.remove('active');
}

function forceHideAdventureUI(){
  advActive=false;
  ['adv-overlay','adv-map','adv-earth-hub','adv-mars-hub','adv-launch-screen','adv-mission-complete'].forEach(id=>{
    const node=document.getElementById(id);
    if(node) node.style.display='none';
  });
  document.body.classList.remove('adv-mars-bg');
}

function forceHideInfiniteFusionUI(){
  IFUSION.exit();
}

