const ACHIEVEMENT_DEFS=[
  {id:'ach_first_fusion',title:'Alchemy Online',hint:'Complete your first fusion.',desc:'Bring the three base elements into a stable gold convergence.',check:s=>s.stats.fusions>=1,reward:6},
  {id:'ach_perfect_fusion',title:'Precision Core',hint:'Trigger a Perfect Fusion.',desc:'Achieve a tightly aligned RGB convergence.',check:s=>s.stats.perfectFusions>=1,reward:8},
  {id:'ach_anomaly_hunter',title:'Anomaly Hunter',hint:'Trigger any rare event.',desc:'Witness a diamond, meltdown, or black hole event.',check:s=>s.stats.rareEvents>=1,reward:8},
  {id:'ach_archive_5',title:'Archive Uplink',hint:'Unlock five discoveries.',desc:'Push the discovery archive beyond the initial research tier.',check:s=>Object.keys(s.discoveries).length>=5,reward:10},
  {id:'ach_boss_clear',title:'Threat Neutralized',hint:'Defeat a boss.',desc:'Destroy a boss-class orb and record the kill.',check:s=>s.stats.bossesDefeated>=1,reward:12},
  {id:'ach_mission_clear',title:'Directive Complete',hint:'Complete a mission.',desc:'Finish one of the new optional Operations directives.',check:s=>s.stats.missionsCompleted>=1,reward:8},
  {id:'ach_fusion_archive_10',title:'Signal Collector',hint:'Discover 10 Fusion Library entries.',desc:'Log ten separate fusion signatures inside the sandbox library.',check:s=>(s.stats.fusionLibraryDiscoveries||0)>=10,reward:10},
  {id:'ach_fusion_legendary',title:'Legendary Transmutation',hint:'Discover a Legendary or Mythic sandbox fusion.',desc:'Register a top-tier fusion signal in the new Fusion Library.',check:s=>(s.stats.fusionLegendary||0)>=1,reward:14},
  {id:'ach_fusion_events_5',title:'Event Horizon',hint:'Trigger five Fusion Events.',desc:'Overload the sandbox often enough to reach a full event chain.',check:s=>(s.stats.fusionEvents||0)>=5,reward:14},
  {id:'ach_fusion_mutation',title:'Unstable Genome',hint:'Witness a fusion mutation.',desc:'Capture a mutated fusion signal that should not exist in the normal chain.',check:s=>(s.stats.fusionMutations||0)>=1,reward:14},
];
const MISSION_DEFS=[
  {id:'mission_fusions',title:'Fusion Cadet',desc:'Complete 5 successful fusions.',goal:5,event:'fusions',reward:10},
  {id:'mission_discoveries',title:'Archive Sweep',desc:'Unlock 4 discoveries.',goal:4,event:'discoveries',reward:12},
  {id:'mission_rare',title:'Anomaly Sweep',desc:'Trigger 1 rare anomaly event.',goal:1,event:'rareEvents',reward:14},
  {id:'mission_triple_gold',title:'Crown Protocol',desc:'Discover a triple-gold fusion result by converging three disguised gold base orbs.',goal:1,event:'tripleGoldDiscoveries',reward:18},
  {id:'mission_boss',title:'Combat Validation',desc:'Defeat 1 boss-tier entity.',goal:1,event:'bossesDefeated',reward:16},
];
const UPGRADE_DEFS=[
  {id:'scan_array',title:'Scan Array',desc:'Increases research data from discoveries, achievements, and missions by 15% per level.',max:3,cost:[12,20,30]},
  {id:'archive_sync',title:'Archive Sync',desc:'Improves the quality of unlocked archive notes and active focus hints.',max:2,cost:[18,28]},
  {id:'logistics_link',title:'Logistics Link',desc:'Stages support bonuses for future Arena, Mutation Lab, and Build/Test systems.',max:3,cost:[16,26,38]},
];
function metaDefaultState(){
  return {discoveries:{},achievements:{},missions:{},upgrades:{scan_array:0,archive_sync:0,logistics_link:0},console:[],researchData:0,skins:{unlocked:{default:true,gold_default:true},equipped:{red:'default',green:'default',blue:'default',gold:'gold_default'}},admin:{missionBossesUnlocked:false},stats:{fusions:0,perfectFusions:0,rareEvents:0,discoveries:0,bossesDefeated:0,missionsCompleted:0,adventureLaunches:0,orbFightWins:0,orbFightMissionClears:0,orbFightMissionBossClears:0,orbFightMissionFinalClears:0,fusionLibraryDiscoveries:0,fusionLegendary:0,fusionEvents:0,fusionMutations:0,tripleGoldDiscoveries:0}};
}
function metaLoad(){
  try{
    const raw=localStorage.getItem(META_KEY);
    if(!raw)return metaDefaultState();
    const saved=JSON.parse(raw),base=metaDefaultState();
    return {...base,...saved,discoveries:{...base.discoveries,...(saved.discoveries||{})},achievements:{...base.achievements,...(saved.achievements||{})},missions:{...base.missions,...(saved.missions||{})},upgrades:{...base.upgrades,...(saved.upgrades||{})},skins:{...base.skins,...(saved.skins||{}),unlocked:{...base.skins.unlocked,...((saved.skins&&saved.skins.unlocked)||{})},equipped:{...base.skins.equipped,...((saved.skins&&saved.skins.equipped)||{})}},admin:{...base.admin,...(saved.admin||{})},stats:{...base.stats,...(saved.stats||{})},console:Array.isArray(saved.console)?saved.console.slice(0,40):[]};
  }catch(e){return metaDefaultState();}
}
let metaState=metaLoad();
function metaSave(){try{localStorage.setItem(META_KEY,JSON.stringify(metaState));}catch(e){}}
function metaRewardMultiplier(){return 1+(metaState.upgrades.scan_array||0)*0.15;}
function metaGrantData(amount,reason='Research data updated'){
  if(!amount)return;
  const gained=Math.max(1,Math.round(amount*metaRewardMultiplier()));
  metaState.researchData+=gained;
  metaConsole('DATA',`${reason} +${gained} RD`,'#7fd1ff');
}
function metaConsole(tag,msg,color='#7fd1ff'){
  const stamp=new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});
  metaState.console.unshift({tag,msg,color,stamp});
  metaState.console=metaState.console.slice(0,40);
  metaSave();
  if(OPS.initialized)OPS.renderConsole();
}
function metaNotify(kind,title,detail,color='#7fd1ff'){
  toast(`${kind} ${title}`,color);
  metaConsole((kind||'SYS').replace(/[^A-Z]/gi,'').slice(0,8)||'SYS',`${title} — ${detail}`,color);
}
function metaUnlockDiscovery(id,detailOverride=''){
  if(metaState.discoveries[id])return false;
  const def=DISCOVERY_DEFS.find(d=>d.id===id);
  if(!def)return false;
  metaState.discoveries[id]={at:Date.now()};
  metaState.stats.discoveries=Object.keys(metaState.discoveries).length;
  metaGrantData(def.reward||4,'Discovery logged');
  metaNotify('NEW DISCOVERY',def.title,detailOverride||def.desc,def.color||'#7fd1ff');
  metaUpdateMissionProgress('discoveries',1);
  metaEvaluateAchievements();
  metaSave();
  SKINS.syncUnlocks();
  if(SKINS.active)SKINS.render();
  if(OPS.initialized)OPS.renderAll();
  return true;
}
function metaUnlockAchievement(id){
  if(metaState.achievements[id])return false;
  const def=ACHIEVEMENT_DEFS.find(a=>a.id===id);
  if(!def)return false;
  metaState.achievements[id]={at:Date.now()};
  metaGrantData(def.reward||6,'Achievement unlocked');
  metaNotify('ACHIEVEMENT',def.title,def.desc,'#f5c842');
  metaSave();
  SKINS.syncUnlocks();
  if(SKINS.active)SKINS.render();
  if(OPS.initialized)OPS.renderAll();
  return true;
}
function metaEvaluateAchievements(){ACHIEVEMENT_DEFS.forEach(def=>{if(!metaState.achievements[def.id]&&def.check(metaState))metaUnlockAchievement(def.id);});}
function metaUpdateMissionProgress(eventId,delta=1){
  MISSION_DEFS.forEach(def=>{
    if(def.event!==eventId)return;
    const curr=metaState.missions[def.id]||{progress:0,completed:false,claimedAt:0};
    if(curr.completed)return;
    curr.progress=Math.min(def.goal,curr.progress+delta);
    if(curr.progress>=def.goal){
      curr.completed=true;curr.claimedAt=Date.now();
      metaState.stats.missionsCompleted+=1;
      metaGrantData(def.reward||10,'Mission completed');
      metaNotify('MISSION',def.title,def.desc,'#88ffaa');
    }
    metaState.missions[def.id]=curr;
  });
  metaEvaluateAchievements();metaSave();if(OPS.initialized)OPS.renderAll();
}
function metaTrack(eventId,delta=1){
  metaState.stats[eventId]=(metaState.stats[eventId]||0)+delta;
  metaUpdateMissionProgress(eventId,delta);
  metaEvaluateAchievements();
  metaSave();
  SKINS.syncUnlocks();
  if(SKINS.active)SKINS.render();
  if(OPS.initialized)OPS.renderSummary();
}
const OPS={
  active:false,initialized:false,currentTab:'overview',returnMode:null,
  init(){
    if(this.initialized)return;
    if(els.opsOverlay&&els.opsOverlay.parentElement!==document.body){
      document.body.appendChild(els.opsOverlay);
    }
    this.initialized=true;
    this.renderAll();
  },
  syncLayout(){
    const header=document.getElementById('main-header');
    const topOffset=header?header.offsetHeight:78;
    document.documentElement.style.setProperty('--ops-top-offset',`${topOffset}px`);
  },
  show(){
    this.init();
    this.syncLayout();
    this.returnMode=lastNonOpsMode||mode||'fusion';
    this.active=true;
    els.opsOverlay?.classList.add('show');
    document.getElementById('ops-btn')?.classList.add('active');
    this.renderAll();
  },
  restoreContext(){
    const target=this.returnMode||lastNonOpsMode||mode||'fusion';
    this.returnMode=null;
    if(!target) return;
    if(mode!==target){
      setMode(target);
      return;
    }
    if(target==='adventure'&&!advActive){
      advEnter();
      return;
    }
    if(target==='orbfight'&&!(typeof OF!=='undefined'&&OF&&OF.active)){
      orbFightEnter();
      return;
    }
    if(target==='ifusion'&&!(typeof IFUSION!=='undefined'&&IFUSION&&IFUSION.active)){
      IFUSION.enter();
      return;
    }
    if(target==='creator'&&!(typeof CREATOR!=='undefined'&&CREATOR&&CREATOR.active)){
      CREATOR.enter();
      return;
    }
    if(target==='fusion'&&typeof FUSION_MODE!=='undefined'&&FUSION_MODE&&!el('fusion-overlay')?.classList.contains('show')){
      FUSION_MODE.enter();
    }
  },
  hide({restore=true}={}){
    this.active=false;
    els.opsOverlay?.classList.remove('show');
    document.getElementById('ops-btn')?.classList.remove('active');
    if(restore) this.restoreContext();
    else this.returnMode=null;
  },
  toggle(){this.active?this.hide():this.show();},
  switchTab(tab){this.currentTab=tab;document.querySelectorAll('.ops-tab').forEach(btn=>btn.classList.toggle('active',btn.dataset.tab===tab));document.querySelectorAll('.ops-view').forEach(panel=>panel.style.display=panel.dataset.view===tab?'block':'none');},
  seedIntel(){metaConsole('SCAN','Seed intel generated. Ops hub telemetry is online.','#7fd1ff');metaConsole('AI','Recommended targets: Perfect Fusion, Diamond Fusion, Golden Crown, Boss Signal.','#a8d8ff');if(this.initialized)this.renderConsole();},
  clearConsole(){metaState.console=[];metaSave();this.renderConsole();},
  buyUpgrade(id){const def=UPGRADE_DEFS.find(u=>u.id===id);if(!def)return;const lvl=metaState.upgrades[id]||0;if(lvl>=def.max){toast('Upgrade already maxed','#88ffaa');return;}const cost=def.cost[lvl]||def.cost[def.cost.length-1]||999;const free=typeof adminPanelHasFreePurchases==='function'&&adminPanelHasFreePurchases();if(!free&&metaState.researchData<cost){toast('Not enough Research Data','#ff8866');return;}if(!free) metaState.researchData-=cost;metaState.upgrades[id]=lvl+1;metaConsole('UPGRADE',`${def.title} upgraded to level ${lvl+1}${free?' (FREE)':''}.`,'#88ffaa');metaSave();this.renderAll();},
  renderSummary(){const discCount=Object.keys(metaState.discoveries).length;const achCount=Object.keys(metaState.achievements).length;const completedMissions=Object.values(metaState.missions).filter(m=>m&&m.completed).length;const activeMissions=MISSION_DEFS.length-completedMissions;el('ops-stat-discoveries').textContent=`${discCount} / ${DISCOVERY_DEFS.length}`;el('ops-stat-discoveries-sub').textContent=discCount?`${Math.round(discCount/DISCOVERY_DEFS.length*100)}% archive recovered`:'Archive offline';el('ops-stat-achievements').textContent=`${achCount} / ${ACHIEVEMENT_DEFS.length}`;el('ops-stat-achievements-sub').textContent=achCount?`${ACHIEVEMENT_DEFS.length-achCount} milestones remaining`:'Milestones pending';el('ops-stat-data').textContent=`${metaState.researchData} RD`;el('ops-stat-data-sub').textContent='Spend on support upgrades';el('ops-stat-missions').textContent=`${completedMissions} / ${MISSION_DEFS.length}`;el('ops-stat-missions-sub').textContent=activeMissions?`${activeMissions} directives still active`:'All directives complete';},
  renderDiscoveries(){const grid=el('ops-discoveries-grid');if(!grid)return;grid.innerHTML=DISCOVERY_DEFS.map(def=>{const unlocked=!!metaState.discoveries[def.id];return `<div class="ops-card ${unlocked?'':'locked'}" data-ops-kind="discovery" data-ops-id="${def.id}"><div class="ops-card-heading"><div class="ops-card-name">${unlocked?def.title:'LOCKED SIGNAL'}</div><div class="ops-card-tier">${def.category}</div></div><div class="ops-card-desc">${unlocked?def.desc:def.hint}</div><div class="ops-card-meta">${unlocked?`Recovered • +${def.reward||0} RD`:'Undiscovered'}</div></div>`;}).join('');},
  renderEncyclopedia(){const grid=el('ops-encyclopedia-grid');if(!grid)return;grid.innerHTML=ENCYCLOPEDIA_DEFS.map(def=>{const unlocked=!def.unlock||!!metaState.discoveries[def.unlock];return `<div class="ops-card ${unlocked?'':'locked'}" data-ops-kind="encyclopedia" data-ops-id="${def.id}"><div class="ops-card-heading"><div class="ops-card-name">${unlocked?def.title:'REDACTED ENTRY'}</div><div class="ops-card-tier">${def.type}</div></div><div class="ops-card-desc">${unlocked?`${def.desc}<br><br><span style="color:rgba(255,235,180,.75)">${def.stats}</span>`:`Unlock via discovery: ${DISCOVERY_DEFS.find(d=>d.id===def.unlock)?.title||'Unknown signal'}`}</div><div class="ops-card-meta">${unlocked?`${def.origin}`:'Archive lock engaged'}</div></div>`;}).join('');},
  renderMissions(){const list=el('ops-missions-list');if(!list)return;list.innerHTML=MISSION_DEFS.map(def=>{const s=metaState.missions[def.id]||{progress:0,completed:false};const pct=Math.round((Math.min(def.goal,s.progress)/def.goal)*100);return `<div class="ops-row" data-ops-kind="mission" data-ops-id="${def.id}"><div class="ops-row-main"><div class="ops-row-title">${def.title}</div><div class="ops-row-desc">${def.desc}</div><div class="ops-progress"><div class="ops-progress-fill" style="width:${pct}%"></div></div></div><div class="ops-row-side">${s.completed?'Complete':`${Math.min(def.goal,s.progress)}/${def.goal}`}</div></div>`;}).join('');},
  renderAchievements(){const grid=el('ops-achievements-grid');if(!grid)return;grid.innerHTML=ACHIEVEMENT_DEFS.map(def=>{const unlocked=!!metaState.achievements[def.id];return `<div class="ops-card ${unlocked?'':'locked'}" data-ops-kind="achievement" data-ops-id="${def.id}"><div class="ops-card-heading"><div class="ops-card-name">${unlocked?def.title:'LOCKED MILESTONE'}</div><div class="ops-card-tier">Achievement</div></div><div class="ops-card-desc">${unlocked?def.desc:def.hint}</div><div class="ops-card-meta">${unlocked?`Unlocked • +${def.reward||0} RD`:'Pending'}</div></div>`;}).join('');},
  renderUpgrades(){const list=el('ops-upgrades-list');if(!list)return;list.innerHTML=UPGRADE_DEFS.map(def=>{const lvl=metaState.upgrades[def.id]||0;const atMax=lvl>=def.max;const cost=def.cost[lvl]||def.cost[def.cost.length-1]||0;const free=typeof adminPanelHasFreePurchases==='function'&&adminPanelHasFreePurchases();return `<div class="ops-row" data-ops-kind="upgrade" data-ops-id="${def.id}"><div class="ops-row-main"><div class="ops-upgrade-row"><div class="ops-row-title">${def.title}</div><div class="ops-upgrade-level">Lv ${lvl}/${def.max}</div></div><div class="ops-row-desc">${def.desc}</div></div><div class="ops-row-side">${atMax?'MAX':'<button class="ops-action-btn" onclick="OPS.buyUpgrade(\''+def.id+'\')">'+(free?'FREE':(cost+' RD'))+'</button>'}</div></div>`;}).join('');},
  renderConsole(){const feed=el('ops-console-feed');if(!feed)return;feed.innerHTML=metaState.console.length?metaState.console.map(entry=>`<div class="ops-console-entry" style="border-left-color:${entry.color||'#7fd1ff'}"><div class="ops-console-time">${entry.stamp} • ${entry.tag}</div><div class="ops-console-text">${entry.msg}</div></div>`).join(''):'<div class="ops-empty">No system messages yet. Discover something strange.</div>';},
  renderFocus(){const list=el('ops-focus-list');if(!list)return;const remainingMission=MISSION_DEFS.find(def=>!(metaState.missions[def.id]&&metaState.missions[def.id].completed));const nextDiscovery=DISCOVERY_DEFS.find(def=>!metaState.discoveries[def.id]);const scans=[];if(remainingMission)scans.push({title:'Mission Focus',desc:remainingMission.desc,side:'Directive'});if(nextDiscovery)scans.push({title:'Research Lead',desc:nextDiscovery.hint,side:nextDiscovery.category});scans.push({title:'Fusion Signals',desc:'Secret triple-gold convergence paths are now present in the archive ladder.',side:'Active'});list.innerHTML=scans.map(item=>`<div class="ops-row"><div class="ops-row-main"><div class="ops-row-title">${item.title}</div><div class="ops-row-desc">${item.desc}</div></div><div class="ops-row-side">${item.side}</div></div>`).join('');},
  renderAll(){this.renderSummary();this.renderDiscoveries();this.renderEncyclopedia();this.renderMissions();this.renderAchievements();this.renderUpgrades();this.renderConsole();this.renderFocus();this.switchTab(this.currentTab);},
};

