const SKINS={
  active:false,
  currentOrb:'red',
  allDefs(){ return [...SKIN_DEFS,...GOLD_SKIN_DEFS]; },
  defsForOrb(orb){ return orb==='gold'?GOLD_SKIN_DEFS:SKIN_DEFS; },
  init(){
    this.ensureState();
    this.syncUnlocks();
    this.applyAll();
    this.bindMenuShell();
  },
  ensureState(){
    if(!metaState.skins) metaState.skins=metaDefaultState().skins;
    metaState.skins.unlocked=metaState.skins.unlocked||{default:true,gold_default:true};
    metaState.skins.unlocked.default=true;
    metaState.skins.unlocked.gold_default=true;
    metaState.skins.equipped={red:'default',green:'default',blue:'default',gold:'gold_default',...(metaState.skins.equipped||{})};
    ['red','green','blue','gold'].forEach(orb=>{
      const defs=this.defsForOrb(orb);
      const fallback=orb==='gold'?'gold_default':'default';
      if(!defs.some(def=>def.id===metaState.skins.equipped[orb])||!metaState.skins.unlocked[metaState.skins.equipped[orb]]) metaState.skins.equipped[orb]=fallback;
    });
  },
  bindMenuShell(){
    const menu=el('skin-menu');
    if(menu&&!menu.dataset.bound){
      menu.dataset.bound='1';
      menu.addEventListener('click',e=>{ if(e.target===menu) this.hide(); });
    }
  },
  toggle(){ this.active?this.hide():this.show(); },
  show(){
    this.syncUnlocks();
    this.active=true;
    el('skin-menu')?.classList.add('show');
    el('skins-btn')?.classList.add('active');
    this.render();
  },
  hide(){
    this.active=false;
    el('skin-menu')?.classList.remove('show');
    el('skins-btn')?.classList.remove('active');
  },
  switchOrb(orb){
    this.currentOrb=orb;
    this.render();
  },
  getThemeClass(orb){ return orb==='gold'?'orb-theme-gold':`orb-theme-${orb}`; },
  getUnlockedCount(){ return this.allDefs().filter(def=>!!metaState.skins.unlocked[def.id]).length; },
  isUnlocked(id){ return !!metaState.skins.unlocked[id]; },
  getGoldSkin(id){ return GOLD_SKIN_DEFS.find(def=>def.id===id)||GOLD_SKIN_DEFS[0]; },
  getEquippedGoldSkinId(){ return metaState.skins.equipped.gold||'gold_default'; },
  syncUnlocks(){
    this.ensureState();
    let changed=false;
    this.allDefs().forEach(def=>{
      if(def.unlock==='free'&&!metaState.skins.unlocked[def.id]){metaState.skins.unlocked[def.id]=true;changed=true;}
      if(def.unlock==='condition'&&def.requirement&&def.requirement()&&!metaState.skins.unlocked[def.id]){
        metaState.skins.unlocked[def.id]=true;
        metaNotify('SKIN UNLOCKED',def.title,def.desc,def.id==='prismatic'?'#ff79c6':def.id==='gold_diamond'?'#aeefff':'#88ddff');
        changed=true;
      }
    });
    if(changed){
      this.ensureState();
      metaSave();
    }
  },
  prismaticMarkup(){
    return `<div class="prismatic-fx"><div class="prismatic-core"></div><div class="prismatic-rings"><span class="prismatic-ring" style="--size:94;--h:214;--dur:5.8s;--delay:-.2s;--angle:0deg"></span><span class="prismatic-ring dashed" style="--size:126;--h:276;--dur:7.4s;--delay:-1.4s;--angle:22deg"></span><span class="prismatic-ring inner" style="--size:66;--h:38;--dur:4.4s;--delay:-.8s;--angle:-16deg"></span></div><div class="prismatic-crystals"><span class="prismatic-crystal" style="--size:9;--h:334;--dur:3.9s;--delay:-.4s;--angle:0deg;--dist:34%"></span><span class="prismatic-crystal" style="--size:8;--h:36;--dur:4.7s;--delay:-1.1s;--angle:60deg;--dist:31%"></span><span class="prismatic-crystal" style="--size:7;--h:96;--dur:5.2s;--delay:-2s;--angle:120deg;--dist:33%"></span><span class="prismatic-crystal" style="--size:8;--h:160;--dur:4.3s;--delay:-.7s;--angle:180deg;--dist:32%"></span><span class="prismatic-crystal" style="--size:7;--h:214;--dur:5.5s;--delay:-1.8s;--angle:240deg;--dist:34%"></span><span class="prismatic-crystal" style="--size:9;--h:282;--dur:4.1s;--delay:-2.6s;--angle:300deg;--dist:30%"></span></div><div class="prismatic-flash"></div></div>`;
  },
  goldSkinMarkup(id){
    if(id==='gold_sunforge') return `<div class="gold-skin-fx-inner"><div class="gold-skin-halo"></div><div class="gold-skin-flare"></div><div class="gold-skin-ring"></div><span class="gold-skin-spark" style="--angle:0deg;--dist:42%;--dur:2.4s"></span><span class="gold-skin-spark" style="--angle:120deg;--dist:38%;--dur:2.8s;--delay:-1s"></span><span class="gold-skin-spark" style="--angle:240deg;--dist:40%;--dur:2.2s;--delay:-1.6s"></span></div>`;
    if(id==='gold_royal') return `<div class="gold-skin-fx-inner"><div class="gold-skin-crown"></div><div class="gold-skin-ring"></div><div class="gold-skin-ring inner"></div><span class="gold-skin-spark" style="--angle:40deg;--dist:44%;--dur:3.1s"></span><span class="gold-skin-spark" style="--angle:180deg;--dist:36%;--dur:2.7s;--delay:-1.1s"></span><span class="gold-skin-spark" style="--angle:300deg;--dist:42%;--dur:3.4s;--delay:-2s"></span></div>`;
    if(id==='gold_diamond') return `<div class="gold-skin-fx-inner"><div class="gold-skin-diamond-halo"></div><div class="gold-skin-ring"></div><span class="gold-skin-shard" style="--angle:0deg;--dist:34%;--dur:3.8s"></span><span class="gold-skin-shard" style="--angle:72deg;--dist:31%;--dur:4.6s;--delay:-1s"></span><span class="gold-skin-shard" style="--angle:144deg;--dist:33%;--dur:4.2s;--delay:-1.6s"></span><span class="gold-skin-shard" style="--angle:216deg;--dist:30%;--dur:4.8s;--delay:-.8s"></span><span class="gold-skin-shard" style="--angle:288deg;--dist:32%;--dur:3.9s;--delay:-2s"></span></div>`;
    if(id==='gold_nova') return `<div class="gold-skin-fx-inner"><div class="gold-skin-halo"></div><div class="gold-skin-flare"></div><div class="gold-skin-ring inner"></div></div>`;
    if(id==='gold_void') return `<div class="gold-skin-fx-inner"><div class="gold-skin-rune"></div><div class="gold-skin-ring inner"></div><span class="gold-skin-spark" style="--angle:20deg;--dist:40%;--dur:3.4s"></span><span class="gold-skin-spark" style="--angle:200deg;--dist:36%;--dur:4.1s;--delay:-1.2s"></span></div>`;
    return '';
  },
  getPreviewMarkup(orb,id){
    return orb==='gold'?this.goldSkinMarkup(id):(id==='prismatic'?this.prismaticMarkup():'');
  },
  getGoldSkinStyle(id,perfect=false){
    if(id==='gold_sunforge') return {background:'radial-gradient(circle at 34% 24%,#fff8da 0%,#ffd56f 22%,#ff962d 52%,#772600 100%)',boxShadow:perfect?'0 0 110px 48px rgba(255,214,120,.9),0 0 220px 92px rgba(255,120,40,.55),inset 0 2px 0 rgba(255,255,255,.72)':'0 0 76px 28px rgba(255,196,94,.76),0 0 150px 68px rgba(255,120,40,.38),inset 0 2px 0 rgba(255,255,255,.56)',filter:'saturate(1.08)'};
    if(id==='gold_royal') return {background:'radial-gradient(circle at 34% 24%,#fff3c5 0%,#ffd161 18%,#8d5dff 56%,#241038 100%)',boxShadow:'0 0 78px 28px rgba(255,214,110,.66),0 0 160px 72px rgba(148,96,255,.34),inset 0 2px 0 rgba(255,255,255,.58)',filter:'saturate(1.05)'};
    if(id==='gold_diamond') return {background:'radial-gradient(circle at 32% 28%,#ffffff,#d8f7ff 26%,#97e2ff 52%,#1588c6 78%,#083a61 100%)',boxShadow:'0 0 88px 34px rgba(196,244,255,.82),0 0 170px 78px rgba(120,210,255,.44),inset 0 0 42px rgba(255,255,255,.24)',filter:'saturate(1.14) brightness(1.02)'};
    if(id==='gold_nova') return {background:'radial-gradient(circle at 36% 28%,#ffffff 0%,#fff8c9 22%,#ffd96c 42%,#ff8f1c 68%,#7a2c00 100%)',boxShadow:'0 0 104px 44px rgba(255,248,184,.9),0 0 220px 104px rgba(255,186,80,.48),inset 0 2px 0 rgba(255,255,255,.76)',filter:'brightness(1.06)'};
    if(id==='gold_void') return {background:'radial-gradient(circle at 36% 28%,#fff2d5 0%,#d396ff 18%,#4d237b 52%,#0f071c 100%)',boxShadow:'0 0 82px 30px rgba(198,150,255,.68),0 0 166px 78px rgba(84,40,170,.4),inset 0 0 36px rgba(0,0,0,.28)',filter:'saturate(1.08)'};
    return {};
  },
  getGoldSkinLabel(id,perfect=false){
    if(id==='gold_sunforge') return {icon:'☀',text:'SUNFORGE',color:'rgba(96,32,0,.92)'};
    if(id==='gold_royal') return {icon:'♛',text:'ROYAL',color:'rgba(54,18,88,.95)'};
    if(id==='gold_diamond') return {icon:'💎',text:'DIAMOND',color:'rgba(200,240,255,.95)'};
    if(id==='gold_nova') return {icon:'✶',text:'NOVA',color:'rgba(100,48,0,.96)'};
    if(id==='gold_void') return {icon:'✦',text:'VOID',color:'rgba(226,205,255,.94)'};
    return perfect?{icon:'✦✦',text:'PERFECT',color:'rgba(60,30,0,.9)'}:{icon:'✦',text:'GOLD',color:'rgba(60,30,0,.9)'};
  },
  getGoldPulse(perfect=false,skinId=this.getEquippedGoldSkinId()){
    if(skinId==='gold_diamond') return 'diamond-pulse 1s ease-in-out infinite';
    if(skinId==='gold_sunforge') return 'pulse-core-over 1.2s ease-in-out infinite';
    if(skinId==='gold_royal') return 'pulse-core-quantum 1.5s ease-in-out infinite';
    if(skinId==='gold_nova') return 'pulse-core-mega 1s ease-in-out infinite';
    if(skinId==='gold_void') return 'pulse-core-sing 1.2s ease-in-out infinite';
    return perfect?'pulse-perfect 1.4s ease-in-out infinite':'pulse-gold 2.2s ease-in-out infinite';
  },
  getGoldSparkColor(skinId=this.getEquippedGoldSkinId()){
    if(skinId==='gold_diamond') return '#b7efff';
    if(skinId==='gold_sunforge') return '#ff9c3f';
    if(skinId==='gold_royal') return '#d7a8ff';
    if(skinId==='gold_nova') return '#fff1a8';
    if(skinId==='gold_void') return '#a978ff';
    return '#f5c842';
  },
  applyEquippedGoldSkin(perfect=false){
    const skinId=this.getEquippedGoldSkinId();
    const style=this.getGoldSkinStyle(skinId,perfect);
    if(Object.keys(style).length) Object.assign(els.gold.style,style);
    const label=this.getGoldSkinLabel(skinId,perfect);
    els.orbIcon.textContent=label.icon;
    els.orbText.textContent=label.text;
    els.orbIcon.style.color=label.color;
    els.orbText.style.color=label.color;
    if(els.goldSkinFx) els.goldSkinFx.innerHTML=this.goldSkinMarkup(skinId);
    startGoldSkinAmbient(skinId);
  },
  syncSkinFx(node,skinId){
    if(!node)return;
    const existing=node.querySelector('.prismatic-fx');
    if(skinId==='prismatic'){
      if(!existing) node.insertAdjacentHTML('afterbegin',this.prismaticMarkup());
    }else if(existing){
      existing.remove();
    }
  },
  syncBaseOrbLabel(orb,skinId){
    const node=els[orb];
    if(!node) return;
    const labelNode=node.querySelector('.circle-label');
    const subNode=node.querySelector('.circle-sub');
    if(!labelNode||!subNode) return;
    if(skinId===GOLD_DISGUISE_SKIN_ID){
      labelNode.textContent='GOLD';
      subNode.textContent='Gold';
      return;
    }
    const fallback=BASE_ORB_LABELS[orb];
    if(!fallback) return;
    labelNode.textContent=fallback.label;
    subNode.textContent=fallback.sub;
  },
  getBaseOrbSkinStyle(skinId){
    if(skinId===GOLD_DISGUISE_SKIN_ID){
      return {
        background:'radial-gradient(circle at 34% 22%,#fff9d8 0%,#ffe08a 18%,#e0aa2a 46%,#8c5400 100%)',
        boxShadow:'0 0 0 2px rgba(255,224,132,.24),0 0 34px rgba(245,190,70,.34),inset 0 2px 0 rgba(255,255,255,.42)',
        filter:'brightness(1.02) saturate(1.04)',
      };
    }
    return null;
  },
  applySkin(orb,skinId){
    const node=els[orb];
    if(!node)return;
    SKIN_DEFS.forEach(def=>node.classList.remove(`skin-${def.id}`));
    node.classList.add(`skin-${skinId}`);
    const inlineStyle=this.getBaseOrbSkinStyle(skinId);
    if(inlineStyle) Object.assign(node.style,inlineStyle);
    else ['background','boxShadow','filter'].forEach(prop=>node.style[prop]='');
    this.syncSkinFx(node,skinId);
    this.syncBaseOrbLabel(orb,skinId);
  },
  applyAll(){
    this.ensureState();
    ['red','green','blue'].forEach(orb=>this.applySkin(orb,metaState.skins.equipped[orb]||'default'));
  },
  buy(id){
    const def=this.allDefs().find(entry=>entry.id===id);
    if(!def||def.unlock!=='buy')return;
    if(this.isUnlocked(id)){toast('Skin already unlocked','#88ffaa');return;}
    const free=typeof adminPanelHasFreePurchases==='function'&&adminPanelHasFreePurchases();
    if(!free&&metaState.researchData<def.cost){toast('Not enough Research Data','#ff8866');return;}
    if(!free) metaState.researchData-=def.cost;
    metaState.skins.unlocked[id]=true;
    metaConsole('SKIN',`${def.title} purchased ${free?'for FREE':`for ${def.cost} RD`}.`,'#88ffaa');
    metaSave();
    if(OPS.initialized) OPS.renderSummary();
    this.render();
  },
  equip(id){
    if(!this.isUnlocked(id)){toast('Skin locked','#ff8866');return;}
    metaState.skins.equipped[this.currentOrb]=id;
    if(this.currentOrb==='gold') this.applyEquippedGoldSkin();
    else this.applySkin(this.currentOrb,id);
    metaConsole('SKIN',`${this.currentOrb.toUpperCase()} orb equipped ${this.allDefs().find(def=>def.id===id)?.title||id}.`,'#f5c842');
    metaSave();
    this.render();
  },
  unlockAll(){
    this.allDefs().forEach(def=>metaState.skins.unlocked[def.id]=true);
    metaState.skins.equipped.red='prismatic';
    metaState.skins.equipped.green='prismatic';
    metaState.skins.equipped.blue='prismatic';
    metaState.skins.equipped.gold='gold_diamond';
    this.applyAll();
    this.applyEquippedGoldSkin();
    metaConsole('ADMIN','All skins unlocked via admin override.','#ffcc66');
    metaSave();
    if(OPS.initialized) OPS.renderSummary();
    this.render();
  },
  getAction(def){
    const equipped=metaState.skins.equipped[this.currentOrb]===def.id;
    const unlocked=this.isUnlocked(def.id);
    const free=typeof adminPanelHasFreePurchases==='function'&&adminPanelHasFreePurchases();
    if(equipped) return '<button class="skin-card-btn equip" disabled>EQUIPPED</button>';
    if(unlocked) return `<button class="skin-card-btn equip" onclick="SKINS.equip('${def.id}')">EQUIP</button>`;
    if(def.unlock==='buy') return `<button class="skin-card-btn buy" onclick="SKINS.buy('${def.id}')">${free?'BUY FREE':`BUY ${def.cost} RD`}</button>`;
    return '<button class="skin-card-btn" disabled>LOCKED</button>';
  },
  getRequirementText(def){
    const requirementText=typeof def.requirementText==='function'?def.requirementText():def.requirementText;
    const free=typeof adminPanelHasFreePurchases==='function'&&adminPanelHasFreePurchases();
    if(this.isUnlocked(def.id)) return `Unlocked • ${def.tier}`;
    if(def.unlock==='buy') return free?`${def.tier} • Free in admin mode`:`${def.tier} • Costs ${def.cost} Research Data`;
    return `${def.tier} • ${requirementText||'Special unlock requirement'}`;
  },
  render(){
    this.ensureState();
    const orb=this.currentOrb;
    const defs=this.defsForOrb(orb);
    document.querySelectorAll('.skin-orb-tab').forEach(btn=>btn.classList.toggle('active',btn.dataset.orb===orb));
    ['red','green','blue','gold'].forEach(name=>{ const target=el(`skin-equipped-${name}`); if(target) target.textContent=(this.defsForOrb(name).find(def=>def.id===metaState.skins.equipped[name])?.title)||(name==='gold'?'Gold Core':'Default'); });
    if(el('skin-rd')) el('skin-rd').textContent=`${metaState.researchData} RD`;
    if(el('skin-unlocked-count')) el('skin-unlocked-count').textContent=`${this.getUnlockedCount()} / ${this.allDefs().length}`;
    if(el('skin-of-wins')) el('skin-of-wins').textContent=`${metaState.stats.orbFightWins||0}`;
    if(el('skin-fusion-count')) el('skin-fusion-count').textContent=`${metaState.stats.fusions||0}`;
    const equippedId=metaState.skins.equipped[orb]||(orb==='gold'?'gold_default':'default');
    const equippedDef=defs.find(def=>def.id===equippedId)||defs[0];
    const preview=el('skin-current-preview');
    if(preview){
      preview.className=`skin-preview ${this.getThemeClass(orb)} skin-${equippedId}`;
      preview.innerHTML=this.getPreviewMarkup(orb,equippedId);
    }
    if(el('skin-current-name')) el('skin-current-name').textContent=equippedDef.title;
    if(el('skin-current-desc')) el('skin-current-desc').textContent=equippedDef.desc;
    const list=el('skin-list');
    if(list){
      list.innerHTML=defs.map(def=>`<div class="skin-card ${this.isUnlocked(def.id)?'':'locked'}" data-skin-id="${def.id}" data-skin-orb="${orb}"><div class="skin-card-head"><div class="skin-card-title">${def.title}</div><div class="skin-card-tag">${def.tier}</div></div><div class="skin-preview-wrap"><div class="skin-preview ${this.getThemeClass(orb)} skin-${def.id}">${this.getPreviewMarkup(orb,def.id)}</div></div><div class="skin-card-desc">${def.desc}</div><div class="skin-card-req">${this.getRequirementText(def)}${def.effectText?` • ${def.effectText}`:''}</div><div class="skin-card-actions">${this.getAction(def)}</div></div>`).join('');
    }
  },
};

const TOOLTIPS={
  activeTarget:null,
  root:null,
  raf:0,
  previewRaf:0,
  previewToken:0,
  pointer:{x:0,y:0},
  init(){
    this.root=el('game-tooltip');
    if(!this.root||this._initialized)return;
    this._initialized=true;
    document.addEventListener('mousemove',e=>this.onPointerMove(e));
    document.addEventListener('mouseleave',()=>this.hide(),true);
    document.addEventListener('focusin',e=>this.onFocusIn(e),true);
    document.addEventListener('focusout',e=>this.onFocusOut(e),true);
    window.addEventListener('scroll',()=>this.hide(),true);
    window.addEventListener('resize',()=>this.hide());
  },
  escape(value){
    return String(value??'').replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[ch]));
  },
  tone(color,alpha=.18){
    if(!color) return `rgba(127,209,255,${alpha})`;
    if(color.startsWith('rgba(')) return color.replace(/rgba\(([^,]+),([^,]+),([^,]+),[^)]+\)/,`rgba($1,$2,$3,${alpha})`);
    if(color.startsWith('rgb(')) return color.replace('rgb(','rgba(').replace(')',`,`+alpha+`)`);
    if(color.startsWith('#')){
      const hex=color.slice(1);
      const full=hex.length===3?hex.split('').map(ch=>ch+ch).join(''):hex.padEnd(6,'0').slice(0,6);
      const r=parseInt(full.slice(0,2),16)||127;
      const g=parseInt(full.slice(2,4),16)||209;
      const b=parseInt(full.slice(4,6),16)||255;
      return `rgba(${r},${g},${b},${alpha})`;
    }
    return `rgba(127,209,255,${alpha})`;
  },
  stat(label,value){return {label,value};},
  payload({kicker,title,badge='',accent='#7fd1ff',sub='',stats=[],desc='',tags=[],footer='',preview=null}){
    return {kicker,title,badge,accent,sub,stats:stats.filter(item=>item&&item.value!==''&&item.value!=null),desc,tags:tags.filter(Boolean),footer,preview};
  },
  clonePreviewData(value){
    return value?JSON.parse(JSON.stringify(value)):value;
  },
  buildStaticPreview(entry,locked=false){
    const palette=(entry&&entry.palette&&entry.palette.length?entry.palette:['#ffffff','#7fd1ff','#224488']).slice(0,3);
    return {kind:'static',icon:entry?.icon||'◈',palette,locked};
  },
  buildOrbPreview(def,locked=false){
    if(!def) return null;
    return {kind:'orb',def:this.clonePreviewData(def),locked};
  },
  buildSkinPreview(orb,skinId,locked=false){
    return {kind:'skin',orb,skinId,locked};
  },
  buildFusionPreview(entry,locked=false,combat=null){
    if(combat) return this.buildOrbPreview(combat,locked);
    return this.buildStaticPreview(entry,locked);
  },
  makePreviewOrb(def){
    const radius=Math.max(34,Math.min(44,(Number(def.r)||48)*0.82));
    return {
      id:'tooltip-preview',
      type:'tooltip-preview',
      team:'blue',
      x:48,y:48,r:radius,
      hp:def.hp||1,maxHp:def.hp||1,
      dmg:def.dmg||0,spd:def.spd||0,
      color:def.color||'#7fd1ff',
      glow:def.glow||'rgba(127,209,255,',
      ability:def.ability||'basic',
      isBoss:!!def.isBoss,isInfinite:!!def.isInfinite,
      isUltimate:!!def.isUltimate,
      isPrismatic:!!def.isPrismatic,
      isCelestial:!!def.isCelestial,
      vx:0,vy:0,
      attackTimer:0,
      attackRate:def.isPrismatic?20:def.isCelestial?35:def.isBoss?60:def.isInfinite?30:90,
      pulseT:0,
      hueShift:0,
      abilityTimer:0,
      prismT:0,
      shieldHp:def.isPrismatic?100000:0,
      shieldMaxHp:def.isPrismatic?100000:0,
      shieldAngle:0,
      projectiles:[],
      dead:false,
      label:'',
      creatorConfig:def.creatorConfig?this.clonePreviewData(def.creatorConfig):null,
      fusionProfile:def.fusionProfile?this.clonePreviewData(def.fusionProfile):null,
      orbitLocked:false,
      orbitPullActive:false,orbitPullT:0,orbitCaptured:[],
    };
  },
  stopPreview(){
    if(this.previewRaf){
      cancelAnimationFrame(this.previewRaf);
      this.previewRaf=0;
    }
    this.previewToken++;
  },
  renderPreviewMarkup(preview){
    if(!preview) return '';
    if(preview.kind==='static'){
      return `<div class="tt-preview ${preview.locked?'locked':''}"><div class="tt-preview-core" style="background:radial-gradient(circle at 34% 28%,${preview.palette[0]},${preview.palette[1]} 46%,${preview.palette[2]} 100%)"><span>${this.escape(preview.icon||'◈')}</span></div></div>`;
    }
    return `<div class="tt-preview ${preview.locked?'locked':''}"><div class="tt-preview-core has-live-preview"></div></div>`;
  },
  mountPreview(preview){
    this.stopPreview();
    if(!this.root||!preview) return;
    const core=this.root.querySelector('.tt-preview-core');
    if(!core) return;
    if(preview.kind==='skin'&&typeof SKINS!=='undefined'){
      core.innerHTML=`<div class="skin-preview tt-preview-skin ${SKINS.getThemeClass(preview.orb)} skin-${preview.skinId}">${SKINS.getPreviewMarkup(preview.orb,preview.skinId)}</div>`;
      return;
    }
    if(preview.kind==='orb'&&typeof OF!=='undefined'&&typeof OF._drawOrb==='function'){
      const canvas=document.createElement('canvas');
      canvas.width=96;
      canvas.height=96;
      canvas.className='tt-preview-canvas';
      core.appendChild(canvas);
      const ctx=canvas.getContext('2d');
      const orb=this.makePreviewOrb(preview.def);
      const token=++this.previewToken;
      const draw=()=>{
        if(this.previewToken!==token) return;
        ctx.clearRect(0,0,canvas.width,canvas.height);
        ctx.save();
        if(preview.locked) ctx.filter='grayscale(1) saturate(.08) brightness(.78)';
        const previousBattle=OF.battleRunning;
        OF.battleRunning=false;
        OF._drawOrb(ctx,orb);
        OF.battleRunning=previousBattle;
        ctx.restore();
        this.previewRaf=requestAnimationFrame(draw);
      };
      draw();
      return;
    }
  },
  abilityMeta(key){
    const map={
      basic:{label:'Basic',desc:'Direct contact fighter with no special firing pattern.'},
      aoe:{label:'AOE',desc:'Damages clustered enemies with area impact.'},
      shards:{label:'Shards',desc:'Projects shard volleys that pressure multiple targets.'},
      gravity:{label:'Gravity',desc:'Pulls enemies off-line and compresses formations.'},
      blink:{label:'Blink',desc:'Repositions aggressively and disrupts pursuit.'},
      shockwave:{label:'Shockwave',desc:'Hits hard and ripples damage across nearby enemies.'},
      multishot:{label:'Multishot',desc:'Fires repeated bursts at several enemies.'},
      infinite:{label:'Infinite',desc:'Macro-orb entity built around overwhelming endurance.'},
      prismatic:{label:'Prismatic',desc:'High-tier spectrum cycle with rotating special attacks.'},
      solar:{label:'Solar',desc:'Celestial burn pressure with bright sustained offense.'},
      lunar:{label:'Lunar',desc:'Balanced celestial control with defensive timing windows.'},
      nebula:{label:'Nebula',desc:'Space-filling attacks and field distortion.'},
      stellar:{label:'Stellar',desc:'Heavy celestial artillery with large damage bursts.'},
      comet:{label:'Comet',desc:'Fast strike pattern built around charge passes.'},
      astral:{label:'Astral',desc:'Elite celestial pattern with layered ranged attacks.'},
      celestial_prime:{label:'Prime',desc:'High-end celestial boss profile with chained abilities.'},
      triastral:{label:'Triastral',desc:'Secret convergence entity with stacked celestial behaviors.'}
    };
    return map[key]||{label:(key||'Unknown').replace(/_/g,' '),desc:'Combat behavior signature not yet classified.'};
  },
  categoryForOrb(def,key){
    if(key==='fusion_signal_test_orb') return 'Fusion Arena Test';
    if(def.missionBoss) return 'Mission Boss Orb';
    if(def.isPrismatic) return 'Prismatic Entity';
    if(def.isInfinite) return 'Infinite Entity';
    if(def.isCelestial) return 'Celestial Orb';
    if(def.isBoss) return 'Boss Orb';
    return 'Orb Fight Orb';
  },
  buildOrbFightPayload(key){
    if(typeof OF==='undefined'||!OF.TYPES||!OF.TYPES[key]) return null;
    const def=OF.TYPES[key];
    const ability=this.abilityMeta(def.ability);
    const powerCost=typeof MISSION_MODE!=='undefined'?MISSION_MODE.getMissionCost(key):null;
    const tags=[];
    if(def.isBoss) tags.push('Boss');
    if(def.missionBoss) tags.push('Mission Boss');
    if(def.isCelestial) tags.push('Celestial');
    if(def.isInfinite) tags.push('Infinite');
    if(def.isPrismatic) tags.push('Prismatic');
    if(def.missionVariant) tags.push('Mission Boss');
    if(key==='fusion_signal_test_orb') tags.push('Sandbox Export');
    return this.payload({
      kicker:def.missionVariant?'Mission Boss Orb':this.categoryForOrb(def,key),
      title:def.label,
      badge:powerCost!=null?`PWR ${powerCost}`:'PWR -',
      accent:def.color||'#7fd1ff',
      sub:`${ability.label} • ${ability.desc}`,
      stats:[this.stat('Power',powerCost!=null?powerCost:'-'),this.stat('HP',def.hp),this.stat('Damage',def.dmg),this.stat('Speed',def.spd),this.stat('Radius',def.r||'Auto')],
      desc:key==='fusion_signal_test_orb'?'A Fusion Mode result exported into Orb Fight for sandbox combat testing.':def.missionVariant?'A boss-tier mission variant with boosted health and pressure compared with the sandbox version.':'Arena spawn entity ready for manual placement and battle simulation.',
      tags,
      footer:def.creatorConfig?'Custom visual payload active.':'Click left or right side of the arena to assign a team.',
      preview:this.buildOrbPreview(def)
    });
  },
  buildFusionPayload(entry,options={}){
    if(!entry) return null;
    const discovered=options.discovered!=null?options.discovered:(typeof FUSION_MODE!=='undefined'?FUSION_MODE.isDiscovered(entry.id):true);
    const rarity=FUSION_RARITY_META[entry.rarity]||FUSION_RARITY_META.common;
    const combat=typeof FUSION_MODE!=='undefined'&&discovered&&FUSION_MODE.canUseEntryInCombat(entry)?FUSION_MODE.buildOrbFightType(entry):null;
    const powerCost=combat&&typeof MISSION_MODE!=='undefined'?MISSION_MODE.getMissionCost(combat.orbFightKey||entry.orbFightKey||entry.id):null;
    return this.payload({
      kicker:'Fusion Signal',
      title:typeof FUSION_MODE!=='undefined'?FUSION_MODE.displayTitle(entry):entry.title,
      badge:powerCost!=null?`PWR ${powerCost}`:rarity.label,
      accent:discovered?rarity.color:'#9aa7c3',
      sub:discovered?`${entry.family} • ${rarity.label}`:'Locked signal preview',
      stats:[this.stat('Setup',entry.setup||'standard'),this.stat('Related',entry.related?entry.related.length:0),combat?this.stat('Arena HP',combat.hp):null,combat?this.stat('Arena DMG',combat.dmg):null,this.stat('Status',discovered?'Unlocked':'Locked')],
      desc:discovered?entry.effect:'Signal silhouette visible, but the recovered telemetry is still locked.',
      tags:[entry.icon?`Icon ${entry.icon}`:'',combat?this.abilityMeta(combat.ability).label:'Not Combat-Ready'],
      footer:discovered?entry.trigger:'Unlock this signal in Fusion Mode to reveal its full telemetry and Orb Fight profile.',
      preview:this.buildFusionPreview(entry,!discovered,combat)
    });
  },
  buildLoadoutPayload(index){
    if(typeof FUSION_MODE==='undefined') return null;
    const slot=FUSION_MODE.getLoadout(index);
    if(!slot||!slot.id) return this.payload({kicker:`Loadout ${index+1}`,title:'Empty Slot',badge:'Ready',accent:'#7fd1ff',sub:'Fusion combat shortcut',stats:[this.stat('Saved Signal','None'),this.stat('Action','Save Selected')],desc:'Store a discovered Fusion signal here for one-click Orb Fight export and testing.',tags:['Fusion Sandbox'],footer:'Use Save Selected or Save Last Result to fill this slot.'});
    const entry=FUSION_MODE.getEntry(slot.id);
    return this.buildFusionPayload(entry);
  },
  buildOpsPayload(kind,id){
    if(kind==='discovery'){
      const def=DISCOVERY_DEFS.find(item=>item.id===id); if(!def) return null;
      const unlocked=!!metaState.discoveries[id];
      return this.payload({kicker:'Discovery',title:unlocked?def.title:'Locked Signal',badge:def.category,accent:def.color||'#7fd1ff',sub:unlocked?'Recovered archive signal':'Research target',stats:[this.stat('Reward',`${def.reward||0} RD`),this.stat('Status',unlocked?'Unlocked':'Locked')],desc:unlocked?def.desc:def.hint,tags:[def.category,unlocked?'Recovered':'Undiscovered'],footer:unlocked?'Logged in the archive.':'Keep experimenting to recover this signal.'});
    }
    if(kind==='encyclopedia'){
      const def=ENCYCLOPEDIA_DEFS.find(item=>item.id===id); if(!def) return null;
      const unlocked=!def.unlock||!!metaState.discoveries[def.unlock];
      return this.payload({kicker:'Encyclopedia',title:unlocked?def.title:'Redacted Entry',badge:def.type,accent:'#ffd98d',sub:unlocked?def.origin:'Archive Locked',stats:[this.stat('Type',def.type),this.stat('Unlock',unlocked?'Recovered':(DISCOVERY_DEFS.find(d=>d.id===def.unlock)?.title||'Unknown'))],desc:unlocked?def.desc:'Recover the linked discovery to reveal the archive entry.',tags:[unlocked?def.origin:'Restricted'],footer:unlocked?def.stats:'Archive lock engaged.'});
    }
    if(kind==='achievement'){
      const def=ACHIEVEMENT_DEFS.find(item=>item.id===id); if(!def) return null;
      const unlocked=!!metaState.achievements[id];
      return this.payload({kicker:'Achievement',title:unlocked?def.title:'Locked Milestone',badge:unlocked?'Unlocked':'Pending',accent:unlocked?'#8fffd1':'#ffcf7f',sub:'Operations milestone',stats:[this.stat('Reward',`${def.reward||0} RD`),this.stat('Status',unlocked?'Complete':'In Progress')],desc:unlocked?def.desc:def.hint,tags:['Meta Progression'],footer:unlocked?'Milestone logged in Operations.':'Complete the requirement to unlock this reward.'});
    }
    if(kind==='mission'){
      const def=MISSION_DEFS.find(item=>item.id===id); if(!def) return null;
      const state=metaState.missions[id]||{progress:0,completed:false};
      return this.payload({kicker:'Directive',title:def.title,badge:state.completed?'Complete':'Active',accent:state.completed?'#8fffd1':'#7fd1ff',sub:def.desc,stats:[this.stat('Progress',`${Math.min(def.goal,state.progress)}/${def.goal}`),this.stat('Reward',`${def.reward||0} RD`)],desc:'Operations directive that tracks core gameplay milestones and rewards research data on completion.',tags:[def.event,'Mission'],footer:state.completed?'Directive complete.':'Advance the matching stat to complete this directive.'});
    }
    if(kind==='upgrade'){
      const def=UPGRADE_DEFS.find(item=>item.id===id); if(!def) return null;
      const lvl=metaState.upgrades[id]||0;
      const cost=def.cost[lvl]||def.cost[def.cost.length-1]||0;
      return this.payload({kicker:'Support Upgrade',title:def.title,badge:`Lv ${lvl}/${def.max}`,accent:'#8effc6',sub:'Operations support system',stats:[this.stat('Next Cost',lvl>=def.max?'MAX':`${cost} RD`),this.stat('Max Level',def.max)],desc:def.desc,tags:['Research Data'],footer:lvl>=def.max?'Upgrade fully developed.':'Spend Research Data to improve this system.'});
    }
    return null;
  },
  buildSkinPayload(id,orb){
    if(typeof SKINS==='undefined') return null;
    const def=SKINS.allDefs().find(item=>item.id===id); if(!def) return null;
    const unlocked=SKINS.isUnlocked(id);
    return this.payload({kicker:`${orb==='gold'?'Gold Core':'Orb'} Skin`,title:def.title,badge:def.tier,accent:def.id.includes('prismatic')?'#ff79c6':def.id.includes('diamond')?'#9cecff':'#7fd1ff',sub:unlocked?'Unlocked visual shell':'Locked cosmetic shell',stats:[this.stat('Orb',orb),this.stat('Status',unlocked?'Unlocked':'Locked'),this.stat('Cost',def.unlock==='buy'?`${def.cost} RD`:'Condition'),this.stat('Effect',def.effectText||'Visual only')],desc:def.desc,tags:[def.tier,def.unlock==='buy'?'Buyable':'Unlockable'],footer:SKINS.getRequirementText(def),preview:this.buildSkinPreview(orb,id,!unlocked)});
  },
  buildCreatorAttackPayload(index){
    if(typeof CREATOR==='undefined'||!CREATOR.config||!Array.isArray(CREATOR.config.attacks)) return null;
    const attack=CREATOR.config.attacks[index]; if(!attack) return null;
    return this.payload({kicker:'Creator Attack',title:attack.label,badge:attack.enabled?'Enabled':'Disabled',accent:attack.enabled?'#7fd1ff':'#9aa7c3',sub:'Custom Orb Fight attack preset',stats:[this.stat('Damage',attack.damage),this.stat('Cooldown',`${attack.cooldown}s`),this.stat('Range',attack.range)],desc:'Editable attack profile used by custom creator orbs inside Orb Fight and the combat simulator.',tags:['Creator','Combat'],footer:attack.enabled?'This attack is active on the current design.':'Enable this attack to include it in the combat package.'});
  },
  buildCreatorAbilityPayload(index){
    if(typeof CREATOR==='undefined'||!CREATOR.config||!CREATOR.config.combat) return null;
    const ability=(CREATOR.config.combat.abilities||[])[index]||'none';
    const locked=index===3&&!CREATOR.config.combat.bossMode;
    const map={'none':'No special ability assigned to this slot.','shield':'Adds a defensive shield cycle to the orb.','gravity field':'Pulls enemies inward and distorts movement.','healing pulse':'Periodically restores health to nearby allies.','teleport burst':'Repositions the orb with sudden burst movement.','berserk mode':'Raises offensive pressure during combat spikes.'};
    return this.payload({kicker:'Creator Ability',title:`Slot ${index+1}`,badge:locked?'Locked':ability.toUpperCase(),accent:locked?'#9aa7c3':'#ffcf7f',sub:locked?'Boss Mode required':'Combat behavior modifier',stats:[this.stat('Assigned',ability),this.stat('State',locked?'Locked':'Active Slot')],desc:map[ability]||'Custom ability routing for creator-built combat entities.',tags:['Creator','Ability'],footer:locked?'Enable Boss Mode to unlock the fourth ability slot.':'Adjust this slot in the Orb Fight creator tab.'});
  },
  resolve(target){
    if(!target||target.closest('#game-tooltip')) return null;
    const fusionOrbBtn=target.closest('.of-spawn-btn[data-fusion-id]');
    if(fusionOrbBtn){
      const entry=FUSION_LIBRARY_BY_ID[fusionOrbBtn.dataset.fusionId];
      return {node:fusionOrbBtn,payload:this.buildFusionPayload(entry,{discovered:typeof FUSION_MODE!=='undefined'?FUSION_MODE.isDiscovered(entry.id):true})};
    }
    const orbBtn=target.closest('.of-spawn-btn[data-key]');
    if(orbBtn) return {node:orbBtn,payload:this.buildOrbFightPayload(orbBtn.dataset.key)};
    const fusionItem=target.closest('.fusion-lib-item[data-fusion-id]');
    if(fusionItem) return {node:fusionItem,payload:this.buildFusionPayload(FUSION_LIBRARY_BY_ID[fusionItem.dataset.fusionId],{discovered:typeof FUSION_MODE!=='undefined'?FUSION_MODE.isDiscovered(fusionItem.dataset.fusionId):true})};
    const loadout=target.closest('.fusion-loadout-item[data-loadout-index]');
    if(loadout) return {node:loadout,payload:this.buildLoadoutPayload(Number(loadout.dataset.loadoutIndex))};
    const opsNode=target.closest('[data-ops-kind][data-ops-id]');
    if(opsNode) return {node:opsNode,payload:this.buildOpsPayload(opsNode.dataset.opsKind,opsNode.dataset.opsId)};
    const skinNode=target.closest('.skin-card[data-skin-id][data-skin-orb]');
    if(skinNode) return {node:skinNode,payload:this.buildSkinPayload(skinNode.dataset.skinId,skinNode.dataset.skinOrb)};
    const attackNode=target.closest('.cc-attack-card[data-attack]');
    if(attackNode) return {node:attackNode,payload:this.buildCreatorAttackPayload(Number(attackNode.dataset.attack))};
    const abilityNode=target.closest('.cc-ability-slot[data-slot]');
    if(abilityNode) return {node:abilityNode,payload:this.buildCreatorAbilityPayload(Number(abilityNode.dataset.slot))};
    return null;
  },
  render(payload){
    if(!this.root||!payload) return;
    this.stopPreview();
    this.root.style.setProperty('--tt-accent',payload.accent||'#7fd1ff');
    this.root.style.setProperty('--tt-accent-soft',this.tone(payload.accent||'#7fd1ff',.18));
    const preview=this.renderPreviewMarkup(payload.preview);
    this.root.innerHTML=`<div class="tt-head"><div><div class="tt-kicker">${this.escape(payload.kicker)}</div><div class="tt-title">${this.escape(payload.title)}</div></div>${payload.badge?`<div class="tt-badge">${this.escape(payload.badge)}</div>`:''}</div>${preview}${payload.sub?`<div class="tt-sub">${this.escape(payload.sub)}</div>`:''}${payload.stats.length?`<div class="tt-grid">${payload.stats.map(item=>`<div class="tt-stat"><div class="tt-stat-label">${this.escape(item.label)}</div><div class="tt-stat-value">${this.escape(item.value)}</div></div>`).join('')}</div>`:''}${payload.desc?`<div class="tt-desc">${this.escape(payload.desc)}</div>`:''}${payload.tags.length?`<div class="tt-tags">${payload.tags.map(tag=>`<span class="tt-tag">${this.escape(tag)}</span>`).join('')}</div>`:''}${payload.footer?`<div class="tt-footer">${this.escape(payload.footer)}</div>`:''}`;
    this.mountPreview(payload.preview);
  },
  position(node,x,y){
    if(!this.root) return;
    const pad=14;
    const rect=this.root.getBoundingClientRect();
    const targetRect=node&&node.getBoundingClientRect?node.getBoundingClientRect():null;
    let left=Math.min(window.innerWidth-rect.width-pad,Math.max(pad,x+18));
    let top=Math.min(window.innerHeight-rect.height-pad,Math.max(pad,y+18));
    if(targetRect){
      const prefersLeft=targetRect.right>window.innerWidth*0.62||!!node.closest?.('#fusion-side-panel');
      left=prefersLeft?Math.max(pad,targetRect.left-rect.width-12):Math.min(window.innerWidth-rect.width-pad,targetRect.right+12);
      top=Math.min(window.innerHeight-rect.height-pad,Math.max(pad,targetRect.top+Math.min(18,Math.max(0,(targetRect.height-rect.height)/2))));
      if(prefersLeft&&left===pad&&targetRect.right+12+rect.width<window.innerWidth-pad) left=targetRect.right+12;
    }
    this.root.style.left=left+'px';
    this.root.style.top=top+'px';
  },
  show(target,payload,x,y){
    if(!payload||!payload.title){ this.hide(); return; }
    this.activeTarget=target;
    this.render(payload);
    this.root.classList.add('show');
    this.root.setAttribute('aria-hidden','false');
    this.position(target,x,y);
  },
  hide(){
    if(!this.root) return;
    this.stopPreview();
    this.activeTarget=null;
    this.root.classList.remove('show');
    this.root.setAttribute('aria-hidden','true');
  },
  onPointerMove(event){
    this.pointer.x=event.clientX;
    this.pointer.y=event.clientY;
    if(this.raf) cancelAnimationFrame(this.raf);
    this.raf=requestAnimationFrame(()=>{
      const resolved=this.resolve(event.target);
      if(!resolved||!resolved.payload){ this.hide(); return; }
      if(this.activeTarget!==resolved.node) this.show(resolved.node,resolved.payload,this.pointer.x,this.pointer.y);
      else this.position(resolved.node,this.pointer.x,this.pointer.y);
    });
  },
  onFocusIn(event){
    const resolved=this.resolve(event.target);
    if(!resolved||!resolved.payload) return;
    const rect=resolved.node.getBoundingClientRect();
    this.show(resolved.node,resolved.payload,rect.right,rect.top);
  },
  onFocusOut(event){
    if(this.activeTarget&&event.target&&this.activeTarget.contains&&this.activeTarget.contains(event.target)) this.hide();
  }
};

// ══════════════════════════════════════════
// DRAG
// ══════════════════════════════════════════
[els.red,els.blue,els.green].forEach(e=>{
  if(!e) return;
  e.addEventListener('mousedown',startDrag);
  e.addEventListener('touchstart',startDrag,{passive:false});
});

function startDrag(e){
  e.preventDefault(); // must be first — prevents scroll on touch
  if(TUTORIAL.active&&!TUTORIAL.internal)return;
  if(_introPlaying)return;           // block during orb intro animation
  if(merged||blackHoleActive)return;
  if(advActive&&advScene!=='earth'&&advScene!=='mars')return;
  dragging=e.currentTarget;
  const rect=dragging.getBoundingClientRect();
  const touch=e.touches?e.touches[0]:e;
  ox=touch.clientX-rect.left;
  oy=touch.clientY-rect.top;
  dragging.style.zIndex=10;
  dragging.style.transition='box-shadow .2s ease';
  dragHistory=[];
  if(mode==='gravity'){
    const idx=[els.red,els.blue,els.green].indexOf(dragging);
    if(idx>=0) gravVels[idx]={x:0,y:0};
  }
  SFX.pick();
}

document.addEventListener('mousemove',moveDrag);
document.addEventListener('touchmove',moveDrag,{passive:false});
document.addEventListener('mouseup',endDrag);
document.addEventListener('touchend',endDrag);

function moveDrag(e){
  if(!dragging)return;
  e.preventDefault();
  const touch=e.touches?e.touches[0]:e;
  const ar=area.getBoundingClientRect();
  let nx=touch.clientX-ox-ar.left;
  let ny=touch.clientY-oy-ar.top;
  if(mode==='puzzle')[nx,ny]=applyWallCollision(nx,ny);
  nx=Math.max(-R*.3,Math.min(cW()-R*1.7,nx));
  ny=Math.max(-R*.3,Math.min(cH()-R*1.7,ny));
  dragging.style.left=nx+'px';dragging.style.top=ny+'px';
  const now=performance.now();
  dragHistory.push({x:nx,y:ny,t:now});
  if(dragHistory.length>8)dragHistory.shift();
  if(infiniteActive) checkInfiniteSeparation();
  else checkCollisions();
}

function applyWallCollision(nx,ny){
  const ar=area.getBoundingClientRect();
  document.querySelectorAll('.wall,.mover').forEach(w=>{
    const wr=w.getBoundingClientRect();
    const wx=wr.left-ar.left,wy=wr.top-ar.top,ww=wr.width,wh=wr.height;
    const cx2=nx+R,cy2=ny+R;
    if(cx2+R>wx&&cx2-R<wx+ww&&cy2+R>wy&&cy2-R<wy+wh){
      const oL=cx2+R-wx,oR=wx+ww-(cx2-R),oT=cy2+R-wy,oB=wy+wh-(cy2-R);
      const mH=Math.min(oL,oR),mV=Math.min(oT,oB);
      if(mH<mV)nx-=(oL<oR?oL:-oR);else ny-=(oT<oB?oT:-oB);
    }
  });
  return[nx,ny];
}

function endDrag(){
  if(dragging){
    // Apply fling velocity in gravity mode
    if(mode==='gravity'&&dragHistory.length>=2){
      const idx=[els.red,els.blue,els.green].indexOf(dragging);
      if(idx>=0){
        // Use last few samples within 80ms for velocity
        const now=performance.now();
        const recent=dragHistory.filter(h=>now-h.t<80);
        if(recent.length>=2){
          const a=recent[0],b=recent[recent.length-1];
          const dt=(b.t-a.t)/1000; // seconds
          if(dt>0){
            const vx=(b.x-a.x)/dt*0.016; // scale to per-frame
            const vy=(b.y-a.y)/dt*0.016;
            const maxSpd=28;
            gravVels[idx].x=Math.max(-maxSpd,Math.min(maxSpd,vx));
            gravVels[idx].y=Math.max(-maxSpd,Math.min(maxSpd,vy));
          }
        }
      }
    }
    dragHistory=[];
    dragging.style.zIndex='';dragging=null;
    checkCollisions();
  }
}

// ══════════════════════════════════════════
// COLLISIONS + MAGNETIC ATTRACTION
// ══════════════════════════════════════════
function isNear(a,b,extraPx=60){
  const ca=getCenter(a),cb=getCenter(b);
  return Math.hypot(ca.x-cb.x,ca.y-cb.y)<ca.rad+cb.rad+extraPx;
}

function checkCollisions(){
  if(merged||blackHoleActive)return;
  // Skip if circles are hidden (adventure map, orbfight overlay, etc.)
  if(els.red.classList.contains('hidden'))return;
  const rb=isTouching(els.red,els.blue),bg=isTouching(els.blue,els.green),rg=isTouching(els.red,els.green);
  const all=rb&&bg&&rg;
  setPips(rb,bg,rg);
  if(mode==='scifi'){updateEnergy(rb,bg,rg);updateBeams(rb,bg,rg);}
  if(!all)handlePairDiscovery(rb,bg,rg);

  // Magnetic glow when near
  const pairs=[[els.red,els.blue],[els.blue,els.green],[els.red,els.green]];
  pairs.forEach(([a,b])=>{
    const near=isNear(a,b,55);
    a.classList.toggle('magnetic',near);
    b.classList.toggle('magnetic',near);
  });

  if(all){
    // Fusion/gravity/scifi get a charge meter — other modes fire instantly
    if(mode==='fusion'||mode==='gravity'||mode==='scifi'){
      if(mode==='scifi'&&SCIFI.phase!=='idle')return; // don't re-trigger mid-sequence
      if(!fusionCharging) SFX.touch();
      startFusionCharge();
    } else {
      cancelFusionCharge();
      triggerFusion();
    }
  } else {
    cancelFusionCharge();
    [els.red,els.blue,els.green].forEach(e=>e.classList.remove('magnetic'));
    const n=(rb?1:0)+(bg?1:0)+(rg?1:0);
    if(n===0)setStatus(modeHint());
    else if(n===1)setStatus('ONE LINK — KEEP GOING');
    else setStatus('TWO LINKS — ALMOST THERE!');
  }
}

// ── FUSION CHARGE METER ──
function startFusionCharge(){
  if(fusionCharging)return;
  fusionCharging=true;
  fusionChargeStart=Date.now();
  fusionChargePct=0;
  setStatus(mode==='scifi'?'⚡ HOLD — REACTOR CHARGING...':'⚡ HOLD — CHARGING FUSION...','merged');

  const isSci=mode==='scifi';
  const arcColor0=isSci?'#44aaff':'#f5c842';
  const arcColor1=isSci?'#44ffee':'#ffffff';
  const bgRingColor=isSci?'rgba(68,170,255,.15)':'rgba(245,200,66,.15)';
  const shadowColor=isSci?'rgba(68,200,255,.9)':'rgba(245,200,66,.9)';
  const sparkColor=isSci?'#44aaff':'#f5c842';

  // draw arc on canvas
  const canvas=els.fusionChargeCvs;
  canvas.width=area.clientWidth; canvas.height=area.clientHeight;

  fusionChargeTimer=setInterval(()=>{
    if(!fusionCharging){clearInterval(fusionChargeTimer);return;}
    const elapsed=Date.now()-fusionChargeStart;
    fusionChargePct=Math.min(1,elapsed/FUSION_CHARGE_DURATION);

    // get centroid
    const cr=getCenter(els.red),cb=getCenter(els.blue),cg=getCenter(els.green);
    const cx=(cr.x+cb.x+cg.x)/3,cy=(cr.y+cb.y+cg.y)/3;
    const r=70+fusionChargePct*18;

    // draw ring
    const ctx=canvas.getContext('2d');
    ctx.clearRect(0,0,canvas.width,canvas.height);

    // background ring
    ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);
    ctx.strokeStyle=bgRingColor;ctx.lineWidth=8;ctx.stroke();

    // fill arc
    ctx.beginPath();ctx.arc(cx,cy,r,-Math.PI/2,-Math.PI/2+Math.PI*2*fusionChargePct);
    const grad=ctx.createLinearGradient(cx-r,cy,cx+r,cy);
    grad.addColorStop(0,arcColor0);grad.addColorStop(1,arcColor1);
    ctx.strokeStyle=grad;ctx.lineWidth=7;
    ctx.shadowColor=shadowColor;ctx.shadowBlur=18;ctx.stroke();

    // sparks at tip
    if(Math.random()<.3){
      const tipAngle=-Math.PI/2+Math.PI*2*fusionChargePct;
      spawnSparks(cx+Math.cos(tipAngle)*r,cy+Math.sin(tipAngle)*r,sparkColor,2);
      SFX.charge(fusionChargePct*100);
    }

    if(fusionChargePct>=1){
      clearInterval(fusionChargeTimer);
      ctx.clearRect(0,0,canvas.width,canvas.height);
      fusionCharging=false;
      triggerFusion();
    }
  },16);
}

function cancelFusionCharge(){
  if(!fusionCharging)return;
  fusionCharging=false;
  clearInterval(fusionChargeTimer);
  fusionChargePct=0;
  const ctx=els.fusionChargeCvs.getContext('2d');
  ctx.clearRect(0,0,els.fusionChargeCvs.width,els.fusionChargeCvs.height);
}

// ── PERFECT FUSION CHECK ──
function isPerfectFusion(){
  const cr=getCenter(els.red),cb=getCenter(els.blue),cg=getCenter(els.green);
  const cx=(cr.x+cb.x+cg.x)/3,cy=(cr.y+cb.y+cg.y)/3;
  // All three within 35px of centroid = perfect
  return[cr,cb,cg].every(c=>Math.hypot(c.x-cx,c.y-cy)<38);
}

// ── COMBO SYSTEM ──
function bumpCombo(){
  comboCount++;
  if(comboTimer)clearTimeout(comboTimer);
  comboTimer=setTimeout(()=>{comboCount=0;els.comboDisplay.classList.remove('show');},8000);
  if(comboCount>1){
    const labels=['','','✦ COMBO x2','✦✦ COMBO x3 — HOT STREAK!','✦✦✦ COMBO x4 — ON FIRE!','⚡ COMBO x5 — UNSTOPPABLE!'];
    els.comboDisplay.textContent=labels[Math.min(comboCount,5)]||`⚡ COMBO x${comboCount} — LEGENDARY!`;
    els.comboDisplay.classList.add('show');
  }
  return comboCount;
}

function modeHint(){
  return{fusion:'DRAG ALL THREE CIRCLES TOGETHER',puzzle:'NAVIGATE AROUND OBSTACLES',gravity:'DRAG WHILE THEY FALL — COLLIDE TO FUSE',ifusion:'COMBINE ELEMENTS TO DISCOVER NEW ONES',scifi:'DRAG ALL THREE CIRCLES INTO THE REACTOR',adventure:'FUSE CIRCLES TO EARN ENERGY',boss:'FUSE THE ELEMENTS — IF YOU DARE',orbfight:'',creator:''}[mode]??'DRAG THE CIRCLES TOGETHER';
}

// ══════════════════════════════════════════
// ⚡ SCI-FI REACTOR SYSTEM
// ══════════════════════════════════════════
const SCIFI={
  active:false,
  phase:'idle',       // idle | doors | fusion | core | charging | charged | launch | instability
  coreType:null,
  chargeLevel:0,
  chargeTimer:null,
  instabilityTimer:null,
  bgCtx:null,
  rcCtx:null,
  bgStars:[],
  rings:[],           // spinning reactor rings
  arcNodes:[],        // electricity arc nodes
  lastArcT:0,

  CORE_TYPES:[
    {id:'standard',  name:'STANDARD CORE',   color:'#44aaff', color2:'#0055cc', glow:'rgba(68,170,255,', rarity:'COMMON',    desc:'Stable energy output\nReliable fusion result',       weight:40},
    {id:'overcharge', name:'OVERCHARGED CORE',color:'#ffaa22', color2:'#ff5500', glow:'rgba(255,160,30,', rarity:'UNCOMMON',  desc:'Excess energy detected\nUnstable but powerful',       weight:25},
    {id:'quantum',   name:'QUANTUM CORE',     color:'#cc44ff', color2:'#660099', glow:'rgba(200,80,255,', rarity:'RARE',      desc:'Quantum superposition\nFlickers between states',      weight:18},
    {id:'singularity',name:'SINGULARITY CORE',color:'#222222', color2:'#440066', glow:'rgba(120,0,200,',  rarity:'EPIC',      desc:'Micro-gravity detected\nDo not approach',             weight:10},
    {id:'plasma',    name:'PLASMA CORE',      color:'#ff4422', color2:'#ff8800', glow:'rgba(255,100,20,', rarity:'UNCOMMON',  desc:'Plasma containment field\nExtreme heat warning',      weight:25},
    {id:'ion',       name:'ION CORE',         color:'#44ffcc', color2:'#00aa88', glow:'rgba(68,255,200,', rarity:'RARE',      desc:'Ion discharge active\nElectric arc hazard',           weight:18},
    {id:'mega',      name:'⚡ MEGA CORE',     color:'#ffffff', color2:'#ffcc00', glow:'rgba(255,240,200,', rarity:'LEGENDARY', desc:'Perfect alignment achieved\nMaximum energy output',   weight:0}, // triggered only by perfect fusion
  ],

  pickCoreType(perfect){
    if(perfect) return this.CORE_TYPES.find(c=>c.id==='mega');
    const pool=this.CORE_TYPES.filter(c=>c.id!=='mega');
    // Singularity weight is overridden by adventure upgrade when in adv mode
    // In adventure mode, singularity chance is controlled by upgrade (already handled
    // in advOnMarsFusion roll). Outside adventure, use normal weight of 10.
    const singWeight=10;
    const total=pool.reduce((s,c)=>s+(c.id==='singularity'?singWeight:c.weight),0);
    let r=Math.random()*total;
    for(const c of pool){
      const w=c.id==='singularity'?singWeight:c.weight;
      r-=w; if(r<=0) return c;
    }
    return pool[0];
  },

  init(){
    // Build bg canvas once
    const bg=document.getElementById('scifi-bg-canvas');
    if(!bg)return;
    bg.width=area.clientWidth;bg.height=area.clientHeight;
    this.bgCtx=bg.getContext('2d');
    // Scatter twinkling grid dots
    this.bgStars=[];
    for(let i=0;i<60;i++) this.bgStars.push({
      x:Math.random()*bg.width,y:Math.random()*bg.height,
      r:Math.random()*.8+.2,phase:Math.random()*Math.PI*2,spd:Math.random()*.02+.005
    });
    // Reactor canvas
    const rc=document.getElementById('reactor-canvas');
    if(rc){ rc.width=220;rc.height=220; this.rcCtx=rc.getContext('2d'); }
    // Build rings
    this.rings=[
      {r:65, speed:.012, angle:0,  width:2, color:'rgba(68,170,255,',  opacity:.35},
      {r:80, speed:-.008,angle:1,  width:1.5,color:'rgba(100,200,255,',opacity:.25},
      {r:52, speed:.02,  angle:2,  width:1, color:'rgba(68,255,200,',  opacity:.2},
    ];
    this.active=true;
    document.body.classList.add('scifi-active');
    this.showTerminal();
    this.aiSay('SYSTEM ONLINE','dim');
    setTimeout(()=>this.aiSay('REACTOR READY'),400);
    setTimeout(()=>this.aiSay('INSERT ENERGY SOURCES'),900);
    this.phase='idle';
    this.showChargeBadge(false);
    document.getElementById('reactor-charge-bar').classList.remove('show');
    document.getElementById('core-type-badge').classList.remove('show');
    document.getElementById('launch-tube').classList.remove('open');
    document.getElementById('reactor-chamber').classList.remove('open','doors-closing');
    this.loop();
    QL.init();
    ScifiNav.reset();
    RL.init();
  },

  stop(){
    this.active=false;
    document.body.classList.remove('scifi-active');
    clearInterval(this.chargeTimer);
    clearTimeout(this.instabilityTimer);
    this.phase='idle';
    this.coreType=null;
    this.chargeLevel=0;
    document.getElementById('ai-terminal')?.classList.remove('show');
    document.getElementById('reactor-charge-bar')?.classList.remove('show');
    document.getElementById('core-type-badge')?.classList.remove('show');
    document.getElementById('launch-tube')?.classList.remove('open');
    document.getElementById('reactor-chamber')?.classList.remove('open','doors-closing');
    const el=document.getElementById('ai-terminal-lines');if(el)el.innerHTML='';
    this._resetOrbLabels();
    QL.stop();
    ScifiNav.reset();
    RL.stop();
  },

  showTerminal(){
    document.getElementById('ai-terminal').classList.add('show');
  },

  aiSay(msg, cls=''){
    const lines=document.getElementById('ai-terminal-lines');
    if(!lines)return;
    const d=document.createElement('div');
    d.className='ai-line'+(cls?' '+cls:'');
    d.textContent='> '+msg;
    lines.appendChild(d);
    // Keep max 8 lines
    while(lines.children.length>8) lines.removeChild(lines.firstChild);
    lines.scrollTop=lines.scrollHeight;
    SFX.aiBeep();
  },

  showChargeBadge(show){
    const el=document.getElementById('core-type-badge');
    if(!el)return;
    if(!show){el.classList.remove('show');return;}
    const c=this.coreType;
    el.innerHTML=`<div id="core-type-name" style="color:${c.color}">${c.name}</div>
      <div id="core-type-desc" style="white-space:pre">${c.desc}</div>
      <div id="core-type-rarity" style="color:${c.color}">${c.rarity}</div>`;
    el.style.borderColor=c.color+'88';
    el.classList.add('show');
  },

  onFusion(cx,cy,perfect){
    if(this.phase!=='idle')return;
    this.phase='doors';
    this.coreType=this.pickCoreType(perfect);
    const c=this.coreType;

    this.aiSay('FUSION INITIATED','warn');
    setTimeout(()=>this.aiSay('CONTAINMENT FIELD ACTIVE'),300);
    setTimeout(()=>this.aiSay(`CORE TYPE: ${c.id.toUpperCase()}`,c.id==='mega'?'warn':''),700);

    // Close doors
    const chamber=document.getElementById('reactor-chamber');
    chamber.classList.add('doors-closing');
    setTimeout(()=>{
      // Doors closed → start fusion sequence
      this.phase='fusion';
      this.aiSay('DOORS SEALED — FUSION ACTIVE','warn');
      shake('sm');
      // Speed up rings
      this.rings.forEach(r=>{ r._baseSpeed=r.speed; r.speed*=6; });

      // After 1.4s → core appears
      setTimeout(()=>this.spawnCore(cx,cy,perfect),1400);
    },650);
  },

  spawnCore(cx,cy,perfect){
    this.phase='core';
    const c=this.coreType;
    shake('md');
    flashScreen(`${c.glow}.5)`,200);
    spawnParticles(cx,cy,c.color,80,9);
    spawnParticles(cx,cy,'#ffffff',30,12);
    spawnShockwave(cx,cy,c.glow,200,10);

    const pulseMap={
      standard:'pulse-core-std',overcharge:'pulse-core-over',quantum:'pulse-core-quantum',
      singularity:'pulse-core-sing',plasma:'pulse-core-plasma',ion:'pulse-core-ion',mega:'pulse-core-mega'
    };
    const pulseAnim=pulseMap[c.id]||'pulse-core-std';

    // Style gold orb as core — no animation yet, set background first
    const size=c.id==='mega'?170:140;
    const bgStyle=this._coreBackground(c);
    Object.assign(els.gold.style,{
      width:size+'px',height:size+'px',left:cx+'px',top:cy+'px',
      background:bgStyle,
      boxShadow:`0 0 60px 25px ${c.glow}.7),0 0 120px 60px ${c.glow}.3)`,
      animation:`${pulseAnim} 1.4s ease-in-out infinite`,
      filter:'',transition:'opacity .4s',pointerEvents:'none',cursor:'default',
    });

    // Label: white text for all cores (non-gold backgrounds)
    els.orbText.style.color=c.id==='singularity'?'rgba(200,150,255,.9)':c.id==='mega'?'rgba(60,30,0,.9)':'rgba(220,240,255,.95)';
    els.orbIcon.style.color=els.orbText.style.color;
    els.orbText.textContent=c.name;
    els.orbIcon.textContent={mega:'⚡',singularity:'◉',quantum:'⟨ψ⟩',plasma:'🔥',ion:'⚡',overcharge:'⬆',standard:'◈'}[c.id]||'◈';
    els.bossPhaseLabel.textContent='';
    els.gold.classList.add('visible');

    // Open doors
    document.getElementById('reactor-chamber').classList.remove('doors-closing');
    document.getElementById('reactor-chamber').classList.add('open');
    document.getElementById('launch-tube').classList.add('open');

    // Show core type badge
    this.showChargeBadge(true);

    const msgTitle=c.id==='mega'?'⚡ MEGA CORE FORMED':c.id==='singularity'?'◉ SINGULARITY CORE':'CORE STABILIZED';
    showMsg(msgTitle,`${c.name} — CHARGING...`,c.color);
    setStatus(`◈ ${c.name} — CHARGING TO LAUNCH`,'merged');
    this.aiSay('CORE STABILIZED');
    setTimeout(()=>this.aiSay(`${c.rarity} CLASSIFICATION`,c.id==='mega'?'warn':c.id==='singularity'?'err':''),400);

    SFX.reactorCore();

    // Special per-type effects
    this._coreSpecialEffect(cx,cy,c);

    // Singularity: skip charging, go straight to black-hole suck → explode
    if(c.id==='singularity'){
      setTimeout(()=>this.triggerSingularityEvent(cx,cy),1200);
      return;
    }

    // Begin charging
    setTimeout(()=>this.startCharging(cx,cy),600);
  },

  triggerSingularityEvent(cx,cy){
    this.phase='launch'; // lock out other interactions
    this.aiSay('⚠ SINGULARITY THRESHOLD REACHED','err');
    this.aiSay('GRAVITY CONTAINMENT FAILING','err');
    setStatus('◉ SINGULARITY — CONTAINMENT FAILING','danger');
    shake('md');

    // Phase 1: suck circles in (1.5s)
    let t=0;
    const suckInterval=setInterval(()=>{
      t+=50;
      [els.red,els.blue,els.green].forEach(e=>{
        if(e.classList.contains('fading'))return;
        const ctr=getCenter(e);
        const ang=Math.atan2(cy-ctr.y,cx-ctr.x);
        const dist=Math.hypot(ctr.x-cx,ctr.y-cy);
        const force=Math.max(4,18-(dist*.04));
        setPos(e,parseFloat(e.style.left)+Math.cos(ang)*force,parseFloat(e.style.top)+Math.sin(ang)*force);
        if(Math.random()<.3) spawnSparks(ctr.x,ctr.y,'#cc44ff',2);
      });
      // Orb grows and darkens as it absorbs
      const grow=140+t*.04;
      els.gold.style.width=grow+'px';els.gold.style.height=grow+'px';
      spawnSparks(cx+(-80+Math.random()*160),cy+(-80+Math.random()*160),'#220066',2);
      if(t>=1500){
        clearInterval(suckInterval);
        // Circles collapse into orb
        [els.red,els.blue,els.green].forEach(e=>e.classList.add('fading'));
        flashScreen('rgba(0,0,0,.95)',400);
        shake('lg');
        SFX.singularity();
        // Adventure mode: trigger enemy/boss strike
        if(advActive&&advScene==='mars') advSingularityStrike();
        // Phase 2: explode like supernova (t+0.6s)
        setTimeout(()=>this._singularityExplosion(cx,cy),600);
      }
    },50);
  },

  _singularityExplosion(cx,cy){
    this.aiSay('CRITICAL FAILURE — CORE OVERLOAD','err');
    // Hide the orb
    els.gold.classList.remove('visible');
    els.gold.style.animation='';
    // Big explosion sequence
    const colors=['#cc00ff','#8800ff','#4400cc','#ffffff','#ff44ff','#aa00ff'];
    for(let i=0;i<8;i++){
      setTimeout(()=>{
        flashScreen(`rgba(${80+i*18},0,${200+i*6},.7)`,80);
        shake(i<4?'lg':'md');
        spawnParticles(cx+(-120+Math.random()*240),cy+(-120+Math.random()*240),colors[i%6],80);
        spawnParticles(cx,cy,'#ffffff',50);
        spawnSparks(cx,cy,'#cc44ff',20);
        spawnShockwave(cx,cy,'rgba(180,0,255,',cW()*(0.5+i*.12),10+i);
      },i*180);
    }
    SFX.supernova();
    // Aftermath + reset
    setTimeout(()=>{
      document.getElementById('reactor-charge-bar').classList.remove('show');
      document.getElementById('core-type-badge').classList.remove('show');
      document.getElementById('launch-tube').classList.remove('open');
      document.getElementById('reactor-chamber').classList.remove('open');
      this.aiSay('CONTAINMENT RESTORED','dim');
      showMsg('SINGULARITY COLLAPSED','GRAVITY EVENT CONCLUDED','#cc44ff');
      setStatus('◈ SINGULARITY DISCHARGED — REACTOR RESETTING','merged');
    },1500);
    setTimeout(()=>{
      merged=false;this.phase='idle';this.coreType=null;this.chargeLevel=0;
      this.rings.forEach(r=>{ if(r._baseSpeed) r.speed=r._baseSpeed; });
      this._resetOrbLabels();
      popCirclesOut();
      setStatus('DRAG ALL THREE CIRCLES INTO THE REACTOR');
      this.aiSay('SYSTEM READY','dim');
    },3500);
  },

  _resetOrbLabels(){
    // Reset label colors back to default gold for non-scifi use
    els.orbText.style.color='';
    els.orbIcon.style.color='';
    els.orbText.textContent='GOLD';
    els.orbIcon.textContent='✦';
  },

  _coreBackground(c){
    const map={
      standard:  'radial-gradient(circle at 38% 35%,#aaddff,#2266cc 45%,#001144)',
      overcharge:'radial-gradient(circle at 38% 35%,#ffffff,#ffaa22 40%,#cc3300)',
      quantum:   'radial-gradient(circle at 38% 35%,#eeccff,#9933cc 45%,#220044)',
      singularity:'radial-gradient(circle at 50% 50%,#000000 25%,#220033 55%,#440066 75%,transparent)',
      plasma:    'radial-gradient(circle at 38% 35%,#ffeecc,#ff4400 45%,#880000)',
      ion:       'radial-gradient(circle at 38% 35%,#ccffee,#22cc99 45%,#004433)',
      mega:      'radial-gradient(circle at 38% 35%,#ffffff,#ffee66 30%,#ffaa00 60%,#cc5500)',
    };
    return map[c.id]||map.standard;
  },

  _coreSpecialEffect(cx,cy,c){
    if(c.id==='singularity'){
      // Gravity pull aura
      const interval=setInterval(()=>{
        if(this.phase!=='charging'&&this.phase!=='charged'){clearInterval(interval);return;}
        [els.red,els.blue,els.green].forEach(e=>{
          if(e.classList.contains('fading'))return;
          const ctr=getCenter(e);
          const ang=Math.atan2(cy-ctr.y,cx-ctr.x);
          const dist=Math.hypot(ctr.x-cx,ctr.y-cy);
          const pull=Math.max(0,(180-dist)*0.012);
          setPos(e,parseFloat(e.style.left)+Math.cos(ang)*pull,parseFloat(e.style.top)+Math.sin(ang)*pull);
        });
      },50);
    }
    if(c.id==='ion'){
      // Random sparks from core
      const interval=setInterval(()=>{
        if(this.phase!=='charging'&&this.phase!=='charged'){clearInterval(interval);return;}
        const a=Math.random()*Math.PI*2, d=50+Math.random()*80;
        spawnSparks(cx+Math.cos(a)*d,cy+Math.sin(a)*d,'#44ffcc',4);
      },200);
    }
    if(c.id==='quantum'){
      // Flicker effect on orb
      const interval=setInterval(()=>{
        if(this.phase!=='charging'&&this.phase!=='charged'){clearInterval(interval);return;}
        if(Math.random()<.25){
          els.gold.style.opacity=(0.4+Math.random()*.6).toString();
          setTimeout(()=>{ if(els.gold.classList.contains('visible')) els.gold.style.opacity='1'; },80);
        }
      },150);
    }
  },

  startCharging(cx,cy){
    this.phase='charging';
    this.chargeLevel=0;
    document.getElementById('reactor-charge-bar').classList.add('show');
    const fill=document.getElementById('reactor-charge-fill');
    const pct=document.getElementById('reactor-charge-pct');
    this.aiSay('CORE CHARGING...','dim');

    // Decide if instability occurs (30% chance + overclock bonus, not for mega)
    const unstable=this.coreType.id!=='mega' && Math.random()<(.30+QL.instabilityBonus());
    let instabilityFired=false;

    this.chargeTimer=setInterval(()=>{
      if(this.phase!=='charging')return;
      this.chargeLevel=Math.min(100,this.chargeLevel+.5*QL.chargeMultiplier());
      fill.style.width=this.chargeLevel+'%';
      pct.textContent=Math.round(this.chargeLevel)+'%';
      SFX.sepPulse(this.chargeLevel);

      // Emit particles as charge rises
      if(Math.random()<.08){
        const a=Math.random()*Math.PI*2,r=55+this.chargeLevel*.6;
        spawnSparks(cx+Math.cos(a)*r,cy+Math.sin(a)*r,this.coreType.color,3);
      }

      // Instability event at ~50-70% charge
      if(unstable&&!instabilityFired&&this.chargeLevel>=50+Math.random()*20){
        instabilityFired=true;
        this.triggerInstability(cx,cy);
      }

      if(this.chargeLevel>=100){
        clearInterval(this.chargeTimer);
        this.coreFullyCharged(cx,cy);
      }
    },40);
  },

  triggerInstability(cx,cy){
    this.phase='instability';
    clearInterval(this.chargeTimer);
    this.aiSay('⚠ CORE INSTABILITY DETECTED','err');
    this.aiSay('CONTAINMENT WARNING','warn');
    shake('md');flashScreen('rgba(255,80,0,.4)');

    let pulses=0;
    const warnLoop=setInterval(()=>{
      pulses++;
      flashScreen('rgba(255,40,0,.25)',120);
      shake('sm');
      spawnSparks(cx+(-80+Math.random()*160),cy+(-80+Math.random()*160),this.coreType.color,6);
      spawnShockwave(cx,cy,this.coreType.glow,100+pulses*20,4);
      SFX.meltdownWarn();
      if(pulses>=4){
        clearInterval(warnLoop);
        // 60% stabilize, 40% fail
        if(Math.random()<.6){
          this.aiSay('STABILIZING...','warn');
          setTimeout(()=>{
            this.aiSay('CORE RESTABILIZED');
            showMsg('CORE RESTABILIZED','EXTRA CHARGE BONUS — +20%',this.coreType.color);
            this.chargeLevel=Math.min(100,this.chargeLevel+20);
            this.phase='charging';
            this.startCharging(cx,cy); // resume
          },800);
        } else {
          this.aiSay('CONTAINMENT FAILURE','err');
          setTimeout(()=>{
            this.phase='idle';
            clearInterval(this.chargeTimer);
            triggerMeltdown(cx,cy);
          },600);
        }
      }
    },350);
  },

  coreFullyCharged(cx,cy){
    this.phase='charged';
    const c=this.coreType;
    const pulseMap={standard:'pulse-core-std',overcharge:'pulse-core-over',quantum:'pulse-core-quantum',
      singularity:'pulse-core-sing',plasma:'pulse-core-plasma',ion:'pulse-core-ion',mega:'pulse-core-mega'};
    this.aiSay('CORE FULLY CHARGED');
    this.aiSay('ENERGY OUTPUT MAXIMUM','warn');
    shake('md');
    flashScreen(`${c.glow}.6)`);
    spawnParticles(cx,cy,c.color,100,12);
    spawnShockwave(cx,cy,c.glow,300,12);
    showMsg('CORE FULLY CHARGED','ENERGY OUTPUT MAXIMUM — CLICK TO LAUNCH',c.color);
    setStatus(`◈ ${c.name} CHARGED — CLICK TO LAUNCH`,'merged');
    SFX.reactorCharged();

    // Fast pulsing glow with correct core color
    els.gold.style.animation=`${pulseMap[c.id]||'pulse-core-std'} .5s ease-in-out infinite`;
    els.gold.style.pointerEvents='all';
    els.gold.style.cursor='pointer';
    els.gold.onclick=()=>this.launchCore(cx,cy);
    document.getElementById('reactor-charge-fill').style.background=`linear-gradient(90deg,${c.color},#ffffff,${c.color})`;
    document.getElementById('reactor-charge-pct').style.color=c.color;
  },

  launchCore(cx,cy){
    if(this.phase!=='charged')return;
    this.phase='launch';
    const c=this.coreType;
    this.aiSay('LAUNCH SEQUENCE INITIATED','warn');
    this.aiSay('DEPLOYING TO ORBIT...');
    SFX.reactorLaunch();

    els.gold.style.pointerEvents='none';
    els.gold.onclick=null;

    // Orb shoots upward
    const startTop=parseFloat(els.gold.style.top);
    let t=0;
    const launchAnim=setInterval(()=>{
      t+=16;
      const p=t/800;
      els.gold.style.top=(startTop - p*p*cH()*1.5)+'px';
      els.gold.style.opacity=(1-p*1.2).toString();
      els.gold.style.transform=`translate(-50%,-50%) scale(${1-p*.5})`;
      spawnSparks(cx,startTop-p*p*cH()*1.5,c.color,4);
      if(t>=800){
        clearInterval(launchAnim);
        els.gold.classList.remove('visible');
        els.gold.style.opacity='';els.gold.style.transform='';
        this.afterLaunch(cx,cy);
      }
    },16);
  },

  afterLaunch(cx,cy){
    const c=this.coreType;
    flashScreen(`${c.glow}.4)`);
    shake('sm');
    spawnParticles(cx,cH()*0.1,c.color,80,8);
    showMsg('CORE LAUNCHED','PAYLOAD DELIVERED TO ORBIT',c.color);
    this.aiSay('PAYLOAD DELIVERED TO ORBIT');
    this.aiSay('REACTOR READY FOR NEXT CYCLE','dim');
    setStatus(`◈ ${c.name} LAUNCHED — REACTOR READY`,'merged');
    document.getElementById('reactor-charge-bar').classList.remove('show');
    document.getElementById('core-type-badge').classList.remove('show');
    document.getElementById('launch-tube').classList.remove('open');
    document.getElementById('reactor-chamber').classList.remove('open');

    // Reset for next fusion
    setTimeout(()=>{
      merged=false;
      this.phase='idle';
      this.coreType=null;
      this.chargeLevel=0;
      // Reset rings speed
      this.rings.forEach(r=>{ if(r._baseSpeed) r.speed=r._baseSpeed; });
      this._resetOrbLabels();
      popCirclesOut();
      setStatus('DRAG ALL THREE CIRCLES INTO THE REACTOR');
      this.aiSay('SYSTEM READY','dim');
    },1800);
  },

  loop(){
    if(!this.active)return;
    if(isGameplayPaused()){
      requestAnimationFrame(()=>this.loop());
      return;
    }
    this._drawBg();
    this._drawReactor();
    requestAnimationFrame(()=>this.loop());
  },

  _drawBg(){
    const ctx=this.bgCtx;
    if(!ctx)return;
    const W=ctx.canvas.width,H=ctx.canvas.height;
    ctx.clearRect(0,0,W,H);
    // Twinkling stars
    const now=Date.now()*.001;
    this.bgStars.forEach(s=>{
      s.phase+=s.spd;
      const a=.15+.3*(Math.sin(s.phase)*0.5+0.5);
      ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);
      ctx.fillStyle=`rgba(100,200,255,${a})`;ctx.fill();
    });
    // Horizontal scan lines
    ctx.strokeStyle='rgba(68,170,255,0.04)';ctx.lineWidth=1;
    for(let y=0;y<H;y+=18){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
    // Circuit network — static computed once, then redrawn each frame with pulsing opacity
    if(!this._circuits){
      this._circuits=[];
      // Horizontal conduit lines
      for(let i=0;i<6;i++){
        const y=H*.12+i*(H*.13);
        const x1=W*.06+Math.random()*W*.1,x2=W*.82+Math.random()*W*.1;
        this._circuits.push({type:'h',x1,y1:y,x2,y2:y,phase:Math.random()*Math.PI*2});
      }
      // Vertical conduit segments
      for(let i=0;i<4;i++){
        const x=W*.18+i*(W*.2);
        const y1=H*.1+Math.random()*H*.1,y2=y1+H*.15+Math.random()*H*.2;
        this._circuits.push({type:'v',x1:x,y1,x2:x,y2,phase:Math.random()*Math.PI*2});
      }
      // Circuit nodes at intersections
      this._cnodes=[];
      for(let i=0;i<20;i++)
        this._cnodes.push({x:W*.1+Math.random()*W*.8,y:H*.1+Math.random()*H*.8,r:.5+Math.random()*1.5,phase:Math.random()*Math.PI*2,spd:.018+Math.random()*.025});
    }
    const t2=Date.now()*.001;
    const isActive=this.phase!=='idle';
    this._circuits.forEach(c=>{
      c.phase+=.005;
      const a=(isActive?.06:.025)*(0.5+0.5*Math.sin(c.phase));
      ctx.strokeStyle=`rgba(68,170,255,${a})`;ctx.lineWidth=.8;
      ctx.beginPath();ctx.moveTo(c.x1,c.y1);ctx.lineTo(c.x2,c.y2);ctx.stroke();
    });
    this._cnodes.forEach(n=>{
      n.phase+=n.spd;
      const a=(isActive?.4:.15)*(0.5+0.5*Math.sin(n.phase));
      ctx.beginPath();ctx.arc(n.x,n.y,n.r,0,Math.PI*2);
      ctx.fillStyle=`rgba(68,220,255,${a})`;ctx.fill();
    });
    // Corner brackets
    const bS=30;
    ctx.strokeStyle='rgba(68,170,255,0.3)';ctx.lineWidth=1.5;
    [[0,0,1,1],[W,0,-1,1],[0,H,1,-1],[W,H,-1,-1]].forEach(([x,y,sx,sy])=>{
      ctx.beginPath();ctx.moveTo(x+sx*bS,y);ctx.lineTo(x,y);ctx.lineTo(x,y+sy*bS);ctx.stroke();
    });
  },

  _drawReactor(){
    const ctx=this.rcCtx;
    if(!ctx)return;
    const W=220,H=220,cx=110,cy=110;
    ctx.clearRect(0,0,W,H);

    const isActive=this.phase!=='idle';
    const now=Date.now()*.001;

    // Speed up rings during fusion
    const speedMult=(this.phase==='fusion'||this.phase==='charging')?1:1;
    this.rings.forEach(r=>{
      r.angle+=r.speed*(isActive?2.5:1);
      // Draw elliptical ring (3D tilt effect)
      ctx.save();
      ctx.translate(cx,cy);
      ctx.rotate(r.angle);
      ctx.scale(1,.35);
      ctx.beginPath();ctx.arc(0,0,r.r,0,Math.PI*2);
      ctx.strokeStyle=r.color+(r.opacity*(isActive?2:1)+')');
      ctx.lineWidth=r.width*(isActive?2:1);
      ctx.shadowColor=r.color+'0.6)';ctx.shadowBlur=isActive?16:6;
      ctx.stroke();
      ctx.restore();

      // Glow node on ring
      if(isActive){
        const nx=cx+Math.cos(r.angle)*r.r;
        const ny=cy+Math.sin(r.angle)*r.r*0.35;
        ctx.beginPath();ctx.arc(nx,ny,3,0,Math.PI*2);
        ctx.fillStyle=r.color+'0.9)';ctx.fill();
      }
    });

    // Core glow in center when active
    if(isActive&&this.coreType){
      const c=this.coreType;
      const pulse=0.7+0.3*Math.sin(now*4);
      const grad=ctx.createRadialGradient(cx,cy,0,cx,cy,45);
      grad.addColorStop(0,c.glow+(0.5*pulse)+')');
      grad.addColorStop(1,c.glow+'0)');
      ctx.beginPath();ctx.arc(cx,cy,45,0,Math.PI*2);
      ctx.fillStyle=grad;ctx.fill();
    }

    // Lightning arcs during fusion phase
    if(this.phase==='fusion'||this.phase==='charging'){
      if(now-this.lastArcT>0.08){
        this.lastArcT=now;
        this._drawArc(ctx,cx,cy);
      }
    }
    // Drones
    QL.drawDrones(ctx,cx,cy);
  },

  _drawArc(ctx,cx,cy){
    const c=this.coreType;if(!c)return;
    ctx.save();
    ctx.strokeStyle=c.color;ctx.lineWidth=1;ctx.globalAlpha=0.6+Math.random()*.4;
    ctx.shadowColor=c.color;ctx.shadowBlur=8;
    // Random zigzag from edge to center
    const a=Math.random()*Math.PI*2;
    const startX=cx+Math.cos(a)*90,startY=cy+Math.sin(a)*90;
    ctx.beginPath();ctx.moveTo(startX,startY);
    let px=startX,py=startY;
    for(let i=0;i<5;i++){
      const p=(i+1)/5;
      const tx=startX+(cx-startX)*p,ty=startY+(cy-startY)*p;
      px=tx+(-15+Math.random()*30);py=ty+(-15+Math.random()*30);
      ctx.lineTo(px,py);
    }
    ctx.lineTo(cx,cy);ctx.stroke();ctx.restore();
  },
};

// ══════════════════════════════════════════
// QUANTUM LAB (Sci-Fi sandbox extras)
// ══════════════════════════════════════════
const QL={
  active:false,
  grav:false, amp:false, over:false, portal:false,
  gravTimer:null, stormCycle:null, portalCheckInterval:null, portalCloseTimer:null,
  drones:[],
  portalX:0, portalY:0,

  init(){
    this.active=true;
    this.grav=false;this.amp=false;this.over=false;this.portal=false;
    this.drones=[];
    clearInterval(this.gravTimer);clearTimeout(this.stormCycle);
    clearInterval(this.portalCheckInterval);clearTimeout(this.portalCloseTimer);
    this._setPanels();
    const pr=document.getElementById('ql-portal-ring');
    if(pr){pr.className='';pr.style.width='';pr.style.height='';}
    const sb=document.getElementById('ql-storm-banner');
    if(sb){sb.classList.remove('show');sb.textContent='';}
    // Spawn 3 starter drones
    SCIFI.aiSay('QUANTUM LAB ONLINE','dim');
    SCIFI.aiSay('TECH PANELS READY');
    setTimeout(()=>{
      ['attack','repair','shield'].forEach(k=>this._spawnDrone(k));
      SCIFI.aiSay('DRONE SQUADRON ACTIVE','dim');
    },1800);
    this._scheduleStorm();
  },

  stop(){
    this.active=false;
    clearInterval(this.gravTimer);
    clearTimeout(this.stormCycle);
    clearInterval(this.portalCheckInterval);
    clearTimeout(this.portalCloseTimer);
    this.drones=[];
    this.portal=false;
    this.grav=false;this.amp=false;this.over=false;
    const pr=document.getElementById('ql-portal-ring');if(pr)pr.className='';
    const sb=document.getElementById('ql-storm-banner');if(sb)sb.classList.remove('show');
    this._setPanels();
  },

  chargeMultiplier(){
    const base=this.amp?1.8:this.over?2.2:1;
    const bonus=typeof RL!=='undefined'?RL.chargeBonus():0;
    return base+bonus;
  },
  instabilityBonus(){return this.over?0.4:0;},

  togglePanel(id){
    if(!this.active)return;
    this[id]=!this[id];
    const btn=document.getElementById('ql-p-'+id);
    if(btn)btn.classList.toggle('active',this[id]);
    const s=document.getElementById('ql-s-'+id);
    if(s)s.textContent=this[id]?'ONLINE':'OFFLINE';
    const names={grav:'GRAVITY CONTROL',amp:'ENERGY AMPLIFIER',over:'REACTOR OVERCLOCK'};
    SCIFI.aiSay(`${names[id]} ${this[id]?'ONLINE':'OFFLINE'}`,this[id]?'warn':'dim');
    if(id==='grav')this._applyGrav();
    if(id==='over'&&this.over)SCIFI.aiSay('⚠ INSTABILITY RISK ELEVATED','err');
    if(id==='amp'&&this.amp)SCIFI.aiSay('CHARGE RATE ×1.8x');
  },

  _applyGrav(){
    clearInterval(this.gravTimer);
    if(!this.grav)return;
    this.gravTimer=setInterval(()=>{
      if(!this.active||!this.grav){clearInterval(this.gravTimer);return;}
      if(SCIFI.phase!=='idle')return;
      const cx=cW()/2,cy=cH()/2;
      [els.red,els.blue,els.green].forEach(e=>{
        if(e.classList.contains('hidden')||e===dragging)return;
        const c=getCenter(e),dx=cx-c.x,dy=cy-c.y;
        const dist=Math.hypot(dx,dy);
        if(dist<35)return;
        const f=0.9;
        setPos(e,parseFloat(e.style.left)+(dx/dist)*f,parseFloat(e.style.top)+(dy/dist)*f);
      });
    },16);
  },

  activatePortal(){
    if(!this.active||this.portal)return;
    if(SCIFI.phase!=='idle'){SCIFI.aiSay('PORTAL BLOCKED — FUSION ACTIVE','err');return;}
    this.portal=true;
    const btn=document.getElementById('ql-p-port');
    if(btn){btn.classList.add('active');btn.style.opacity='';}
    const s=document.getElementById('ql-s-port');if(s)s.textContent='ACTIVE';
    SCIFI.aiSay('PORTAL GENERATOR ONLINE','warn');
    SCIFI.aiSay('DRAG AN ORB INTO THE PORTAL');
    // Place portal at random position in canvas area
    const mg=90;
    this.portalX=mg+Math.random()*(cW()-mg*2);
    this.portalY=mg+Math.random()*(cH()-mg*2);
    const ring=document.getElementById('ql-portal-ring');
    ring.style.width='88px';ring.style.height='88px';
    ring.style.left=this.portalX+'px';ring.style.top=this.portalY+'px';
    ring.classList.remove('shrink');
    ring.classList.add('open');
    // Check if orb enters portal
    this.portalCheckInterval=setInterval(()=>{
      if(!this.active||!this.portal){clearInterval(this.portalCheckInterval);return;}
      [els.red,els.blue,els.green].forEach(e=>{
        if(e===dragging||e.classList.contains('hidden'))return;
        const c=getCenter(e);
        if(Math.hypot(c.x-this.portalX,c.y-this.portalY)<52){
          clearInterval(this.portalCheckInterval);
          this._orbEntersPortal(e);
        }
      });
    },50);
    // Auto-close after 9s if unused
    this.portalCloseTimer=setTimeout(()=>{
      if(this.portal){
        clearInterval(this.portalCheckInterval);
        this._closePortal(false);
        SCIFI.aiSay('PORTAL COLLAPSED — INSUFFICIENT ENERGY','err');
      }
    },9000);
  },

  _orbEntersPortal(orbEl){
    const c=getCenter(orbEl);
    spawnParticles(c.x,c.y,'#44ffcc',55,8);
    spawnShockwave(c.x,c.y,'rgba(68,255,200,',180,8);
    flashScreen('rgba(68,255,200,.3)',280);
    SFX.portalOpen();
    this._closePortal(true);
    if(Math.random()<0.5){
      // Teleport
      const mg=65;
      setPos(orbEl,mg+Math.random()*(cW()-mg*2)-R,mg+Math.random()*(cH()-mg*2)-R);
      spawnParticles(parseFloat(orbEl.style.left)+R,parseFloat(orbEl.style.top)+R,'#44ffcc',35,6);
      SCIFI.aiSay('ORB COORDINATES RANDOMIZED','warn');
    } else {
      // Duplicate ghost for 3s
      SCIFI.aiSay('⚠ ANOMALY: DUPLICATE SIGNATURE!','err');
      const ghost=orbEl.cloneNode(true);
      ghost.id='ql-ghost';ghost.style.opacity='.65';
      ghost.style.animation='none';ghost.style.pointerEvents='none';
      ghost.style.zIndex='25';ghost.style.filter='hue-rotate(90deg) brightness(1.2)';
      area.appendChild(ghost);
      const mg=65;
      setPos(ghost,mg+Math.random()*(cW()-mg*2)-R,mg+Math.random()*(cH()-mg*2)-R);
      spawnParticles(parseFloat(ghost.style.left)+R,parseFloat(ghost.style.top)+R,'#44ffcc',28,5);
      setTimeout(()=>{
        ghost.style.transition='opacity .45s';
        ghost.style.opacity='0';
        setTimeout(()=>{if(ghost.parentNode)ghost.parentNode.removeChild(ghost);},500);
        SCIFI.aiSay('DUPLICATE COLLAPSED','dim');
      },3000);
    }
  },

  _closePortal(immediate){
    this.portal=false;
    clearTimeout(this.portalCloseTimer);
    clearInterval(this.portalCheckInterval);
    const ring=document.getElementById('ql-portal-ring');
    if(ring){ring.classList.remove('open');ring.classList.add('shrink');}
    const btn=document.getElementById('ql-p-port');
    if(btn)btn.classList.remove('active');
    const s=document.getElementById('ql-s-port');
    if(s)s.textContent=immediate?'COOLDOWN':'READY';
    if(immediate&&btn){
      btn.style.opacity='.4';
      const _pcd=typeof RL!=='undefined'?RL.portalCooldown():6000;
      setTimeout(()=>{if(btn)btn.style.opacity='';const s2=document.getElementById('ql-s-port');if(s2)s2.textContent='READY';SCIFI.aiSay('PORTAL GENERATOR RECHARGED','dim');},_pcd);
    }
  },

  spawnDroneWave(){
    if(!this.active)return;
    const kinds=['attack','repair','shield'];
    const k=kinds[Math.floor(Math.random()*3)];
    this._spawnDrone(k);
    spawnSparks(cW()/2,cH()/2,'#44ffcc',8);
    SCIFI.aiSay(`${k.toUpperCase()} DRONE DEPLOYED`);
  },

  _spawnDrone(kind){
    this.drones.push({
      kind,
      angle:Math.random()*Math.PI*2,
      orbitR:88+Math.random()*35,
      speed:(.006+Math.random()*.009)*(Math.random()<.5?1:-1),
      pulse:Math.random()*Math.PI*2,
    });
  },

  drawDrones(ctx,cx,cy){
    if(!this.active||this.drones.length===0)return;
    const colors={attack:'rgba(255,90,90,',repair:'rgba(68,255,140,',shield:'rgba(68,160,255,'};
    this.drones.forEach(d=>{
      d.angle+=d.speed;
      d.pulse+=0.045;
      const x=cx+Math.cos(d.angle)*d.orbitR;
      const y=cy+Math.sin(d.angle)*d.orbitR*0.36;
      const al=0.5+0.3*Math.sin(d.pulse);
      const col=colors[d.kind];
      // Shadow
      ctx.shadowColor=col+'0.8)';ctx.shadowBlur=8;
      // Body
      ctx.beginPath();ctx.arc(x,y,4.5,0,Math.PI*2);
      ctx.fillStyle=col+al+')';ctx.fill();
      // Trail
      ctx.beginPath();
      ctx.arc(x-Math.cos(d.angle)*9,y-Math.sin(d.angle)*9*0.36,2,0,Math.PI*2);
      ctx.fillStyle=col+(al*.28)+')';ctx.fill();
      ctx.shadowBlur=0;
    });
  },

  _scheduleStorm(){
    if(!this.active)return;
    const delay=14000+Math.random()*18000;
    this.stormCycle=setTimeout(()=>{
      if(!this.active)return;
      const types=['ion','grav','burst'];
      this._triggerStorm(types[Math.floor(Math.random()*3)]);
      this._scheduleStorm();
    },delay);
  },

  _triggerStorm(type){
    const cfg={
      ion:  {label:'⚡ ION STORM',   color:'#ffff55',msg:'ION STORM INCOMING'},
      grav: {label:'🌀 GRAVITY SURGE',color:'#cc44ff',msg:'GRAVITATIONAL ANOMALY'},
      burst:{label:'💥 ENERGY BURST', color:'#ff6622',msg:'PLASMA DISCHARGE EVENT'},
    }[type];
    const banner=document.getElementById('ql-storm-banner');
    if(banner){banner.textContent=cfg.label;banner.style.color=cfg.color;banner.style.borderColor=cfg.color;banner.classList.add('show');}
    SCIFI.aiSay(`⚠ ${cfg.msg}`,'err');
    shake('md');
    if(type==='ion'){
      let n=0;
      const loop=setInterval(()=>{
        n++;
        flashScreen('rgba(255,255,80,.18)',80);
        spawnSparks(Math.random()*cW(),Math.random()*cH(),'#ffff44',7);
        if(n>=7){clearInterval(loop);if(banner)banner.classList.remove('show');}
      },320);
    } else if(type==='grav'){
      const ox=cW()/2,oy=cH()/2;
      let elapsed=0;
      const pull=setInterval(()=>{
        elapsed+=16;
        [els.red,els.blue,els.green].forEach(e=>{
          if(e.classList.contains('hidden')||e===dragging)return;
          const c=getCenter(e),dx=ox-c.x,dy=oy-c.y,dist=Math.hypot(dx,dy);
          if(dist<28)return;
          const _sc=typeof RL!=='undefined'?RL.stormScale():1;
          setPos(e,parseFloat(e.style.left)+(dx/dist)*2.8*_sc,parseFloat(e.style.top)+(dy/dist)*2.8*_sc);
        });
        if(elapsed>=2200){clearInterval(pull);if(banner)banner.classList.remove('show');}
      },16);
    } else {
      let n=0;
      const burst=setInterval(()=>{
        n++;
        const bx=60+Math.random()*(cW()-120),by=60+Math.random()*(cH()-120);
        spawnParticles(bx,by,'#ff6622',22,7);
        spawnShockwave(bx,by,'rgba(255,100,30,',110,5);
        flashScreen('rgba(255,70,0,.1)',100);
        if(n>=5){clearInterval(burst);if(banner)banner.classList.remove('show');}
      },480);
    }
  },

  _setPanels(){
    ['grav','amp','over'].forEach(id=>{
      const btn=document.getElementById('ql-p-'+id);
      if(btn)btn.classList.toggle('active',!!this[id]);
      const s=document.getElementById('ql-s-'+id);
      if(s)s.textContent=this[id]?'ONLINE':'OFFLINE';
    });
    const s=document.getElementById('ql-s-port');
    if(s)s.textContent='READY';
  },
};

// ══════════════════════════════════════════
// SCIFI NAV (view router)
// ══════════════════════════════════════════
const ScifiNav={
  current:'reactor',

  go(view){
    if(!QL.active)return;
    this.current=view;
    ['reactor','lab','experiments'].forEach(v=>{
      document.getElementById('snav-'+v)?.classList.toggle('active',v===view);
    });
    document.getElementById('rl-panel')?.classList.toggle('show',view==='lab');
    if(view==='lab'){
      RL.openPanel();
      SCIFI.aiSay('RESEARCH LAB ACCESS GRANTED','dim');
    } else if(view==='experiments'){
      SCIFI.aiSay('EXPERIMENT CONTROL PANELS','dim');
    } else {
      SCIFI.aiSay('REACTOR VIEW','dim');
    }
  },

  reset(){
    this.current='reactor';
    ['reactor','lab','experiments'].forEach(v=>{
      document.getElementById('snav-'+v)?.classList.toggle('active',v==='reactor');
    });
    document.getElementById('rl-panel')?.classList.remove('show');
    document.getElementById('snav-lab')?.classList.remove('notify');
  },

  notifyLab(){
    if(this.current!=='lab')
      document.getElementById('snav-lab')?.classList.add('notify');
  },
};

// ══════════════════════════════════════════
// RESEARCH LAB (idle research + offline progress)
// ══════════════════════════════════════════
const RL={
  SAVE_KEY:'ca_rl_v1',

  PROJECTS:[
    {
      id:'orb_resonance',
      name:'ORB RESONANCE',
      icon:'⊕',
      cat:'ORBITAL',
      dur:90,
      desc:'Orbs emit a proximity attraction field, easing natural alignment and fusion attempts.',
      effect:'orbResonance',
    },
    {
      id:'reactor_eff',
      name:'REACTOR EFFICIENCY',
      icon:'⚙',
      cat:'REACTOR',
      dur:120,
      desc:'Core charge rate boosted by +30%. Faster energy buildup accelerates all fusion events.',
      effect:'reactorEff',
    },
    {
      id:'void_core',
      name:'VOID CORE MATRIX',
      icon:'◈',
      cat:'CORES',
      dur:200,
      desc:'Unlocks VOID CORE — a rare dark energy class with extreme gravitational output and unique visual signature.',
      effect:'voidCore',
    },
    {
      id:'research_drone',
      name:'RESEARCH DRONE MK-II',
      icon:'🛸',
      cat:'DRONES',
      dur:150,
      desc:'Deploys a permanent autonomous research drone to the orbital laboratory. Assists in real-time analysis.',
      effect:'drone',
    },
    {
      id:'quantum_ent',
      name:'QUANTUM ENTANGLEMENT',
      icon:'∞',
      cat:'PORTAL',
      dur:240,
      desc:'Portal generator cooldown reduced by 66%. Quantum channel range expanded significantly.',
      effect:'quantumEnt',
    },
    {
      id:'plasma_shield',
      name:'PLASMA SHIELDING',
      icon:'⬡',
      cat:'DEFENSE',
      dur:100,
      desc:'Electromagnetic barriers reduce gravitational storm displacement forces by 50%.',
      effect:'plasmaShield',
    },
  ],

  _state:{active:null,startTime:0,completed:[],effects:{}},
  _tickTimer:null,

  init(){
    this._loadState();
    this._checkOffline();
    this._startTick();
    // Re-apply all completed effects silently
    this._state.completed.forEach(id=>{
      const p=this.PROJECTS.find(x=>x.id===id);
      if(p)this._applyEffect(p,false);
    });
  },

  stop(){
    clearInterval(this._tickTimer);
    this._saveState();
  },

  openPanel(){
    this._renderProjects();
    document.getElementById('snav-lab')?.classList.remove('notify');
    document.getElementById('rl-panel')?.scrollTo(0,0);
  },

  // Bonuses consumed by other systems
  chargeBonus(){return this._state.effects.reactorEff?0.3:0;},
  stormScale(){return this._state.effects.plasmaShield?0.5:1;},
  portalCooldown(){return this._state.effects.quantumEnt?2000:6000;},

  _loadState(){
    try{
      const raw=localStorage.getItem(this.SAVE_KEY);
      if(!raw)return;
      const s=JSON.parse(raw);
      if(s&&typeof s==='object'){
        this._state={
          active:s.active||null,
          startTime:Number(s.startTime)||0,
          completed:Array.isArray(s.completed)?s.completed:[],
          effects:(s.effects&&typeof s.effects==='object')?s.effects:{},
        };
      }
    }catch(e){/* corrupt save — use defaults */}
  },

  _saveState(){
    try{localStorage.setItem(this.SAVE_KEY,JSON.stringify(this._state));}catch(e){}
  },

  _checkOffline(){
    if(!this._state.active)return;
    const p=this.PROJECTS.find(x=>x.id===this._state.active);
    if(!p)return;
    const elapsed=(Date.now()-this._state.startTime)/1000;
    if(elapsed>=p.dur)this._completeProject(p,true);
  },

  _startTick(){
    clearInterval(this._tickTimer);
    this._tickTimer=setInterval(()=>{
      if(!this._state.active)return;
      const p=this.PROJECTS.find(x=>x.id===this._state.active);
      if(!p)return;
      const elapsed=(Date.now()-this._state.startTime)/1000;
      if(elapsed>=p.dur){this._completeProject(p,false);return;}
      this._saveState();
      // Update bar if panel is open
      const item=document.getElementById('rlp-'+p.id);
      if(!item)return;
      const pct=Math.min(100,(elapsed/p.dur)*100);
      const bar=item.querySelector('.rl-proj-bar');
      if(bar)bar.style.width=pct.toFixed(1)+'%';
      const timeEl=item.querySelector('.rl-proj-time');
      if(timeEl)timeEl.textContent=this._fmt(p.dur-elapsed)+' REMAINING';
    },1000);
  },

  startProject(id){
    if(this._state.active){SCIFI.aiSay('RESEARCH IN PROGRESS','warn');return;}
    if(this._state.completed.includes(id)){SCIFI.aiSay('ALREADY COMPLETED','dim');return;}
    const p=this.PROJECTS.find(x=>x.id===id);
    if(!p)return;
    this._state.active=id;
    this._state.startTime=Date.now();
    this._saveState();
    SCIFI.aiSay(`RESEARCH STARTED: ${p.name}`,'warn');
    SCIFI.aiSay(`EST. COMPLETION: ${this._fmt(p.dur)}`,'dim');
    this._renderProjects();
  },

  _completeProject(p,offline){
    this._state.completed.push(p.id);
    this._state.active=null;
    this._state.startTime=0;
    this._saveState();
    this._applyEffect(p,true);
    this._renderProjects();
    if(offline){
      // Show offline note
      const note=document.getElementById('rl-offline-note');
      if(note){
        note.textContent=`⬡ OFFLINE RESEARCH COMPLETE — ${p.name}`;
        note.classList.add('show');
        setTimeout(()=>note.classList.remove('show'),12000);
      }
      ScifiNav.notifyLab();
      setTimeout(()=>SCIFI.aiSay('OFFLINE RESEARCH FINISHED','warn'),500);
      setTimeout(()=>SCIFI.aiSay(`${p.name} COMPLETE`),900);
    } else {
      SCIFI.aiSay(`✓ ${p.name} COMPLETE`,'warn');
      SCIFI.aiSay('BREAKTHROUGH ACHIEVED');
      // Visual fanfare
      spawnParticles(cW()/2,cH()/3,'#44ffcc',40,6);
      spawnShockwave(cW()/2,cH()/3,'rgba(68,255,200,',120,5);
      flashScreen('rgba(68,255,200,.22)',420);
      SFX.reactorCharged();
    }
  },

  _applyEffect(p,announce){
    const say=m=>{if(announce)SCIFI.aiSay(m,'dim');};
    switch(p.effect){
      case 'orbResonance':
        this._state.effects.orbResonance=true;
        say('ORB RESONANCE FIELD ACTIVE');
        break;
      case 'reactorEff':
        this._state.effects.reactorEff=true;
        say('REACTOR EFFICIENCY +30%');
        break;
      case 'voidCore':{
        if(!SCIFI.CORE_TYPES.find(c=>c.id==='void')){
          SCIFI.CORE_TYPES.push({
            id:'void',name:'VOID CORE',color:'#1a0033',color2:'#440088',
            glow:'rgba(60,0,120,',rarity:'LEGENDARY',
            desc:'Dark energy anomaly\nEvent horizon forming',weight:6,
          });
        }
        say('VOID CORE UNLOCKED');
        break;
      }
      case 'drone':
        if(QL.active)QL._spawnDrone('repair');
        say('RESEARCH DRONE DEPLOYED');
        break;
      case 'quantumEnt':
        this._state.effects.quantumEnt=true;
        say('QUANTUM ENTANGLEMENT ONLINE');
        break;
      case 'plasmaShield':
        this._state.effects.plasmaShield=true;
        say('PLASMA SHIELDING ACTIVE');
        break;
    }
    this._saveState();
  },

  _fmt(secs){
    secs=Math.max(0,Math.floor(secs));
    const m=Math.floor(secs/60),s=secs%60;
    return m>0?`${m}m ${s.toString().padStart(2,'0')}s`:`${s}s`;
  },

  _renderProjects(){
    const c=document.getElementById('rl-projects');
    if(!c)return;
    c.innerHTML='';
    this.PROJECTS.forEach(p=>{
      const done=this._state.completed.includes(p.id);
      const active=this._state.active===p.id;
      const elapsed=active?(Date.now()-this._state.startTime)/1000:0;
      const pct=active?Math.min(100,(elapsed/p.dur)*100):done?100:0;
      const timeStr=active
        ?this._fmt(p.dur-elapsed)+' REMAINING'
        :done?'COMPLETE':this._fmt(p.dur);
      const btnLabel=done?'✓ COMPLETE':active?'WORKING...':'▶ RESEARCH';
      const btnDis=(done||active||!!this._state.active)?'disabled':'';
      const div=document.createElement('div');
      div.className='rl-project'+(active?' researching':done?' done':'');
      div.id='rlp-'+p.id;
      div.innerHTML=
        `<div class="rl-project-head">`+
          `<span class="rl-proj-icon">${p.icon}</span>`+
          `<span class="rl-proj-name">${p.name}</span>`+
          `<span class="rl-proj-cat">${p.cat}</span>`+
        `</div>`+
        `<div class="rl-proj-desc">${p.desc}</div>`+
        `<div class="rl-proj-bar-wrap"><div class="rl-proj-bar" style="width:${pct.toFixed(1)}%"></div></div>`+
        `<div class="rl-proj-foot">`+
          `<span class="rl-proj-time">${timeStr}</span>`+
          `<button class="rl-proj-btn" ${btnDis} onclick="RL.startProject('${p.id}')">${btnLabel}</button>`+
        `</div>`;
      c.appendChild(div);
    });
  },
};

// ══════════════════════════════════════════
function updateBeams(rb,bg,rg){
  const cr=getCenter(els.red),cb=getCenter(els.blue),cg=getCenter(els.green);
  function setB(line,c1,c2,active,col){
    if(active){line.setAttribute('x1',c1.x);line.setAttribute('y1',c1.y);line.setAttribute('x2',c2.x);line.setAttribute('y2',c2.y);line.setAttribute('stroke',col);line.style.opacity='.9';}
    else line.style.opacity='0';
  }
  setB(els.beamRB,cr,cb,rb,'#ff88aa');setB(els.beamRG,cr,cg,rg,'#88ffaa');setB(els.beamBG,cb,cg,bg,'#88aaff');
  els.beamSvg.classList.toggle('show',rb||bg||rg);
}
function updateEnergy(rb,bg,rg){
  const pct=(rb?33:0)+(bg?33:0)+(rg?34:0);
  els.energyFill.style.width=pct+'%';els.energyVal.textContent=pct+'%';
}

