function triggerMeltdown(cx,cy){
  metaTrack('rareEvents',1);
  metaUnlockDiscovery('meltdown');
  FUSION_MODE.recordOutcome('meltdown_cascade');
  FUSION_MODE.recordEvent('meltdown_event','☢ MELTDOWN CASCADE','#ff8844');
  Object.assign(els.gold.style,{
    width:'122px',height:'122px',left:cx+'px',top:cy+'px',
    background:'radial-gradient(circle at 38% 35%,#fffde0,#f5c842 40%,#c87800)',
    boxShadow:'0 0 60px 20px rgba(245,200,66,.7),0 0 120px 50px rgba(245,200,66,.3),inset 0 2px 0 rgba(255,255,255,.5)',
    animation:'',filter:'',transition:'opacity .4s,transform .5s cubic-bezier(.175,.885,.32,1.4)',pointerEvents:'none',
  });
  els.orbText.textContent='GOLD';els.orbIcon.textContent='✦';els.bossPhaseLabel.textContent='';
  els.gold.classList.add('visible');
  flashScreen('rgba(255,220,80,.45)');
  setStatus('✦ FUSION COMPLETE — CLICK ORB TO—','merged');

  // T+0.0s — normal message appears
  showMsg('FUSION COMPLE—','','var(--gold)');

  // T+0.7s — message glitches, trembling begins
  setTimeout(()=>{
    els.fusionMsg.classList.remove('show');
    els.fusionTitle.textContent='FUSION COMPLE—';
    els.fusionTitle.style.color='#ff5533';
    els.fusionSub.textContent='CRITICAL INSTABILITY DETECTED';
    els.fusionMsg.classList.add('show');
    setStatus('⚠ CORE UNSTABLE — CRITICAL FAILURE IMMINENT','danger');
    els.gold.classList.add('trembling');
    shake('sm');
    spawnSparks(cx,cy,'#ff4422',10);spawnSparks(cx,cy,'#ffffff',6);
    SFX.meltdownWarn();
  },700);

  // T+1.4s — collapse begins
  setTimeout(()=>{
    els.fusionMsg.classList.remove('show');
    setStatus('☠ SINGULARITY FORMING — EVACUATE','danger');
    els.gold.classList.remove('trembling');
    flashScreen('rgba(255,60,30,.5)');shake('md');
    const collapseStart=Date.now();
    const loop=setInterval(()=>{
      const p=Math.min(1,(Date.now()-collapseStart)/850);
      const e2=p*p;
      const s=122*(1-e2*.98);
      const br=1+e2*4;
      Object.assign(els.gold.style,{
        width:s+'px',height:s+'px',
        filter:`brightness(${br}) saturate(${1+e2*5})`,
        boxShadow:`0 0 ${25+e2*90}px ${8+e2*60}px rgba(255,${Math.floor(200-e2*190)},${Math.floor(80-e2*80)},.95)`,
      });
      if(Math.random()<.25+e2*.5){
        const a=Math.random()*Math.PI*2,d=30+Math.random()*70;
        spawnSparks(cx+Math.cos(a)*d,cy+Math.sin(a)*d,'#ffaa00',2);
      }
      if(p>=1){clearInterval(loop);els.gold.classList.remove('visible');doSingularity(cx,cy);}
    },16);
  },1400);
}

function doSingularity(cx,cy){
  metaUnlockDiscovery('singularity_echo');
  FUSION_MODE.recordOutcome('singularity_echo',{quiet:true});
  flashScreen('rgba(0,0,0,.92)',350);shake('lg');
  SFX.singularity();

  // Space distortion lens
  els.spaceDistort.style.setProperty('--bx',(cx/window.innerWidth*100)+'%');
  els.spaceDistort.style.setProperty('--by',(cy/window.innerHeight*100)+'%');
  els.spaceDistort.classList.add('show');
  document.body.classList.add('meltdown-warp');
  els.stars.classList.add('pulling');

  // Pull circles inward
  const pull=setInterval(()=>{
    [els.red,els.blue,els.green].forEach(e=>{
      const c=getCenter(e);
      const ang=Math.atan2(cy-c.y,cx-c.x);
      const dist=Math.hypot(c.x-cx,c.y-cy);
      const f=Math.max(3,22-(dist*.04));
      setPos(e,parseFloat(e.style.left)+Math.cos(ang)*f,parseFloat(e.style.top)+Math.sin(ang)*f);
      if(Math.random()<.2) spawnSparks(c.x,c.y,['#ff4455','#4488ff','#44ee88'][~~(Math.random()*3)],2);
    });
    spawnSparks(cx+(-90+Math.random()*180),cy+(-90+Math.random()*180),'#ffffff',1);
  },55);

  // Tiny singularity dot — positioned in canvas-area (absolute), not fixed
  const dot=document.createElement('div');
  dot.id='meltdown-dot';
  dot.style.cssText=`position:absolute;border-radius:50%;z-index:78;pointer-events:none;
    left:${cx}px;top:${cy}px;width:4px;height:4px;transform:translate(-50%,-50%);
    background:#000;box-shadow:0 0 10px 4px rgba(100,0,200,.9),0 0 0 2px #fff;
    transition:width 1.8s ease,height 1.8s ease,box-shadow 1.8s ease;`;
  area.appendChild(dot);
  setTimeout(()=>{
    dot.style.width='24px';dot.style.height='24px';
    dot.style.boxShadow='0 0 50px 24px rgba(60,0,160,.95),0 0 100px 50px rgba(20,0,80,.6),0 0 0 3px rgba(200,150,255,.6)';
  },60);

  // Text
  els.meltdownLine1.textContent='SINGULARITY';els.meltdownLine1.style.color='#cc66ff';
  els.meltdownLine2.textContent='GRAVITY BEYOND CONTAINMENT';els.meltdownLine2.style.color='rgba(210,170,255,.7)';
  els.meltdownOverlay.classList.add('show');
  setTimeout(()=>els.meltdownLine1.style.opacity='1',200);
  setTimeout(()=>els.meltdownLine2.style.opacity='1',1000);

  // T+2.4s: freeze flash
  setTimeout(()=>{
    clearInterval(pull);
    els.meltdownLine1.textContent='⚠';els.meltdownLine1.style.color='#fff';
    els.meltdownLine2.style.opacity='0';
    flashScreen('rgba(255,255,255,.15)',600);
  },2400);

  // T+2.9s: SUPERNOVA
  setTimeout(()=>{ dot.remove(); doSupernova(cx,cy); },2900);
}

function doSupernova(cx,cy){
  metaUnlockDiscovery('supernova_burst');
  FUSION_MODE.recordOutcome('supernova_burst',{quiet:true});
  FUSION_MODE.recordEvent('supernova_burst','☀ SUPERNOVA BURST','#ffd68a');
  els.meltdownLine1.textContent='SUPERNOVA';
  els.meltdownLine1.style.fontSize='clamp(2rem,9vw,5rem)';
  els.meltdownLine1.style.textShadow='0 0 60px #fff,0 0 130px rgba(255,180,80,.9)';
  els.meltdownLine2.textContent='CONTAINMENT FAILED';
  els.meltdownLine2.style.opacity='1';els.meltdownLine2.style.color='rgba(255,220,180,.6)';
  SFX.supernova();

  // White-out flash
  const sn=els.supernovaFlash;
  sn.style.transition='none';sn.style.opacity='1';
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    sn.style.transition='opacity 2s ease';sn.style.opacity='0';
  }));

  shake('lg');setTimeout(()=>shake('lg'),180);setTimeout(()=>shake('md'),450);setTimeout(()=>shake('sm'),700);

  const cols=['#ffffff','#ffee88','#ff8844','#ff5533','#cc44ff','#44aaff'];
  for(let w=0;w<6;w++){
    setTimeout(()=>{
      flashScreen(`rgba(255,${180-w*20},${100-w*12},.5)`,90);
      spawnParticles(cx,cy,cols[w],80,10+w*2);
      spawnSparks(cx,cy,cols[w],20);
      spawnShockwave(cx,cy,`rgba(255,${180-w*25},255,`,cW()*.75+w*90,9+w);
    },w*175);
  }
  for(let i=0;i<8;i++){
    setTimeout(()=>{
      const a=(i/8)*Math.PI*2;
      spawnParticles(cx+Math.cos(a)*110,cy+Math.sin(a)*110,cols[i%6],45,7);
    },i*130);
  }

  // T+2.2s after supernova: slow stabilization
  setTimeout(()=>{
    els.meltdownLine1.style.opacity='0';
    els.meltdownLine2.textContent='…stabilizing…';
    els.meltdownLine2.style.color='rgba(180,220,255,.4)';
    document.body.classList.remove('meltdown-warp');
    els.spaceDistort.classList.remove('show');
    els.stars.classList.remove('pulling');
    els.stars.classList.add('restoring');
    setTimeout(()=>els.stars.classList.remove('restoring'),3500);

    // Restore circles gently
    popCirclesOut();
    [els.red,els.blue,els.green].forEach(e=>{
      e.classList.remove('fading');
      ['opacity','transform','pointerEvents','transition'].forEach(p=>e.style[p]='');
    });
    setStatus('…NORMAL SPACE RESTORED…','merged');
  },2200);

  // T+5s: fully done
  setTimeout(()=>{
    els.meltdownLine2.style.opacity='0';
    setTimeout(()=>{
      els.meltdownOverlay.classList.remove('show');
      els.meltdownLine1.style.opacity='0';
      els.meltdownLine1.style.fontSize='';els.meltdownLine1.style.textShadow='';
    },600);
    merged=false;
    setStatus(modeHint());
    // No restart button — circles auto-restore after meltdown
  },5000);
}

function startOrbPersonality(perfect,{pulse,sparkColor}={}){
  if(orbPersonalityTimer)clearInterval(orbPersonalityTimer);
  els.gold.style.animation=pulse||SKINS.getGoldPulse(perfect);
  els.gold.style.marginTop='0px';
  let t=0;
  orbPersonalityTimer=setInterval(()=>{
    if(!els.gold.classList.contains('visible')){clearInterval(orbPersonalityTimer);return;}
    t+=0.04;
    els.gold.style.marginTop=(Math.sin(t)*4)+'px';
    if(Math.random()<.07){
      const cx=parseFloat(els.gold.style.left);
      const cy=parseFloat(els.gold.style.top);
      spawnSparks(cx+(-40+Math.random()*80),cy+(-40+Math.random()*80),sparkColor||SKINS.getGoldSparkColor(),2);
    }
  },50);
}

function clearGoldSkinAmbient(){
  if(goldSkinAmbientTimer){clearInterval(goldSkinAmbientTimer);goldSkinAmbientTimer=null;}
  if(els.goldSkinFx) els.goldSkinFx.innerHTML='';
}

function spawnGoldRainDrop(cx,cy,type='diamond'){
  const drop=document.createElement('div');
  const size=type==='diamond'?5+Math.random()*6:4+Math.random()*5;
  const startX=cx-60+Math.random()*120;
  const startY=cy-120+Math.random()*20;
  const dur=520+Math.random()*620;
  const dx=-22+Math.random()*44;
  const dy=110+Math.random()*130;
  const spin=-120+Math.random()*240;
  drop.className=`gold-rain-drop ${type}`;
  drop.style.left=`${startX}px`;
  drop.style.top=`${startY}px`;
  drop.style.width=`${size}px`;
  drop.style.height=`${size}px`;
  drop.style.setProperty('--dur',`${dur}ms`);
  drop.style.setProperty('--dx',`${dx}px`);
  drop.style.setProperty('--dy',`${dy}px`);
  drop.style.setProperty('--rot',`${Math.random()*60}deg`);
  drop.style.setProperty('--spin',`${spin}deg`);
  area.appendChild(drop);
  setTimeout(()=>drop.remove(),dur+80);
}

function startGoldSkinAmbient(skinId){
  if(!els.gold.classList.contains('visible')) return;
  if(els.goldSkinFx) els.goldSkinFx.innerHTML=SKINS.goldSkinMarkup(skinId);
  if(goldSkinAmbientTimer){clearInterval(goldSkinAmbientTimer);goldSkinAmbientTimer=null;}
  if(skinId==='gold_default') return;
  goldSkinAmbientTimer=setInterval(()=>{
    if(!els.gold.classList.contains('visible')){clearGoldSkinAmbient();return;}
    const cx=parseFloat(els.gold.style.left)||0;
    const cy=parseFloat(els.gold.style.top)||0;
    if(skinId==='gold_diamond'){
      spawnGoldRainDrop(cx,cy,'diamond');
      if(Math.random()<.32) SFX.diamondTinkle();
      return;
    }
    if(skinId==='gold_sunforge'){
      spawnGoldRainDrop(cx,cy,'ember');
      spawnSparks(cx+(-38+Math.random()*76),cy+(-34+Math.random()*68),'#ff9c3f',2);
      return;
    }
    if(skinId==='gold_royal'){
      spawnGoldRainDrop(cx,cy,'royal');
      spawnParticles(cx+(-24+Math.random()*48),cy+(-28+Math.random()*56),'#d7a8ff',2,2);
      return;
    }
    if(skinId==='gold_nova'){
      spawnParticles(cx+(-18+Math.random()*36),cy+(-18+Math.random()*36),'#fff0a6',4,2);
      return;
    }
    if(skinId==='gold_void'){
      spawnGoldRainDrop(cx,cy,'void');
      spawnParticles(cx+(-20+Math.random()*40),cy+(-20+Math.random()*40),'#a978ff',2,2);
    }
  },skinId==='gold_diamond'?150:240);
}

function startSpecialFusionAmbient(fusionId){
  if(!els.gold.classList.contains('visible')) return;
  if(goldSkinAmbientTimer){clearInterval(goldSkinAmbientTimer);goldSkinAmbientTimer=null;}
  goldSkinAmbientTimer=setInterval(()=>{
    if(!els.gold.classList.contains('visible')){clearGoldSkinAmbient();return;}
    const cx=parseFloat(els.gold.style.left)||0;
    const cy=parseFloat(els.gold.style.top)||0;
    if(fusionId==='golden_titan'){
      spawnParticles(cx+(-20+Math.random()*40),cy+(-20+Math.random()*40),'#fff1a8',5,3);
      spawnParticles(cx+(-28+Math.random()*56),cy+(-28+Math.random()*56),'#ffb55a',3,3);
      if(Math.random()<.42) spawnSparks(cx+(-42+Math.random()*84),cy+(-42+Math.random()*84),'#fff4b8',3);
      return;
    }
    spawnGoldRainDrop(cx,cy,'royal');
    spawnParticles(cx+(-18+Math.random()*36),cy+(-22+Math.random()*44),'#d7a8ff',2,2);
    if(Math.random()<.35) spawnSparks(cx+(-34+Math.random()*68),cy+(-34+Math.random()*68),'#ffd56a',2);
  },fusionId==='golden_titan'?170:230);
}

function playGoldSplitEffect(cx,cy,skinId,perfect=false){
  if(skinId==='gold_diamond'){
    flashScreen('rgba(200,255,255,.55)',120);
    shake('md');
    spawnParticles(cx,cy,'#aeefff',72,10);
    spawnParticles(cx,cy,'#ffffff',34,12);
    spawnShockwave(cx,cy,'rgba(170,238,255,',220,9);
    for(let i=0;i<14;i++) setTimeout(()=>spawnGoldRainDrop(cx,cy,'diamond'),i*28);
    SFX.diamondRain();
    return;
  }
  if(skinId==='gold_sunforge'){
    flashScreen('rgba(255,180,60,.4)',90);
    shake('md');
    spawnParticles(cx,cy,'#ffb352',90,10);
    spawnParticles(cx,cy,'#ff6d24',48,11);
    spawnShockwave(cx,cy,'rgba(255,140,40,',210,9);
    return;
  }
  if(skinId==='gold_royal'){
    flashScreen('rgba(255,214,110,.36)',90);
    spawnParticles(cx,cy,'#ffd86f',64,9);
    spawnParticles(cx,cy,'#b98eff',34,8);
    spawnShockwave(cx,cy,'rgba(204,142,255,',190,8);
    return;
  }
  if(skinId==='gold_nova'){
    flashScreen('rgba(255,248,180,.72)',120);
    shake('lg');
    spawnParticles(cx,cy,'#fff4b8',110,13);
    spawnParticles(cx,cy,'#ffffff',60,14);
    spawnShockwave(cx,cy,'rgba(255,228,120,',260,11);
    return;
  }
  if(skinId==='gold_void'){
    flashScreen('rgba(106,58,180,.46)',110);
    shake('md');
    spawnParticles(cx,cy,'#b68cff',80,9);
    spawnParticles(cx,cy,'#2c1146',48,7);
    spawnShockwave(cx,cy,'rgba(126,90,255,',220,8);
    return;
  }
  flashScreen(perfect?'rgba(255,245,180,.52)':'rgba(255,220,80,.34)',90);
  spawnParticles(cx,cy,'#f5c842',58,8);
  if(perfect) spawnParticles(cx,cy,'#ffffff',28,11);
  spawnShockwave(cx,cy,perfect?'rgba(255,235,150,':'rgba(255,190,70,',perfect?200:150,7);
}

function playSpecialFusionSplitEffect(cx,cy,fusionId){
  if(fusionId==='golden_titan'){
    flashScreen('rgba(255,244,186,.7)',130);
    shake('lg');
    spawnParticles(cx,cy,'#fff4b8',92,12);
    spawnParticles(cx,cy,'#ffb55a',54,14);
    spawnParticles(cx,cy,'#ffffff',36,16);
    spawnShockwave(cx,cy,'rgba(255,228,150,',250,10);
    for(let i=0;i<3;i++) setTimeout(()=>spawnSparks(cx+(-46+Math.random()*92),cy+(-46+Math.random()*92),'#fff1a8',8),i*80);
    return;
  }
  flashScreen('rgba(255,218,110,.54)',110);
  shake('md');
  spawnParticles(cx,cy,'#ffd56a',70,10);
  spawnParticles(cx,cy,'#8f58ff',24,10);
  spawnParticles(cx,cy,'#ffffff',24,12);
  spawnShockwave(cx,cy,'rgba(255,214,110,',210,8);
}

