const BOSS_RUN_DEFS=[
  {name:'GOLD TYRANT',color:'#f5c842',color2:'#c87800',glow:'rgba(245,200,66,',ring:'#ffcc00',hp:100,ringSize:1.5,warningText:'BOSS AWAKENED',warningColor:'#ff4400',rewardTitle:'⚔ WARRIOR TITLE',icon:'☠'},
  {name:'GIANT OVERLORD',color:'#ff8800',color2:'#cc4400',glow:'rgba(255,120,0,',ring:'#ff6600',hp:150,ringSize:1.6,warningText:'TITAN RISES',warningColor:'#ff5522',rewardTitle:'🏆 GIANT SLAYER',icon:'☠'},
  {name:'RAINBOW CHAOS',color:'#ff44ff',color2:'#4444ff',glow:'rgba(200,100,255,',ring:'#aa44ff',hp:200,ringSize:1.7,warningText:'CHAOS UNLEASHED',warningColor:'#ff66ff',rewardTitle:'🌈 CHAOS MASTER',icon:'☠'},
  {name:'VOID EMPEROR',color:'#222244',color2:'#000011',glow:'rgba(80,40,200,',ring:'#6644ff',hp:250,ringSize:1.8,warningText:'VOID STIRS',warningColor:'#cc88ff',rewardTitle:'🌑 VOID BREAKER',icon:'☠'},
  {name:'STORM JUDICATOR',color:'#9cecff',color2:'#1270bd',glow:'rgba(90,210,255,',ring:'#7fe7ff',hp:320,ringSize:1.82,warningText:'TEMPEST LOCKS ON',warningColor:'#7fe7ff',rewardTitle:'⛈ STORM RENDER',moveSpeed:2.6,attackInterval:3300,icon:'⚡'},
  {name:'CRYSTAL BEHEMOTH',color:'#dffcff',color2:'#3aa9d4',glow:'rgba(170,245,255,',ring:'#b8f6ff',hp:380,ringSize:1.86,warningText:'CRYSTAL MASS FORMS',warningColor:'#b8f6ff',rewardTitle:'💎 SHARD REAPER',moveSpeed:2.9,attackInterval:3200,icon:'◆'},
  {name:'PLASMA WARDEN',color:'#ffd08a',color2:'#ff5baf',glow:'rgba(255,130,180,',ring:'#ff9bd0',hp:440,ringSize:1.9,warningText:'PLASMA WALL IGNITES',warningColor:'#ff9bd0',rewardTitle:'🔥 PLASMA BREAKER',moveSpeed:3.2,attackInterval:3050,icon:'✦'},
  {name:'CELESTIAL HYDRA',color:'#f2f7ff',color2:'#6487ff',glow:'rgba(160,190,255,',ring:'#b8c7ff',hp:510,ringSize:1.95,warningText:'HEADS OF LIGHT DESCEND',warningColor:'#b8c7ff',rewardTitle:'🌌 STAR HUNTER',moveSpeed:3.5,attackInterval:2950,icon:'✶'},
  {name:'SINGULARITY MONARCH',color:'#f3eaff',color2:'#7a2dca',glow:'rgba(190,120,255,',ring:'#d2a2ff',hp:580,ringSize:2.0,warningText:'GRAVITY BENDS TO THE THRONE',warningColor:'#d2a2ff',rewardTitle:'◉ EVENT HORIZON',moveSpeed:3.9,attackInterval:2850,phase2Scale:1.32,phase3Scale:1.58,icon:'◉'},
  {name:'OBLIVION CROWN',color:'#ffffff',color2:'#5b133b',glow:'rgba(255,140,210,',ring:'#ff9fd2',hp:660,ringSize:2.05,warningText:'THE CROWN OPENS THE VOID',warningColor:'#ff9fd2',rewardTitle:'👑 VOID REGENT',moveSpeed:4.2,attackInterval:2725,phase2Scale:1.34,phase3Scale:1.6,icon:'♛'},
  {name:'THE ULTIMATE',displayName:'ULTIMATE',color:'#ffffff',color2:'#8800ff',glow:'rgba(200,150,255,',ring:'#cc88ff',hp:760,ringSize:2.1,warningText:'THE ULTIMATE AWAKENS',warningSub:'ALL PREVIOUS FORMS COMBINED',warningColor:'#cc88ff',phaseLabel:'THE ULTIMATE — FINAL BOSS',tierLabel:'⚡ FINAL APEX — RUN 11',rewardTitle:'∞ INFINITE SIGNAL',moveSpeed:4.8,attackInterval:2600,phase1Size:175,phase2Scale:1.3,phase3Scale:1.55,final:true,icon:'⬡'}
];
const BOSS_TIERS=BOSS_RUN_DEFS.filter(def=>!def.final);
const ULTIMATE_TIER=BOSS_RUN_DEFS[BOSS_RUN_DEFS.length-1];
const BOSS_FINAL_RUN=BOSS_RUN_DEFS.length;
const BOSS_STANDARD_RUNS=BOSS_FINAL_RUN-1;

function getBossTier(run=bossRun){
  return BOSS_RUN_DEFS[Math.max(0,Math.min(run-1,BOSS_RUN_DEFS.length-1))];
}

function getBossPhase1Size(tier,run=bossRun){
  return tier.phase1Size||Math.min(280,160+(run*12));
}

function getBossPhase2Size(tier,run=bossRun){
  return getBossPhase1Size(tier,run)*(tier.phase2Scale||1.35);
}

function getBossPhase3Size(tier,run=bossRun){
  return getBossPhase1Size(tier,run)*(tier.phase3Scale||1.7);
}

function spawnBossRun(run,cx,cy){
  const tier=getBossTier(run);
  bossRun=run;
  bossMaxHp=tier.hp;
  bossCurrentHp=tier.hp;
  bossPhase=0;bossPhase2Reached=false;bossPhase3Reached=false;
  bossAlive=true;
  bossX=cx;bossY=cy;
  bossSize=tier.final?110:90;
  bossTargetSize=getBossPhase1Size(tier,run);

  els.orbIcon.textContent=tier.icon||'☠';
  els.orbText.textContent=tier.displayName||tier.name;
  els.bossPhaseLabel.textContent='';

  Object.assign(els.gold.style,{
    width:bossSize+'px',height:bossSize+'px',left:cx+'px',top:cy+'px',
    background:`radial-gradient(circle at 38% 35%,#ffffff,${tier.color} 40%,${tier.color2})`,
    boxShadow:tier.final
      ? '0 0 40px 15px rgba(200,150,255,.8),0 0 80px 30px rgba(100,0,255,.4)'
      : `0 0 20px 8px ${tier.glow}0.5),0 0 40px 16px ${tier.glow}0.2)`,
    animation:'none',pointerEvents:'all',cursor:'pointer',transition:'opacity .4s,width .1s,height .1s,left .1s,top .1s',
  });
  els.gold.classList.add('visible');
  els.gold.onclick=bossClick;

  els.bossHpBar.classList.add('show');
  els.bossHpFill.style.width='100%';
  els.bossHpFill.style.background=tier.final
    ? 'linear-gradient(90deg,#330099,#8800ff,#cc88ff,#ffffff)'
    : `linear-gradient(90deg,${tier.color2},${tier.color})`;
  els.bossPhaseInd.textContent=tier.phaseLabel||'PHASE 1 — AWAKENING';
  els.bossPhaseInd.style.color=tier.final?'#cc88ff':'#ff9955';

  els.bossTier.textContent=tier.tierLabel||`RUN #${bossRun} — ${tier.name}`;
  els.bossTier.classList.add('show');

  document.body.classList.add('boss-arena');
  document.body.classList.toggle('ultimate-arena',!!tier.final);
  els.header.classList.add('boss-header');
  document.querySelector('.tab:last-child').classList.add('boss-active');
  els.bossVignette.classList.add('show');

  growBoss();

  flashScreen(tier.final?'rgba(150,80,255,.7)':'rgba(255,100,0,.6)');
  shake(tier.final?'lg':'md');
  setTimeout(()=>{
    els.bossOverlay.classList.add('show');
    els.bossWarningText.textContent=tier.warningText||`ROUND ${bossRun} ENGAGED`;
    els.bossWarningText.style.color=tier.warningColor||'#ff4400';
    els.bossWarningSub.textContent=tier.warningSub||(`${tier.name} — GOLD CORE UNSTABLE`);
    setTimeout(()=>els.bossOverlay.classList.remove('show'),tier.final?2800:2500);
  },300);

  setStatus(tier.final?'⚡ THE FINAL APEX — CLICK TO STRIKE!':'CLICK THE BOSS TO DAMAGE IT!','boss-status');
  bossStartPhase1();
}

function triggerBoss(cx,cy){
  metaUnlockDiscovery('first_boss');
  if(advActive) advExit();
  const nextRun=Math.min(Math.max(bossRun,0)+1,BOSS_STANDARD_RUNS);
  spawnBossRun(nextRun,cx,cy);
}

// ── GROW BOSS ──
function growBoss(){
  const tier=getBossTier();
  bossTargetSize=getBossPhase1Size(tier,bossRun);
  animateBossSize();
}

let bossGrowAnim=null;
function animateBossSize(){
  if(bossGrowAnim)clearInterval(bossGrowAnim);
  bossGrowAnim=setInterval(()=>{
    if(!bossAlive){clearInterval(bossGrowAnim);return;}
    const diff=bossTargetSize-bossSize;
    if(Math.abs(diff)<1){bossSize=bossTargetSize;clearInterval(bossGrowAnim);return;}
    bossSize+=diff*.12;
    applyBossOrbSize();
  },16);
}

function applyBossOrbSize(){
  const half=bossSize/2;
  els.gold.style.width=bossSize+'px';
  els.gold.style.height=bossSize+'px';
  els.gold.style.left=(bossX-half)+'px'; // note: boss is NOT using translate(-50%,-50%) here — we manage manually
  // Actually the orb uses translate(-50%) in CSS, so just set left/top to center
  els.gold.style.left=bossX+'px';
  els.gold.style.top=bossY+'px';
  // Update ring
  const ringSize=bossSize*1.5;
  Object.assign(els.ring.style,{width:ringSize+'px',height:ringSize+'px',left:bossX+'px',top:bossY+'px'});
}

// ── PHASE 1: AWAKENING ──
function bossStartPhase1(){
  bossPhase=1;
  const tier=getBossTier();
  els.gold.style.animation=`pulse-gold 2s ease-in-out infinite`;

  // Spawn ring
  const ringSize=bossTargetSize*1.5;
  Object.assign(els.ring.style,{
    width:ringSize+'px',height:ringSize+'px',left:bossX+'px',top:bossY+'px',
    borderColor:tier.ring,
    boxShadow:`0 0 12px ${tier.ring},inset 0 0 8px ${tier.ring}`,
    borderStyle:'dashed',
  });
  els.ring.classList.add('show');

  // Continuous ambient sparks
  bossSparkInterval=setInterval(()=>{
    if(!bossAlive)return;
    spawnSparks(bossX,bossY,tier.color,4);
  },400);

  // Periodic rumble
  bossRumbleInterval=setInterval(()=>{
    if(!bossAlive)return;
    if(bossPhase>=2){shake('sm');spawnShockwave(bossX,bossY,tier.glow,160,5);}
  },4000);

  bossAttackInterval=setInterval(()=>{
    if(!bossAlive||bossPhase<2)return;
    bossAttack();
  },tier.attackInterval||3500);
}

// ── PHASE 2: ANGRY ──
function bossStartPhase2(){
  if(bossPhase2Reached)return;
  bossPhase2Reached=true;bossPhase=2;
  const tier=getBossTier();
  bossTargetSize=getBossPhase2Size(tier,bossRun);animateBossSize();

  document.body.classList.remove('boss-arena');document.body.classList.add('boss-phase2');
  els.bossPhaseInd.textContent='PHASE 2 — ANGRY MODE';els.bossPhaseInd.style.color='#ff5522';
  els.bossHpFill.style.background=`linear-gradient(90deg,#aa0000,${tier.color2},${tier.color})`;

  els.gold.style.animation='pulse-gold .8s ease-in-out infinite';
  els.ring.style.borderStyle='solid';els.ring.style.animation='spin-ring 1s linear infinite';

  shake('md');flashScreen('rgba(255,60,0,.5)');
  spawnParticles(bossX,bossY,tier.color,50);
  showMsg('PHASE 2','BOSS IS ANGRY — ATTACKS INCOMING','#ff6622');
  setStatus('⚠ ANGRY MODE — HIT IT FASTER!','danger');
  toast('⚡ BOSS ENTERS ANGRY MODE!','#ff6633');
  SFX.bossPhase(2);

  // Start moving the boss around the arena
  let mdir=Math.random()*Math.PI*2;
  let mspeed=tier.moveSpeed||1.2+bossRun*.3;
  bossMoveInterval=setInterval(()=>{
    if(!bossAlive||bossPhase<2){clearInterval(bossMoveInterval);return;}
    mdir+=(.3-Math.random()*.6);
    const newX=bossX+Math.cos(mdir)*mspeed;
    const newY=bossY+Math.sin(mdir)*mspeed;
    const margin=bossSize/2+20;
    const W=cW(),H=cH();
    bossX=Math.max(margin,Math.min(W-margin,newX));
    bossY=Math.max(margin+40,Math.min(H-margin,newY));
    applyBossOrbSize();
    // Also update ring position
    els.ring.style.left=bossX+'px';els.ring.style.top=bossY+'px';
  },16);
}

// ── PHASE 3: OVERLOAD ──
function bossStartPhase3(){
  if(bossPhase3Reached)return;
  bossPhase3Reached=true;bossPhase=3;
  const tier=getBossTier();
  bossTargetSize=getBossPhase3Size(tier,bossRun);animateBossSize();

  document.body.classList.remove('boss-phase2');document.body.classList.add('boss-phase3');
  els.bossPhaseInd.textContent='⚠ PHASE 3 — OVERLOAD ⚠';els.bossPhaseInd.style.color='#ff2200';
  els.bossHpFill.style.background='linear-gradient(90deg,#ff0000,#ff4400,#ff8800)';

  els.gold.style.animation='pulse-gold .4s ease-in-out infinite';
  els.ring.style.animation='spin-ring .5s linear infinite';
  els.ring.style.borderWidth='5px';

  shake('lg');flashScreen('rgba(255,0,0,.65)');
  spawnParticles(bossX,bossY,tier.color,100);spawnParticles(bossX,bossY,'#ffffff',50);
  spawnShockwave(bossX,bossY,tier.glow,cW()*.8,8);
  showMsg('⚠ OVERLOAD','BOSS IS UNSTABLE — FINISH IT NOW!','#ff2200');
  setStatus('⚠ OVERLOAD — STRIKE NOW!','danger');
  toast('💥 PHASE 3 — OVERLOAD!','#ff3300');
  SFX.bossPhase(3);

  // Heavy periodic rumble + flash
  clearInterval(bossRumbleInterval);
  bossRumbleInterval=setInterval(()=>{
    if(!bossAlive)return;
    shake(Math.random()>.5?'md':'sm');
    flashScreen('rgba(255,40,0,.2)',80);
    spawnSparks(bossX,bossY,tier.color,8);
    spawnShockwave(bossX,bossY,tier.glow,200,7);
  },1800);
}

// ── BOSS ATTACK ──
function bossAttack(){
  const tier=getBossTier();
  const attackType=bossPhase===3?Math.floor(Math.random()*3):Math.floor(Math.random()*2);
  if(attackType===0){
    // Shockwave
    const r=bossPhase===3?300:220;
    const sw={x:bossX,y:bossY,r:bossSize/2,maxR:r,speed:bossPhase===3?7:5,color:tier.glow,life:1,fromBoss:true};
    shockwaves.push(sw);
    flashScreen('rgba(255,100,0,.15)',100);
  } else if(attackType===1){
    // Magnet pull — move circles toward boss
    [els.red,els.blue,els.green].forEach(e=>{
      if(e.classList.contains('fading'))return;
      const c=getCenter(e);
      const ang=Math.atan2(bossY-c.y,bossX-c.x);
      const pull=20+bossPhase*8;
      let px=parseFloat(e.style.left),py=parseFloat(e.style.top);
      px+=Math.cos(ang)*pull;py+=Math.sin(ang)*pull;
      px=Math.max(0,Math.min(cW()-R*2,px));py=Math.max(0,Math.min(cH()-R*2,py));
      setPos(e,px,py);
    });
    toast('☠ MAGNET PULL!','#ff8844');
  } else {
    // Orb rain — particle burst from top
    for(let i=0;i<6;i++){
      setTimeout(()=>{
        const rx=Math.random()*cW();
        spawnSparks(rx,0,tier.color,8);
      },i*150);
    }
    toast('☠ ORB RAIN!','#ffaa44');
  }
}

// ── BOSS CLICK (damage) ──
function bossClick(e){
  if(!bossAlive)return;
  e.stopPropagation();
  const tier=getBossTier();
  const dmg=10;
  bossCurrentHp=Math.max(0,bossCurrentHp-dmg);
  const pct=(bossCurrentHp/bossMaxHp)*100;
  els.bossHpFill.style.width=pct+'%';

  // Hit flash
  els.gold.style.filter='brightness(3) saturate(0)';
  setTimeout(()=>els.gold.style.filter='',120);
  SFX.bossHit();

  // Hit sparks at click position
  const ar=area.getBoundingClientRect();
  const hx=e.clientX-ar.left,hy=e.clientY-ar.top;
  spawnSparks(hx,hy,'#ffffff',14);spawnSparks(hx,hy,tier.color,10);
  shake('sm');

  // Phase transitions
  if(bossCurrentHp<=bossMaxHp*.6&&!bossPhase2Reached) bossStartPhase2();
  if(bossCurrentHp<=bossMaxHp*.25&&!bossPhase3Reached) bossStartPhase3();

  // Update label
  const phaseName=['','AWAKENING','ANGRY','OVERLOAD'][bossPhase]||'';
  els.bossPhaseLabel.textContent=`${phaseName} — ${Math.round(pct)}%`;

  if(bossCurrentHp<=0) bossDefeat();
}

// ── RUN BANNER ──
let runBannerTimeout=null;
function showRunBanner(runNum,tierName,tierColor){
  // Remove any existing banner
  const old=document.getElementById('run-banner');if(old)old.remove();
  const b=document.createElement('div');b.id='run-banner';
  b.style.cssText=`position:fixed;top:50%;left:50%;transform:translate(-50%,-50%) scale(0);z-index:70;text-align:center;pointer-events:none;
    background:rgba(8,4,0,.95);border:2px solid ${tierColor};border-radius:10px;padding:20px 40px;
    box-shadow:0 0 50px ${tierColor}55,inset 0 1px 0 rgba(255,255,255,.05);
    transition:transform .4s cubic-bezier(.175,.885,.32,1.5),opacity .4s;opacity:0;`;
  b.innerHTML=`
    <div style="font-family:'Orbitron',monospace;font-size:clamp(.6rem,2vw,.9rem);letter-spacing:.35em;color:${tierColor};text-shadow:0 0 16px ${tierColor};margin-bottom:8px">▶ ROUND ${runNum}</div>
    <div style="font-family:'Orbitron',monospace;font-size:clamp(1rem,4vw,2rem);font-weight:900;letter-spacing:.2em;color:#fff;text-shadow:0 0 24px ${tierColor}">${tierName}</div>
    <div style="font-family:'Rajdhani',sans-serif;font-size:.75rem;letter-spacing:.25em;color:rgba(255,255,255,.5);margin-top:6px">FUSE THE ELEMENTS TO BEGIN</div>`;
  document.body.appendChild(b);
  requestAnimationFrame(()=>{requestAnimationFrame(()=>{b.style.transform='translate(-50%,-50%) scale(1)';b.style.opacity='1';});});
  if(runBannerTimeout)clearTimeout(runBannerTimeout);
  runBannerTimeout=setTimeout(()=>{b.style.opacity='0';b.style.transform='translate(-50%,-50%) scale(.9)';setTimeout(()=>b.remove(),400);},3000);
}

// ── BOSS DEFEAT ──
function bossDefeat(){
  bossAlive=false;
  clearInterval(bossMoveInterval);clearInterval(bossAttackInterval);
  clearInterval(bossRumbleInterval);clearInterval(bossSparkInterval);
  if(bossGrowAnim)clearInterval(bossGrowAnim);

  const tier=getBossTier();
  const isUltimate=!!tier.final;

  shake('lg');
  SFX.bossDefeat();
  for(let i=0;i<6;i++){
    setTimeout(()=>{
      flashScreen(`rgba(255,${140+i*18},${i*25},.7)`,80);
      shake('md');
      spawnParticles(bossX+(-90+Math.random()*180),bossY+(-90+Math.random()*180),tier.color,80);
      spawnParticles(bossX,bossY,'#ffffff',60);
      spawnSparks(bossX,bossY,'#ffcc00',20);
      spawnShockwave(bossX,bossY,tier.glow,cW(),10);
    },i*180);
  }

  setTimeout(()=>{
    hideGold();els.ring.classList.remove('show');
    els.bossHpBar.classList.remove('show');
    document.body.classList.remove('boss-arena','boss-phase2','boss-phase3','ultimate-arena');
    els.header.classList.remove('boss-header');
    document.querySelector('.tab:last-child')?.classList.remove('boss-active');

    playerScore += bossMaxHp * 10 * Math.max(1,bossRun);
    metaTrack('bossesDefeated',1);
    metaUnlockDiscovery('boss_defeat');

    if(isUltimate){
      metaUnlockDiscovery('infinite_signal');
      triggerInfiniteSequence();
      return;
    }

    const allNormalDefeated=bossRun>=BOSS_STANDARD_RUNS;
    const nextTier=allNormalDefeated?getBossTier(BOSS_FINAL_RUN):getBossTier(bossRun+1);
    els.rewardTitle.textContent='BOSS DEFEATED!';
    els.rewardTitle.style.color=tier.color;
    els.rewardDesc.innerHTML=`<span style="color:${tier.color}">${tier.name}</span> has fallen<br><span style="color:#ffddaa">${tier.rewardTitle||`RUN ${bossRun} CLEARED`}</span>`;
    els.rewardScore.textContent=`+ ${bossMaxHp*10*bossRun} PTS  |  TOTAL: ${playerScore.toLocaleString()}`;
    els.rewardSub.textContent = allNormalDefeated
      ? `⚠ ${nextTier.name} AWAKENS — PREPARE YOURSELF...`
      : `NEXT: ${nextTier.name} awaits`;
    els.rewardBanner.classList.add('show');
    setTimeout(()=>els.rewardBanner.classList.remove('show'), allNormalDefeated?4200:2800);

    if(allNormalDefeated){
      metaUnlockDiscovery('ultimate_awakened');
      merged=false;
      popCirclesOut();
      setStatus('⚠ SOMETHING FAR WORSE IS COMING...','danger');
      els.bossVignette.classList.add('show');
      setTimeout(()=>{
        triggerUltimateBoss();
      }, 3800);
    } else {
      merged = false;
      els.bossVignette.classList.remove('show');
      popCirclesOut();

      const nextRun = bossRun + 1;
      setTimeout(()=>{
        showRunBanner(nextRun, nextTier.name, nextTier.color);
        setStatus(`⚔ ROUND ${nextRun} — FUSE THE ELEMENTS!`, 'boss-status');
      }, 600);
    }

  }, 1100);
}

function popCirclesOut(){
  [els.red,els.blue,els.green].forEach((e,i)=>{
    e.classList.remove('fading','knocked');
    ['opacity','transform','pointerEvents','transition'].forEach(p=>e.style[p]='');
    const angle=(i/3)*Math.PI*2+.3;
    setPos(e,cW()/2+Math.cos(angle)*160-R,cH()/2+Math.sin(angle)*160-R);
  });
}

function triggerUltimateBoss(){
  if(advActive) advExit();
  spawnBossRun(BOSS_FINAL_RUN,cW()/2,cH()/2);
}

// ══════════════════════════════════════════
// ████ THE INFINITE CIRCLE — TRUE FINAL BOSS ████
// ══════════════════════════════════════════
let infiniteActive   = false;  // blocks all boss/fusion creation
let infPhase         = 0;      // 1-5
let infSepPower      = 0;      // 0-100, win at 100
let infSepReady      = false;  // grace period before sep can count
let infShieldActive  = false;  // chain shield engaged
let infClonesActive  = false;
let infFakeDeath     = false;  // in fake-death swirl
let infGravPull      = false;
let infiniteSize     = 0;
let infX=0, infY=0;

// interval handles
let inf_grow=null, inf_spark=null, inf_attack=null,
    inf_rumble=null, inf_phase2=null, inf_phase3=null,
    inf_storm=null, inf_sep=null;

// bullet circles for circle storm
let stormBullets = [];   // {x,y,vx,vy,r,color,life}

// energy chains
let infChains = [];   // {x1,y1,x2,y2,life,broken}

const infEl={
  orb:()=>document.getElementById('infinite-orb'),
  hpbar:()=>document.getElementById('infinite-hpbar'),
  phaseInd:()=>document.getElementById('infinite-phase-ind'),
  hint:()=>document.getElementById('inf-hint'),
  sepMeter:()=>document.getElementById('sep-meter'),
  sepFill:()=>document.getElementById('sep-fill'),
  sepVal:()=>document.getElementById('sep-val'),
  reveal:()=>document.getElementById('reveal-overlay'),
  rl1:()=>document.getElementById('reveal-line1'),
  rl2:()=>document.getElementById('reveal-line2'),
  rl3:()=>document.getElementById('reveal-line3'),
};

// ── STEP 1: REVEAL TEXT ──
function triggerInfiniteSequence(){
  if(advActive) advExit();
  els.bossVignette.classList.remove('show');
  document.body.classList.remove('ultimate-arena');
  document.body.classList.add('infinite-arena');

  const rev=infEl.reveal();
  rev.classList.add('show');
  setTimeout(()=>{ infEl.rl1().style.opacity='1'; },500);
  setTimeout(()=>{ infEl.rl2().style.opacity='1'; shake('md'); flashScreen('rgba(120,80,255,.5)'); },2000);
  setTimeout(()=>{ infEl.rl3().style.opacity='1'; },3600);
  setTimeout(()=>{
    rev.classList.remove('show');
    [infEl.rl1(),infEl.rl2(),infEl.rl3()].forEach(l=>l.style.opacity='0');
    setTimeout(()=>infFusionSwirl(),600);
  },5400);
}

// ── STEP 2: FUSION SWIRL (circles spiral in) ──
function infFusionSwirl(){
  // Lock player out during swirl
  merged=true;
  popCirclesOut();   // start them at scatter positions

  const circles=[els.red,els.blue,els.green];
  const orb=infEl.orb();
  const cx=cW()/2, cy=cH()/2;

  // show vignette
  els.bossVignette.classList.add('show');
  showMsg('FUSION UNSTOPPABLE','THE ELEMENTS BETRAY YOU','#cc66ff');
  flashScreen('rgba(100,0,200,.4)');

  // Animate circles spiraling toward center over 3s
  let t=0;
  const startPositions=circles.map(e=>getCenter(e));
  const swirl=setInterval(()=>{
    t+=16;
    const progress=Math.min(1, t/3000);
    const eased=progress<1 ? 1-Math.pow(1-progress,3) : 1;
    const angle=progress*Math.PI*8;  // spin 4 full rotations

    circles.forEach((e,i)=>{
      const sp=startPositions[i];
      const baseAngle=(i/3)*Math.PI*2 + angle;
      const dist=(1-eased)*180 + eased*0;
      const nx= cx + Math.cos(baseAngle)*dist - R;
      const ny= cy + Math.sin(baseAngle)*dist - R;
      setPos(e, nx, ny);
      // burst particles as they converge
      if(Math.random()<.12){
        const colors=['#ff4455','#4488ff','#44ee88'];
        spawnSparks(nx+R,ny+R,colors[i],2);
      }
    });

    if(progress>=1){
      clearInterval(swirl);
      // hide circles
      circles.forEach(e=>{ e.style.opacity='0'; e.style.pointerEvents='none'; });
      // big merge flash
      flashScreen('rgba(200,150,255,.85)');
      shake('lg');
      spawnParticles(cx,cy,'#aa55ff',100);
      spawnParticles(cx,cy,'#ffffff',60);
      spawnShockwave(cx,cy,'rgba(180,120,255,',cW()*.9,10);
      setTimeout(()=>spawnInfiniteCircle(),700);
    }
  },16);
}

// ── STEP 3: SPAWN & PHASE SYSTEM ──
function spawnInfiniteCircle(){
  infiniteActive=true;
  infPhase=1;
  infSepPower=0;
  infShieldActive=false;
  infClonesActive=false;
  infFakeDeath=false;
  infGravPull=false;
  infX=cW()/2; infY=cH()/2;
  infiniteSize=10;
  stormBullets=[];
  infChains=[];

  const orb=infEl.orb();
  Object.assign(orb.style,{
    width:'10px',height:'10px',left:infX+'px',top:infY+'px',
    transition:'opacity .8s,transform .8s cubic-bezier(.175,.885,.32,1.4)',
  });
  orb.classList.add('visible');

  infEl.hpbar().classList.add('show');
  infEl.phaseInd().textContent='PHASE 1 — AWAKENING';
  infEl.sepMeter().classList.add('show');
  infEl.sepFill().style.width='0%';
  infEl.sepVal().textContent='0%';
  infEl.hint().textContent='SEPARATE THE CIRCLES';
  els.sepBarBig.classList.add('show');
  els.sepBarBigFill.style.width='0%';
  els.sepBarBigPct.textContent='0%';

  // pop circles back visible
  merged=false;
  popCirclesOut();
  setStatus('∞ SPREAD THE CIRCLES APART TO WIN','blackhole');
  SFX.infiniteSpawn();

  // Grow loop
  inf_grow=setInterval(()=>{
    if(!infiniteActive)return;
    const cap=infPhase===5? cW()*.65 : infPhase===4? cW()*.55 : infPhase===3? cW()*.45 : cW()*.35;
    if(infiniteSize<cap) infiniteSize=Math.min(infiniteSize+0.35*(1+infPhase*.2), cap);
    orb.style.width=infiniteSize+'px';
    orb.style.height=infiniteSize+'px';
    orb.style.left=infX+'px';
    orb.style.top=infY+'px';
    // Update hint
    if(infShieldActive) infEl.hint().textContent='⛓ CLICK GOLD DOTS TO BREAK CHAINS';
    else if(infGravPull) infEl.hint().textContent='🧲 DRAG CIRCLES AWAY FROM CENTER!';
    else if(infClonesActive) infEl.hint().textContent='👥 IGNORE FAKES — SPREAD CIRCLES!';
    else if(infSepPower>80) infEl.hint().textContent='⚡ HOLD THEM APART — ALMOST DONE!';
    else if(infSepPower>40) infEl.hint().textContent='↔ DRAG EACH CIRCLE TO A DIFFERENT CORNER';
    else infEl.hint().textContent='↔ DRAG ALL 3 CIRCLES AS FAR APART AS POSSIBLE';
  },100);

  // Sparks
  inf_spark=setInterval(()=>{
    if(!infiniteActive)return;
    const colors=['#8855ff','#ffffff','#cc88ff','#4444ff'];
    spawnSparks(infX,infY,colors[Math.floor(Math.random()*colors.length)],3+infPhase);
    if(infPhase>=3) spawnSparks(
      infX+(-infiniteSize*.4+Math.random()*infiniteSize*.8),
      infY+(-infiniteSize*.4+Math.random()*infiniteSize*.8),
      '#cc66ff', 2
    );
  },400);

  // Main attack ticker - starts slow, phases speed it up
  inf_attack=setInterval(()=>{
    if(!infiniteActive||infFakeDeath)return;
    infDoAttack();
  },4000);

  // Rumble
  inf_rumble=setInterval(()=>{
    if(!infiniteActive)return;
    shake(infPhase>=4?'md':'sm');
    flashScreen('rgba(80,40,180,.15)',80);
    spawnShockwave(infX,infY,'rgba(120,60,255,', 80+infiniteSize*.5, 3+infPhase);
  },3500);

  // Separation checker — delayed start so initial scatter positions don't count
  infSepPower=0;
  infSepReady=false;
  setTimeout(()=>{
    infSepReady=true;
    inf_sep=setInterval(()=>{ if(infiniteActive) checkInfiniteSeparation(); },80);
  },3000);

  // Phase escalation timer
  infSchedulePhaseUps();
}

function infSchedulePhaseUps(){
  setTimeout(()=>{ if(infiniteActive&&infPhase===1) infSetPhase(2); },8000);
  setTimeout(()=>{ if(infiniteActive&&infPhase===2) infSetPhase(3); },18000);
  setTimeout(()=>{ if(infiniteActive&&infPhase===3) infSetPhase(4); },30000);
  setTimeout(()=>{ if(infiniteActive&&infPhase===4) infSetPhase(5); },45000);
}

function infSetPhase(p){
  if(infPhase>=p||!infiniteActive)return;
  infPhase=p;
  const names=['','AWAKENING','CLONE ILLUSION','GRAVITY STORM','CHAOS SURGE','FINAL FORM'];
  const colors=['','#aa88ff','#ff88cc','#ff4400','#ff0000','#ffffff'];
  infEl.phaseInd().textContent=`PHASE ${p} — ${names[p]}`;
  infEl.phaseInd().style.color=colors[p];
  showMsg(`∞ PHASE ${p}`,names[p],'#cc88ff');
  shake('lg'); flashScreen('rgba(140,60,255,.6)');
  spawnParticles(infX,infY,'#cc66ff',80);
  spawnShockwave(infX,infY,'rgba(180,100,255,',cW(),10);
  toast(`⚡ PHASE ${p} — ${names[p]}`,'#cc88ff');
  SFX.infinitePhase();

  // Speed up attacks per phase
  clearInterval(inf_attack);
  const attackDelay=[0,4000,3200,2500,1800,1200][p]||1200;
  inf_attack=setInterval(()=>{ if(infiniteActive&&!infFakeDeath) infDoAttack(); },attackDelay);

  // Per-phase specials
  if(p===2) setTimeout(()=>infSpawnClones(),2000);
  if(p===3) setInterval(()=>{ if(infiniteActive&&infPhase>=3) infGravitySurge(); },8000);
  if(p===4){
    setTimeout(()=>infCircleStorm(),3000);
  }
  if(p===5){
    // repeated fake deaths
    setTimeout(()=>infFakeDeathTrap(),4000);
    setTimeout(()=>infFakeDeathTrap(),20000);
  }
}

// ── ATTACK DISPATCHER ──
function infDoAttack(){
  const attacks=[infShockwaveAttack, infMagnetPull, infAntiSepShield];
  if(infPhase>=3) attacks.push(infAnnihilationLaser);
  if(infPhase>=4) attacks.push(infCircleStorm);
  const fn=attacks[Math.floor(Math.random()*attacks.length)];
  fn();
}

// ── ATTACK: ANNIHILATION LASER ──
let infLaserActive=false;
function infAnnihilationLaser(){
  if(!infiniteActive||infLaserActive||infFakeDeath)return;
  infLaserActive=true;

  // ── Phase 1: Charge (2s) ──
  toast('⚠ INFINITE ENERGY SURGE DETECTED','#ffffff');
  setStatus('⚠ INFINITE ENERGY SURGE — INCOMING LASER!','danger');
  shake('sm');

  // Darken screen during charge
  const darkEl=document.createElement('div');
  darkEl.id='inf-laser-dark';
  darkEl.style.cssText='position:fixed;inset:0;z-index:45;pointer-events:none;background:rgba(0,0,0,0);transition:background 1.8s ease;';
  document.body.appendChild(darkEl);
  requestAnimationFrame(()=>{ darkEl.style.background='rgba(0,0,0,.55)'; });

  // Orb brightens during charge — pulsing white glow
  const orb=infEl.orb();
  const origBoxShadow=orb.style.boxShadow;
  orb.style.transition='box-shadow .3s,filter .3s';
  let chargeT=0;
  const chargeGlow=setInterval(()=>{
    if(!infiniteActive){clearInterval(chargeGlow);return;}
    chargeT+=0.18;
    const intensity=0.5+chargeT*.08;
    orb.style.filter=`brightness(${Math.min(3.5,1+chargeT*.15)}) saturate(0.3)`;
    orb.style.boxShadow=`0 0 ${100+chargeT*30}px ${40+chargeT*15}px rgba(255,255,255,${Math.min(.95,intensity)}),0 0 ${200+chargeT*60}px ${80+chargeT*25}px rgba(200,160,255,${Math.min(.6,intensity*.5)})`;
    if(Math.random()<.4+chargeT*.04){
      spawnSparks(infX+(-100+Math.random()*200),infY+(-100+Math.random()*200),'#ffffff',3);
      spawnSparks(infX+(-60+Math.random()*120),infY+(-60+Math.random()*120),'#cc88ff',2);
    }
  },60);

  // ── Phase 2: FIRE (after 2.2s) ──
  setTimeout(()=>{
    clearInterval(chargeGlow);
    if(!infiniteActive){ infLaserActive=false; darkEl.remove(); return; }

    // Restore orb appearance
    orb.style.filter='';
    orb.style.boxShadow=origBoxShadow;

    // Pick a random angle for the laser
    const angle=Math.random()*Math.PI; // 0-180° — always horizontal-ish
    _fireAnnihilationLaser(angle);
  },2200);
}

function _fireAnnihilationLaser(angle){
  if(!infiniteActive){ infLaserActive=false; document.getElementById('inf-laser-dark')?.remove(); return; }

  shake('lg');setTimeout(()=>shake('lg'),120);setTimeout(()=>shake('md'),350);
  flashScreen('rgba(255,255,255,.85)',60);
  SFX.infinitePhase();

  // Build the beam parameters
  const beamW=70+infPhase*15;   // very wide
  const cx=infX,cy=infY;
  const cos=Math.cos(angle),sin=Math.sin(angle);
  const reach=Math.max(cW(),cH())*1.5; // extends past screen edges

  // How long beam lasts
  const BEAM_MS=1400;
  const startT=Date.now();
  const ctx=els.swCanvas.getContext('2d');

  showMsg('∞ ANNIHILATION LASER','INFINITE ENERGY DISCHARGE','#ffffff');

  // Draw beam on shockwave canvas each frame
  const beamLoop=setInterval(()=>{
    if(!infiniteActive){ clearInterval(beamLoop); infLaserActive=false; return; }
    const elapsed=Date.now()-startT;
    const prog=elapsed/BEAM_MS;
    if(prog>=1){
      clearInterval(beamLoop);
      _laserAftermath(cx,cy,angle,reach);
      return;
    }

    // Fade out toward end
    const alpha=prog<0.7?1:1-(prog-0.7)/0.3;

    // Draw beam — bi-directional from orb center
    ctx.save();
    ctx.translate(cx,cy);ctx.rotate(angle);

    // Core beam (white hot center)
    ctx.beginPath();ctx.moveTo(-reach,0);ctx.lineTo(reach,0);
    ctx.strokeStyle=`rgba(255,255,255,${alpha*.95})`;
    ctx.lineWidth=beamW*.35;
    ctx.shadowColor='rgba(255,255,255,1)';ctx.shadowBlur=40;
    ctx.stroke();

    // Mid glow (purple energy)
    ctx.beginPath();ctx.moveTo(-reach,0);ctx.lineTo(reach,0);
    ctx.strokeStyle=`rgba(200,140,255,${alpha*.8})`;
    ctx.lineWidth=beamW*.7;ctx.shadowBlur=60;
    ctx.stroke();

    // Outer bloom
    ctx.beginPath();ctx.moveTo(-reach,0);ctx.lineTo(reach,0);
    ctx.strokeStyle=`rgba(120,60,255,${alpha*.4})`;
    ctx.lineWidth=beamW*1.4;ctx.shadowBlur=80;
    ctx.stroke();

    ctx.restore();

    // Crackling particles along beam
    if(Math.random()<.6){
      const t=(-1+Math.random()*2)*reach;
      const px=cx+cos*t, py=cy+sin*t;
      const perpX=-sin,perpY=cos;
      const off=(-beamW*.4+Math.random()*beamW*.8);
      spawnSparks(px+perpX*off,py+perpY*off,'#ffffff',2);
      if(Math.random()<.4) spawnSparks(px+perpX*off*1.5,py+perpY*off*1.5,'#cc88ff',1);
    }

    // Push player circles away from beam if they're inside it
    [els.red,els.blue,els.green].forEach(e=>{
      if(e.classList.contains('fading'))return;
      const c=getCenter(e);
      // Distance from circle center to beam line
      const dx=c.x-cx,dy=c.y-cy;
      const along=dx*cos+dy*sin;     // projection along beam
      const perp=Math.abs(-dx*sin+dy*cos); // distance from beam axis
      if(perp<beamW*.6+R){           // inside beam width
        const pushDir=(-dx*sin+dy*cos)<0?-1:1;
        const pushAmt=4+alpha*6;
        let px=parseFloat(e.style.left)+(- sin*pushDir*pushAmt);
        let py=parseFloat(e.style.top)+(  cos*pushDir*pushAmt);
        px=Math.max(0,Math.min(cW()-R*2,px));
        py=Math.max(0,Math.min(cH()-R*2,py));
        setPos(e,px,py);
        if(infSepPower>0) infSepPower=Math.max(0,infSepPower-1.5);
        infUpdateBar();
      }
    });
  },16);
}

function _laserAftermath(cx,cy,angle,reach){
  infLaserActive=false;
  // Remove darkness
  const darkEl=document.getElementById('inf-laser-dark');
  if(darkEl){ darkEl.style.background='rgba(0,0,0,0)'; setTimeout(()=>darkEl.remove(),800); }

  // Residual glow particles along beam path
  const cos=Math.cos(angle),sin=Math.sin(angle);
  for(let i=0;i<20;i++){
    setTimeout(()=>{
      const t=(-1+Math.random()*2)*reach;
      spawnParticles(cx+cos*t,cy+sin*t,'#cc88ff',8,3);
      spawnSparks(cx+cos*t,cy+sin*t,'#ffffff',3);
    },i*60);
  }

  setStatus('∞ SPREAD THE CIRCLES APART TO WIN','blackhole');
  shake('sm');
}

// ── ATTACK: SHOCKWAVE ──
function infShockwaveAttack(){
  const count=infPhase>=4?3:1;
  for(let i=0;i<count;i++){
    setTimeout(()=>{
      spawnShockwave(infX,infY,'rgba(150,80,255,',220+infiniteSize*.6,5+infPhase,true);
      flashScreen('rgba(100,50,200,.15)',80);
    },i*600);
  }
}

// ── ATTACK: MAGNET PULL ──
function infMagnetPull(){
  if(infGravPull)return;
  infGravPull=true;
  toast('🧲 GRAVITY SURGE — FIGHT IT!','#ff88aa');
  setStatus('🧲 GRAVITY SURGE — DRAG CIRCLES TO CORNERS!','danger');
  shake('md');
  spawnShockwave(infX,infY,'rgba(180,80,255,',cW()*.7,8);

  const pullInterval=setInterval(()=>{
    if(!infiniteActive||!infGravPull){clearInterval(pullInterval);return;}
    [els.red,els.blue,els.green].forEach(e=>{
      if(e===dragging)return; // never pull the one being actively dragged
      const c=getCenter(e);
      const ang=Math.atan2(infY-c.y,infX-c.x);
      const dist=Math.hypot(c.x-infX,c.y-infY);
      // Weak pull — player can easily overcome by dragging
      const pull=Math.max(0.5, 4-(dist*.008));
      let px=parseFloat(e.style.left)+Math.cos(ang)*pull;
      let py=parseFloat(e.style.top)+Math.sin(ang)*pull;
      px=Math.max(0,Math.min(cW()-R*2,px));
      py=Math.max(0,Math.min(cH()-R*2,py));
      setPos(e,px,py);
    });
  },120);

  // Lasts 4 seconds
  setTimeout(()=>{
    infGravPull=false;
    clearInterval(pullInterval);
    setStatus('∞ SPREAD THE CIRCLES APART TO WIN','blackhole');
    toast('✓ GRAVITY ENDED — KEEP SPREADING!','#88aaff');
  },4000);
}

// ── ATTACK: ANTI-SEP SHIELD (energy chains) ──
function infAntiSepShield(){
  if(infShieldActive)return;
  infShieldActive=true;
  toast('⛓ ENERGY CHAINS — CLICK TO BREAK!','#ffcc44');
  setStatus('⛓ CLICK THE GLOWING CHAINS TO BREAK THEM!','danger');

  // draw chains on shockwave canvas via infChains array
  infChains=[];
  const cs=[els.red,els.blue,els.green];
  for(let i=0;i<cs.length;i++){
    for(let j=i+1;j<cs.length;j++){
      const ca=getCenter(cs[i]), cb=getCenter(cs[j]);
      const mx=(ca.x+cb.x)/2, my=(ca.y+cb.y)/2;
      infChains.push({x1:ca.x,y1:ca.y,x2:cb.x,y2:cb.y,
        mx,my,broken:false,life:1,id:`${i}-${j}`});
    }
  }

  // Gentle pull toward each other while shield is up
  const chainPull=setInterval(()=>{
    if(!infiniteActive||!infShieldActive){clearInterval(chainPull);return;}
    for(let i=0;i<cs.length;i++){
      for(let j=i+1;j<cs.length;j++){
        const ca=getCenter(cs[i]),cb=getCenter(cs[j]);
        const ang=Math.atan2(cb.y-ca.y,cb.x-ca.x);
        const pull=1.5; // very gentle
        for(const[e,a] of [[cs[i],ang],[cs[j],-ang]]){
          if(e===dragging)continue;
          let px=parseFloat(e.style.left)+Math.cos(a)*pull;
          let py=parseFloat(e.style.top)+Math.sin(a)*pull;
          px=Math.max(0,Math.min(cW()-R*2,px));
          py=Math.max(0,Math.min(cH()-R*2,py));
          setPos(e,px,py);
        }
      }
    }
    // refresh chain positions
    infChains.forEach((ch,idx)=>{
      if(ch.broken)return;
      const ca=getCenter(cs[parseInt(ch.id[0])]);
      const cb=getCenter(cs[parseInt(ch.id[2])]);
      ch.x1=ca.x;ch.y1=ca.y;ch.x2=cb.x;ch.y2=cb.y;
      ch.mx=(ca.x+cb.x)/2;ch.my=(ca.y+cb.y)/2;
    });
  },50);

  // Auto-break after 12s anyway
  setTimeout(()=>{
    if(infShieldActive) infBreakAllChains();
  },12000);
}

function infBreakAllChains(){
  infShieldActive=false;
  infChains.forEach(ch=>{
    if(!ch.broken){
      spawnSparks(ch.mx,ch.my,'#ffcc44',10);
      ch.broken=true;
    }
  });
  infChains=[];
  setStatus('∞ SPREAD THE CIRCLES APART TO WIN','blackhole');
  toast('✓ CHAINS BROKEN','#88ffaa');
}

// Handle clicks on chains
if(area){
  area.addEventListener('click',e=>{
    if(!infShieldActive||!infChains.length)return;
    const ar=area.getBoundingClientRect();
    const mx=e.clientX-ar.left, my=e.clientY-ar.top;
    let anyBroken=false;
    infChains.forEach(ch=>{
      if(ch.broken)return;
      // distance from click to chain midpoint
      const d=Math.hypot(mx-ch.mx,my-ch.my);
      if(d<40){
        ch.broken=true; anyBroken=true;
        spawnSparks(ch.mx,ch.my,'#ffdd44',16);
        spawnParticles(ch.mx,ch.my,'#ffaa00',12);
        flashScreen('rgba(255,200,50,.3)',60);
      }
    });
    if(anyBroken && infChains.every(c=>c.broken)){
      infBreakAllChains();
    }
  });
}

// ── GRAVITY SURGE (Phase 3 special) ──
function infGravitySurge(){
  if(!infiniteActive||infGravPull)return;
  toast('🌀 GRAVITY SURGE','#ff8844');
  infMagnetPull();
}

// ── CIRCLE STORM ──
function infCircleStorm(){
  if(!infiniteActive)return;
  toast('🌌 CIRCLE STORM — DODGE!','#ff4466');
  setStatus('🌌 CIRCLE STORM — KEEP SPREADING!','danger');
  shake('lg');
  const colors=['#ff4455','#4488ff','#44ee88','#ff88ff','#ffcc00'];
  for(let i=0;i<24;i++){
    setTimeout(()=>{
      if(!infiniteActive)return;
      const ang=Math.random()*Math.PI*2;
      const spd=3+Math.random()*4;
      stormBullets.push({
        x:infX,y:infY,
        vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd,
        r:8+Math.random()*12,
        color:colors[Math.floor(Math.random()*colors.length)],
        life:1
      });
    },i*100);
  }
  setTimeout(()=>{ if(infiniteActive) setStatus('∞ SPREAD THE CIRCLES APART TO WIN','blackhole'); },6000);
}

// ── FAKE DEATH TRAP ──
function infFakeDeathTrap(){
  if(!infiniteActive||infFakeDeath)return;
  infFakeDeath=true;
  setStatus('∞ THE CIRCLE IS DYING?!','blackhole');
  toast('⚠ SOMETHING IS WRONG...','#ffcc44');

  const orb=infEl.orb();
  // fade and shrink
  orb.style.transition='width 2s ease,height 2s ease,opacity 2s ease';
  orb.style.opacity='.2';
  orb.style.width='30px';
  orb.style.height='30px';
  shake('sm');

  setTimeout(()=>{
    if(!infiniteActive)return;
    // FAKE! IT COMES BACK STRONGER
    flashScreen('rgba(255,0,0,.75)');
    shake('lg');
    orb.style.transition='width .6s ease,height .6s ease,opacity .4s ease';
    orb.style.opacity='1';
    const newSize=Math.min(infiniteSize*1.15, cW()*.65);
    infiniteSize=newSize;
    orb.style.width=newSize+'px';
    orb.style.height=newSize+'px';
    spawnParticles(infX,infY,'#cc44ff',120);
    spawnShockwave(infX,infY,'rgba(200,80,255,',cW(),14);
    showMsg('IT WAS A TRAP!','THE CIRCLE GROWS STRONGER','#ff4444');
    toast('💀 FAKE DEATH — IT RETURNS STRONGER!','#ff3300');
    infFakeDeath=false;
    setStatus('∞ STILL ALIVE — KEEP SEPARATING!','danger');
  },2800);
}

// ── CLONE ILLUSION ──
function infSpawnClones(){
  if(!infiniteActive||infClonesActive)return;
  infClonesActive=true;
  toast('👥 CLONE ILLUSION — FIND THE REAL ONE!','#cc88ff');
  setStatus('👥 CLICK THE REAL BOSS — FAKES FLICKER','danger');

  const cloneCount=4;
  const clones=[];
  const area2=document.getElementById('canvas-area');

  // create fake divs
  for(let i=0;i<cloneCount;i++){
    const c=document.createElement('div');
    c.className='inf-clone';
    const ang=(i/cloneCount)*Math.PI*2;
    const dist=120+Math.random()*60;
    const cx2=infX+Math.cos(ang)*dist;
    const cy2=infY+Math.sin(ang)*dist;
    const sz=infiniteSize*.5+20;
    c.style.cssText=`position:absolute;border-radius:50%;z-index:9;pointer-events:all;cursor:pointer;
      width:${sz}px;height:${sz}px;left:${cx2}px;top:${cy2}px;transform:translate(-50%,-50%);
      background:radial-gradient(circle at 38% 35%,#aaaaff,#5500ff 50%,#000);
      box-shadow:0 0 30px 10px rgba(100,60,200,.5);
      animation:flicker-clone .4s ease-in-out infinite alternate;opacity:.6;`;
    c.onclick=()=>{
      // fake! explode it
      const cr=c.getBoundingClientRect(),ar2=area2.getBoundingClientRect();
      spawnParticles(cr.left-ar2.left+cr.width/2,cr.top-ar2.top+cr.height/2,'#8855ff',35);
      spawnSparks(cr.left-ar2.left+cr.width/2,cr.top-ar2.top+cr.height/2,'#ffffff',12);
      flashScreen('rgba(100,60,200,.35)',60);
      toast('FAKE! Keep looking...','#aa88ff');
      c.remove();
      clones.splice(clones.indexOf(c),1);
    };
    area2.appendChild(c);
    clones.push(c);
  }

  // After 8s remove clones and end illusion
  setTimeout(()=>{
    clones.forEach(c=>c.remove());
    infClonesActive=false;
    infEl.orb().style.opacity='1';
    setStatus('∞ SPREAD THE CIRCLES APART TO WIN','blackhole');
    toast('CLONES GONE — BOSS RETURNS!','#cc88ff');
  },8000);
}

// ── SEPARATION CHECKER ──
function checkInfiniteSeparation(){
  if(!infiniteActive||infFakeDeath||!infSepReady)return;
  const circles=[els.red,els.blue,els.green];
  // All three must be visible
  const visible=circles.filter(e=>!e.classList.contains('fading')&&parseFloat(e.style.opacity||1)>0.1);
  if(visible.length<3){infSepPower=Math.max(0,infSepPower-0.3);infUpdateBar();return;}

  // Measure spread: average distance between each pair of circles
  const centers=circles.map(e=>getCenter(e));
  const d01=Math.hypot(centers[0].x-centers[1].x,centers[0].y-centers[1].y);
  const d12=Math.hypot(centers[1].x-centers[2].x,centers[1].y-centers[2].y);
  const d02=Math.hypot(centers[0].x-centers[2].x,centers[0].y-centers[2].y);
  const avgDist=(d01+d12+d02)/3;

  // Win when circles are spread very far apart — must drag them to opposite corners
  const winDist=Math.min(cW(),cH())*.58;
  let raw=Math.min(100,(avgDist/winDist)*100);

  // Shield slightly resists (but doesn't wipe progress)
  if(infShieldActive) raw=Math.max(0,raw-0.5);

  // Separation power builds up gradually — it's sticky (doesn't reset instantly)
  if(raw>infSepPower) infSepPower=Math.min(100,infSepPower+Math.min(2,raw-infSepPower));
  else infSepPower=Math.max(0,infSepPower-0.8);

  infUpdateBar();
  if(infSepPower>=100) infiniteDefeated();
}

function infUpdateBar(){
  const pct=Math.round(infSepPower);
  SFX.sepPulse(pct);
  // small bar (existing)
  infEl.sepFill().style.width=pct+'%';
  infEl.sepVal().textContent=pct+'%';
  // big bottom bar
  els.sepBarBigFill.style.width=pct+'%';
  els.sepBarBigPct.textContent=pct+'%';
  els.sepBarBigFill.classList.toggle('winning',pct>75);
  // Hint text in big bar
  if(infShieldActive) els.sepBarBigHint.textContent='⛓ BREAK THE CHAINS FIRST — CLICK THE GOLD DOTS';
  else if(infGravPull) els.sepBarBigHint.textContent='🧲 FIGHT THE PULL — DRAG CIRCLES TO OPPOSITE CORNERS';
  else if(pct>80) els.sepBarBigHint.textContent='⚡ HOLD THEM APART — ALMOST THERE!';
  else if(pct>40) els.sepBarBigHint.textContent='↔ EACH CIRCLE TO A DIFFERENT CORNER OF THE SCREEN';
  else els.sepBarBigHint.textContent='↔ DRAG ALL 3 CIRCLES AS FAR APART AS POSSIBLE';
  // color shift
  const hue=280-pct*1.5;
  infEl.sepFill().style.background=`linear-gradient(90deg,hsl(${hue},80%,35%),hsl(${hue+40},90%,60%),#fff)`;
}

// ── DEFEAT ──
function infiniteDefeated(){
  if(!infiniteActive)return;
  infiniteActive=false;
  clearInterval(inf_grow);clearInterval(inf_spark);clearInterval(inf_attack);
  clearInterval(inf_rumble);clearInterval(inf_sep);
  document.querySelectorAll('.inf-clone').forEach(c=>c.remove());

  const orb=infEl.orb();

  // Phase 1: cracking apart
  shake('lg');
  for(let i=0;i<10;i++){
    setTimeout(()=>{
      flashScreen(`rgba(${180+i*7},${100+i*5},255,.7)`,70);
      if(i%2===0) shake('md');
      spawnParticles(infX+(-150+Math.random()*300),infY+(-150+Math.random()*300),'#8855ff',60);
      spawnParticles(infX,infY,'#ffffff',50);
      spawnSparks(infX,infY,'#cc99ff',15);
      spawnShockwave(infX,infY,'rgba(180,120,255,',cW()*1.3,14);
    },i*200);
  }

  // Phase 2: orb cracks and shrinks, tiny core rises
  setTimeout(()=>{
    orb.style.transition='opacity 1.2s ease,width 1.5s ease,height 1.5s ease';
    orb.style.opacity='0';
    orb.style.width='0';
    orb.style.height='0';

    // tiny core floats up
    const core=document.createElement('div');
    core.id='inf-core';
    core.style.cssText=`position:absolute;border-radius:50%;width:18px;height:18px;
      left:${infX}px;top:${infY}px;transform:translate(-50%,-50%);z-index:15;pointer-events:none;
      background:radial-gradient(circle,#ffffff,#cc88ff);
      box-shadow:0 0 20px 8px rgba(200,160,255,.9);
      transition:top 3s ease,opacity 3s ease;`;
    area.appendChild(core);
    setTimeout(()=>{ core.style.top='-60px'; core.style.opacity='0'; },100);
    setTimeout(()=>core.remove(),3200);
  },700);

  // Phase 3: victory
  setTimeout(()=>{
    orb.classList.remove('visible');
    infEl.hpbar().classList.remove('show');
    infEl.sepMeter().classList.remove('show');
    document.body.classList.remove('infinite-arena');
    els.bossVignette.classList.remove('show');
    els.bossTier.classList.remove('show');

    playerScore+=15000;
    SFX.infiniteDefeat();

    // Big victory moment
    flashScreen('rgba(200,160,255,.6)');
    shake('lg');
    spawnParticles(cW()/2,cH()/2,'#cc99ff',200);
    spawnParticles(cW()/2,cH()/2,'#ffffff',120);
    spawnShockwave(cW()/2,cH()/2,'rgba(200,150,255,',cW()*1.5,16);

    // final text
    const rev=infEl.reveal();
    infEl.rl1().textContent='YOU BROKE THE CIRCLE.';
    infEl.rl2().textContent='UNIVERSE SAVED';
    infEl.rl3().textContent='No force can contain you.';
    infEl.rl1().style.color='#cc99ff';
    infEl.rl2().style.color='#ffffff';
    rev.style.background='rgba(0,0,0,.6)';
    rev.classList.add('show');
    setTimeout(()=>infEl.rl1().style.opacity='1',400);
    setTimeout(()=>{ infEl.rl2().style.opacity='1'; shake('md'); },1600);
    setTimeout(()=>infEl.rl3().style.opacity='1',2800);
    setTimeout(()=>{
      rev.classList.remove('show');
      [infEl.rl1(),infEl.rl2(),infEl.rl3()].forEach(l=>{ l.style.opacity='0'; });
      infEl.rl1().textContent='You thought that was the end?';
      infEl.rl2().textContent='THE INFINITE CIRCLE';
      infEl.rl3().textContent='Separate the elements to break infinity';
      infEl.rl1().style.color='#8866ff';
      infEl.rl2().style.color='#fff';
      rev.style.background='rgba(0,0,0,.9)';
    },5000);

    els.rewardTitle.textContent='∞ INFINITY SHATTERED';
    els.rewardTitle.style.color='#cc99ff';
    els.rewardDesc.innerHTML='You separated the elements<br>and broke the fabric of forever.<br><span style="color:#ffe066;font-size:.9rem">🏆 TRUE LEGEND — CIRCLE BREAKER</span>';
    els.rewardScore.textContent=`TOTAL: ${playerScore.toLocaleString()} POINTS`;
    els.rewardSub.textContent='No force in the universe can stop you.';
    els.rewardBanner.style.borderColor='#cc99ff';
    els.rewardBanner.classList.add('show');

    setStatus('∞ INFINITY BROKEN — YOU ARE LEGEND','merged');
    els.status.style.color='#cc99ff';
    els.status.style.borderColor='rgba(180,120,255,.5)';
    els.status.style.boxShadow='0 0 24px rgba(140,80,255,.4)';
    els.restartBtn.classList.add('show');
    merged=false;
    popCirclesOut();
  },2200);
}

// ── SHOCKWAVE: add fromInfinite flag support ──
// (updateShockwaves already handles fromBoss; we reuse it)

// ── DRAW CHAINS on shockwave canvas (overlay) ──
// We'll hook into updateShockwaves by drawing chains in a separate pass
function drawInfChains(){
  if(!infChains.length)return;
  const ctx=els.swCanvas.getContext('2d');
  const t=Date.now();
  infChains.forEach(ch=>{
    if(ch.broken)return;
    // animated gold chain
    const pulse=.5+.5*Math.sin(t*.008);
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(ch.x1,ch.y1);
    ctx.lineTo(ch.x2,ch.y2);
    ctx.strokeStyle=`rgba(255,200,50,${.6+pulse*.4})`;
    ctx.lineWidth=3+pulse*2;
    ctx.shadowColor='rgba(255,180,0,.8)';
    ctx.shadowBlur=12+pulse*8;
    ctx.setLineDash([12,8]);
    ctx.stroke();
    // clickable midpoint dot
    ctx.beginPath();
    ctx.arc(ch.mx,ch.my,10+pulse*4,0,Math.PI*2);
    ctx.fillStyle=`rgba(255,220,80,${.7+pulse*.3})`;
    ctx.shadowBlur=20;
    ctx.fill();
    ctx.restore();
  });
}

// ── DRAW STORM BULLETS ──
function updateStormBullets(){
  if(!stormBullets.length)return;
  const ctx=els.pCanvas.getContext('2d');
  stormBullets=stormBullets.filter(b=>{
    b.x+=b.vx; b.y+=b.vy;
    // bounce off walls
    if(b.x<b.r||b.x>cW()-b.r) b.vx*=-1;
    if(b.y<b.r||b.y>cH()-b.r) b.vy*=-1;
    b.life-=.003;
    if(b.life<=0)return false;
    ctx.save();
    ctx.globalAlpha=b.life*.8;
    ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);
    ctx.fillStyle=b.color;
    ctx.shadowColor=b.color;ctx.shadowBlur=10;
    ctx.fill();ctx.restore();
    return true;
  });
}

function stopInfinite(){
  infiniteActive=false;infSepReady=false;
  clearInterval(inf_grow);clearInterval(inf_spark);clearInterval(inf_attack);
  clearInterval(inf_rumble);clearInterval(inf_sep);
  infChains=[];infShieldActive=false;infClonesActive=false;infGravPull=false;infFakeDeath=false;
  infLaserActive=false;
  document.getElementById('inf-laser-dark')?.remove();
  stormBullets=[];
  document.querySelectorAll('.inf-clone,.inf-core').forEach(c=>c.remove());
  const orb=infEl.orb();
  orb.classList.remove('visible');
  orb.style.opacity='';orb.style.width='10px';orb.style.height='10px';
  infEl.hpbar().classList.remove('show');
  infEl.sepMeter().classList.remove('show');
  els.sepBarBig.classList.remove('show');
  document.body.classList.remove('infinite-arena');
  const rev=infEl.reveal();if(rev)rev.classList.remove('show');
  [infEl.rl1(),infEl.rl2(),infEl.rl3()].forEach(l=>{ l.style.opacity='0'; });
  infEl.rl1().textContent='You thought that was the end?';
  infEl.rl2().textContent='THE INFINITE CIRCLE';
  infEl.rl3().textContent='Separate the elements to break infinity';
  infEl.rl1().style.color='#8866ff';
  infEl.rl2().style.color='#fff';
  if(infEl.reveal())infEl.reveal().style.background='rgba(0,0,0,.9)';
}

