// SPLIT (non-boss)
// ══════════════════════════════════════════
function splitApart(){
  if(mode==='boss')return;
  SFX.split();
  cancelFusionCharge();
  if(orbPersonalityTimer){clearInterval(orbPersonalityTimer);orbPersonalityTimer=null;}
  const cx=parseFloat(els.gold.style.left)||cW()/2;
  const cy=parseFloat(els.gold.style.top)||cH()/2;
  const specialFusionId=els.gold.dataset.specialFusion||'';
  if(specialFusionId) playSpecialFusionSplitEffect(cx,cy,specialFusionId);
  else playGoldSplitEffect(cx,cy,SKINS.getEquippedGoldSkinId(),els.gold.dataset.perfect==='1');
  hideGold();els.restartBtn.classList.remove('show');merged=false;
  els.status.className='';
  [els.red,els.blue,els.green].forEach((e,i)=>{
    e.classList.remove('fading','magnetic');
    ['opacity','transform','pointerEvents','transition','marginTop'].forEach(p=>e.style[p]='');
    const cx=cW()/2,cy=cH()/2,angle=(i/3)*Math.PI*2+.3;
    setPos(e,cx+Math.cos(angle)*140-R,cy+Math.sin(angle)*140-R);
  });
  setStatus(modeHint());
  if(mode==='gravity')startGravity();
  if(mode==='scifi'){els.energyFill.style.width='0%';els.energyVal.textContent='0%';}
}

// ══════════════════════════════════════════
// GRAVITY
// ══════════════════════════════════════════
function startGravity(){
  // If gravity is already running, don't stack another loop
  if(gravityActive) return;
  gravityActive=true;
  gravVels=[{x:0,y:0},{x:0,y:0},{x:0,y:0}];
  const GRAVITY=0.38;
  const BOUNCE_FLOOR=0.72;   // energy kept on floor bounce
  const BOUNCE_WALL=0.78;    // energy kept on wall bounce
  const FRICTION=0.994;      // air friction per frame
  const MIN_BOUNCE_SPD=1.2;  // below this, don't play sound or spark

  let lastBounceSound=0;

  (function loop(){
    if(!gravityActive)return;
    if(isGameplayPaused()){
      requestAnimationFrame(loop);
      return;
    }
    const circles=[els.red,els.blue,els.green];
    circles.forEach((e,i)=>{
      if(e.classList.contains('fading')||dragging===e){
        // While dragged, zero out velocity so it doesn't fly on release w/ old vel
        return;
      }
      const v=gravVels[i];
      v.y+=GRAVITY;
      v.x*=FRICTION;
      let p=getPos(e);
      p.x+=v.x;p.y+=v.y;

      // Floor bounce
      if(p.y+R*2>=cH()){
        p.y=cH()-R*2;
        const spd=Math.abs(v.y);
        v.y=-spd*BOUNCE_FLOOR;
        v.x*=0.88; // floor friction on x
        if(spd>MIN_BOUNCE_SPD){
          gravBounceEffect(p.x+R,cH(),'floor',spd,i);
          lastBounceSound=gravBounceSound(spd,lastBounceSound);
        }
        // Kill tiny bounces to settle
        if(Math.abs(v.y)<0.5) v.y=0;
      }
      // Ceiling bounce
      if(p.y<=0){
        p.y=0;
        const spd=Math.abs(v.y);
        v.y=spd*0.5;
        if(spd>MIN_BOUNCE_SPD) lastBounceSound=gravBounceSound(spd*0.5,lastBounceSound);
      }
      // Left wall
      if(p.x<=0){
        p.x=0;
        const spd=Math.abs(v.x);
        v.x=spd*BOUNCE_WALL;
        if(spd>MIN_BOUNCE_SPD){
          gravBounceEffect(0,p.y+R,'left',spd,i);
          lastBounceSound=gravBounceSound(spd,lastBounceSound);
        }
      }
      // Right wall
      if(p.x+R*2>=cW()){
        p.x=cW()-R*2;
        const spd=Math.abs(v.x);
        v.x=-spd*BOUNCE_WALL;
        if(spd>MIN_BOUNCE_SPD){
          gravBounceEffect(cW(),p.y+R,'right',spd,i);
          lastBounceSound=gravBounceSound(spd,lastBounceSound);
        }
      }

      setPos(e,p.x,p.y);
    });
    checkCollisions();
    requestAnimationFrame(loop);
  })();
}

function gravBounceEffect(x,y,wall,speed,circleIdx){
  const colors=['#ff6644','#4488ff','#44ee88'];
  const col=colors[circleIdx];
  const n=Math.min(12,Math.floor(speed*0.8));
  // Sparks angled away from wall
  const baseAngle=wall==='floor'?-Math.PI/2:wall==='left'?0:Math.PI;
  for(let i=0;i<n;i++){
    const a=baseAngle+(-0.6+Math.random()*1.2);
    const spd=2+Math.random()*speed*0.25;
    particles.push({x,y,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,r:Math.random()*3+1,life:1,decay:.05+Math.random()*.04,color:col});
  }
  // Small shockwave ring at impact
  if(speed>5) spawnShockwave(x,y,'rgba(255,200,100,',40+speed*3,speed*.6);
}

function gravBounceSound(speed,lastTime){
  const now=Date.now();
  if(now-lastTime<60)return lastTime; // throttle
  // Pitch and volume scale with speed
  const vol=Math.min(0.28,0.06+speed*0.01);
  const freq=120+speed*8;
  SFX.bounce(freq,vol);
  return now;
}

function stopGravity(){gravityActive=false;}

// ══════════════════════════════════════════
// TIMER
// ══════════════════════════════════════════
function startTimer(seconds=30){
  timeLeft=seconds;els.timerVal.textContent=timeLeft;els.timerVal.classList.remove('urgent');
  els.timerDisplay.classList.add('show');
  timerInterval=setInterval(()=>{
    timeLeft--;els.timerVal.textContent=timeLeft;
    if(timeLeft<=10)els.timerVal.classList.add('urgent');
    if(timeLeft<=0){stopTimer();if(!merged){setStatus("⏰ TIME'S UP — TRY AGAIN",'danger');els.restartBtn.classList.add('show');}}
  },1000);
}
function stopTimer(){clearInterval(timerInterval);timerInterval=null;}

