// 🚀 ADVENTURE MODE
// ══════════════════════════════════════════
const ADV_KEY='circle_alchemy_adventure_save_v1';
let advActive=false;
let advScene='map';
let advCurrentPlanet='mars';

function advDefaultPlanetState(missionCount){
  return {
    currentMission:0,
    missionProgress:new Array(missionCount).fill(0),
    bossDefeated:false,
  };
}

function advDefaultState(){
  return {
    energy:0,
    earth:{
      upgrades:{
        stableFusion:0,
        energyBoost:0,
        fasterDrag:0,
        strongerFusion:0,
        singularityChance:0,
        fusionBurst:0,
        coreShield:0,
        gravityPulse:0,
      },
    },
    mars:advDefaultPlanetState(6),
    phobos:advDefaultPlanetState(5),
    deimos:advDefaultPlanetState(4),
    phobosUnlocked:false,
    deimosUnlocked:false,
  };
}

function advMergePlanetState(savedPlanet,missionCount){
  const def=advDefaultPlanetState(missionCount);
  const savedProgress=Array.isArray(savedPlanet?.missionProgress)?savedPlanet.missionProgress:[];
  return {
    ...def,
    ...(savedPlanet||{}),
    missionProgress:def.missionProgress.map((_,i)=>savedProgress[i]||0),
  };
}

function advLoad(){
  try{
    const raw=localStorage.getItem(ADV_KEY);
    if(!raw)return advDefaultState();
    const saved=JSON.parse(raw);
    const def=advDefaultState();
    return {
      ...def,
      ...(saved||{}),
      earth:{
        ...def.earth,
        ...(saved?.earth||{}),
        upgrades:{
          ...def.earth.upgrades,
          ...(saved?.earth?.upgrades||{}),
        },
      },
      mars:advMergePlanetState(saved?.mars,6),
      phobos:advMergePlanetState(saved?.phobos,5),
      deimos:advMergePlanetState(saved?.deimos,4),
      phobosUnlocked:!!saved?.phobosUnlocked,
      deimosUnlocked:!!saved?.deimosUnlocked,
    };
  }catch(e){
    return advDefaultState();
  }
}

function advSave(){
  try{ localStorage.setItem(ADV_KEY,JSON.stringify(advState)); }catch(e){}
}

function advResetProgress(){
  try{ localStorage.removeItem(ADV_KEY); }catch(e){}
  advState=advDefaultState();
  advSave();
  toast('Adventure progress reset','#ffcc66');
  if(advActive)advShowMap();
}

