  const host=(window.location.hostname||'').toLowerCase();
  const isLoopback=host==='localhost'||host==='127.0.0.1'||host==='0.0.0.0'||host==='::1';
  const isLan=/^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[0-1])\.)/.test(host);
