function adminSummonOrbFightBoss(item){
  if(mode!=='orbfight') setMode('orbfight');
  OF.reset();
  MISSION_MODE.setMode('sandbox');
  const typeKey=item.orbType;
  const def=OF.TYPES[typeKey];
  if(!def) return;
  const enemyX=OF.W*0.74;
  const enemyY=OF.H*0.5;
  const allyX=OF.W*0.26;
  const allyY=OF.H*0.5;
  OF.orbs.push(OF._makeOrb(typeKey,enemyX,enemyY,'blue',def.r));
  OF.orbs.push(OF._makeOrb('basic_red',allyX,allyY,'red',OF.TYPES.basic_red.r));
  OF.updateHUD();
  OF.selectedType='basic_red';
  showMsg('MISSION BOSS TEST','ADMIN SANDBOX LOADOUT READY',item.color);
  setStatus(`MISSION BOSS TEST — ${item.label}`,'merged');
  flashScreen('rgba(255,255,255,.2)');
  shake('md');
}

function _adminFusionSequence(item){
  // Ensure we're in a clean state
  if(merged) restart();
  merged=true;
  dragging=null;
  stopGravity();

  const cx=cW()/2, cy=cH()/2;
  const circles=[els.red,els.blue,els.green];
  const circleColors=['#ff4455','#4488ff','#44ee88'];

  // Make circles visible and positioned
  popCirclesOut();
  circles.forEach(e=>{
    e.classList.remove('fading','magnetic');
    e.style.pointerEvents='none';
    e.style.transition='none';
  });

  // ── PHASE 1: Vibrate (0.6s) ──
  let vibT=0;
  const basePositions=circles.map(e=>getCenter(e));
  const vib=setInterval(()=>{
    vibT+=16;
    const amp=2+vibT/80;
    circles.forEach((e,i)=>{
      const bp=basePositions[i];
      const nx=bp.x-R+(-amp+Math.random()*amp*2);
      const ny=bp.y-R+(-amp+Math.random()*amp*2);
      setPos(e,nx,ny);
    });
    if(vibT>=600){ clearInterval(vib); _adminSwirl(cx,cy,circles,circleColors,item); }
  },16);

  // Status + flash
  setStatus(`⬡ ADMIN SUMMON — ${item.label}`,'merged');
  flashScreen(`rgba(68,170,255,.4)`);
  shake('sm');
  SFX.infinitePhase();
  showMsg(`⬡ SUMMONING`,item.label,item.color);
}

function _adminSwirl(cx,cy,circles,circleColors,item){
  // ── PHASE 2: Dramatic swirl (3s, 6 full rotations, accelerating) ──
  let t=0;
  const SWIRL_MS=2800;
  const startAngles=circles.map((_,i)=>(i/3)*Math.PI*2);

  const cvs=els.fusionChargeCvs;
  cvs.width=area.clientWidth; cvs.height=area.clientHeight;

  const swirl=setInterval(()=>{
    t+=16;
    const prog=Math.min(1, t/SWIRL_MS);
    const ease=prog<1 ? 1-Math.pow(1-prog,2.5) : 1;
    // Orbit radius collapses from 180 → 0, speed accelerates
    const dist=(1-ease)*190;
    const spin=prog*Math.PI*12; // 6 full rotations

    circles.forEach((e,i)=>{
      const ang=startAngles[i]+spin;
      setPos(e, cx+Math.cos(ang)*dist-R, cy+Math.sin(ang)*dist-R);
      if(Math.random()<prog*.5) spawnSparks(cx+Math.cos(ang)*dist, cy+Math.sin(ang)*dist, circleColors[i], 2);
    });

    // Energy ring on canvas — color from item
    const ctx=cvs.getContext('2d');
    ctx.clearRect(0,0,cvs.width,cvs.height);
    const ringR=18+ease*70;
    ctx.beginPath();ctx.arc(cx,cy,ringR,0,Math.PI*2);
    ctx.strokeStyle=`${item.color.replace('#','')==item.color.replace('#','') ? item.color : item.color}${Math.floor((0.15+ease*.65)*255).toString(16).padStart(2,'0')}`;
    // Simpler: use rgba
    const ri=parseInt(item.color.slice(1,3),16)||68;
    const gi=parseInt(item.color.slice(3,5),16)||170;
    const bi=parseInt(item.color.slice(5,7),16)||255;
    ctx.strokeStyle=`rgba(${ri},${gi},${bi},${0.2+ease*.75})`;
    ctx.lineWidth=3+ease*8;
    ctx.shadowColor=`rgba(${ri},${gi},${bi},.8)`;ctx.shadowBlur=20+ease*30;
    ctx.stroke();
    // Inner spinning lines
    for(let s=0;s<3;s++){
      const a=spin*1.5+(s/3)*Math.PI*2;
      ctx.beginPath();
      ctx.moveTo(cx,cy);
      ctx.lineTo(cx+Math.cos(a)*ringR*.8,cy+Math.sin(a)*ringR*.8);
      ctx.strokeStyle=`rgba(${ri},${gi},${bi},${0.3+ease*.4})`;
      ctx.lineWidth=1+ease*2;ctx.shadowBlur=10;ctx.stroke();
    }

    // Shake escalates
    if(prog>0.5&&Math.random()<(prog-.5)*0.4) shake('sm');

    if(prog>=1){
      clearInterval(swirl);
      ctx.clearRect(0,0,cvs.width,cvs.height);
      circles.forEach(e=>{ e.style.opacity='0'; e.style.pointerEvents='none'; });
      // Big convergence flash
      flashScreen(`rgba(${ri},${gi},${bi},.75)`);
      shake('lg');
      spawnParticles(cx,cy,item.color,100,12);
      spawnParticles(cx,cy,'#ffffff',60,16);
      spawnShockwave(cx,cy,`rgba(${ri},${gi},${bi},`,cW()*.9,12);
      SFX.fusion();
      setTimeout(()=>_adminTrigger(cx,cy,item), 600);
    }
  },16);
}

function _adminTrigger(cx,cy,item){
  // ── PHASE 3: Trigger the actual thing ──
  merged=false; // allow triggers to work

  if(item.type==='fusion'){
    switch(item.key||Object.keys(ADMIN_ITEMS).find(k=>ADMIN_ITEMS[k]===item)){
      case 'gold':
        triggerGoldOrb(cx,cy,false);
        break;
      case 'perfect':
        if(getTripleGoldFusionDef(true)){
          triggerTripleGoldFusion(cx,cy,true);
          break;
        }
        // Force perfect orb
        const combo=bumpCombo();
        Object.assign(els.gold.style,{
          width:'138px',height:'138px',left:cx+'px',top:cy+'px',
          background:'radial-gradient(circle at 38% 35%,#ffffff,#fff8aa 25%,#f5c842 55%,#c87800)',
          boxShadow:'0 0 80px 30px rgba(255,255,200,.9),0 0 160px 70px rgba(245,200,66,.6),inset 0 2px 0 rgba(255,255,255,.7)',
          animation:'',filter:'',transition:'opacity .4s,transform .5s cubic-bezier(.175,.885,.32,1.4)',
        });
        els.orbText.textContent='PERFECT';els.orbIcon.textContent='✦✦';
        els.orbText.style.color='';els.orbIcon.style.color='';
        els.gold.style.pointerEvents='all';els.gold.style.cursor='pointer';
        els.gold.classList.add('visible');
        els.gold.onclick=splitApart;
        merged=true;
        spawnParticles(cx,cy,'#ffffff',80);spawnParticles(cx,cy,'#f5c842',50);
        spawnShockwave(cx,cy,'rgba(255,230,100,',200,10);
        flashScreen('rgba(255,255,200,.7)');shake('md');
        showMsg('✦ PERFECT FUSION','ADMIN FORCED — ALL ELEMENTS ALIGNED','#ffffff');
        setStatus('✦ PERFECT FUSION — CLICK ORB TO SPLIT','merged');
        SFX.perfectFusion();
        setTimeout(()=>startOrbPersonality(true),500);
        break;
      case 'diamond':
        triggerDiamondFusion(cx,cy);
        break;
      case 'meltdown':
        merged=true;
        triggerMeltdown(cx,cy);
        break;
      case 'blackhole':
        triggerBlackHole(cx,cy);
        break;
      case 'singularity':
        merged=true;
        doSingularity(cx,cy);
        break;
    }
  } else if(item.type==='boss'){
    if(mode!=='boss') setMode('boss');
    bossRun=item.run-1; // triggerBoss will increment
    triggerBoss(cx,cy);
  } else if(item.type==='infinite'){
    // Set up as if all bosses were defeated
    if(mode!=='boss') setMode('boss');
    bossRun=5;
    flashScreen('rgba(120,80,255,.7)');shake('lg');
    showMsg('⬡ ADMIN SUMMON','INFINITE CIRCLE — PREPARE','#cc88ff');
    setTimeout(()=>triggerInfiniteSequence(),1200);
  }
}

// ══════════════════════════════════════════
// 🎨 ORB CREATOR
// ══════════════════════════════════════════
const CREATOR={
  active:false,
  currentTab:'appearance',
  config:{
    name:'',
    size:1,
    mainColor:'#4488ff',
    glowColor:'#3366ff',
    animation:'pulse',
    decorations:[],
    effects:[],
    combat:{
      health:180,
      damage:22,
      behavior:'aggressive',
      targeting:'closest',
      classification:'regular',
      bossMode:false,
      canSummon:false,
      minionCount:3,
      minionRate:3,
      minionPower:12,
      abilities:['shield','none','none','none']
    },
    attacks:[
      {id:'laser',label:'Laser Beam',enabled:true,damage:24,cooldown:1.4,range:560},
      {id:'missile',label:'Missile Launch',enabled:false,damage:40,cooldown:3.6,range:620},
      {id:'pulse',label:'Energy Pulse',enabled:true,damage:16,cooldown:2.1,range:280},
      {id:'shockwave',label:'Shockwave',enabled:false,damage:34,cooldown:4.8,range:240},
      {id:'chain',label:'Chain Lightning',enabled:false,damage:20,cooldown:2.7,range:450},
      {id:'projectile',label:'Projectile Blast',enabled:false,damage:18,cooldown:1.0,range:500}
    ]
  },
  canvas:null,
  ctx:null,
  animT:0,
  renderLoop:null,
  testActive:false,
  testCanvas:null,
  testCtx:null,
  testEnemies:[],
  testMinions:[],
  testFx:[],
  testOrb:{x:0,y:0,hp:0,maxHp:0},
  simClock:0,
  attackState:{},
  minionState:{lastSpawn:0},
  testSettings:{autoSpawn:true,maxEnemies:14,info:'COMBAT SIMULATION - Click to spawn enemy - ESC to exit'},

  init(){
    this.canvas=document.getElementById('creator-canvas');
    if(!this.canvas)return;
    this.ctx=this.canvas.getContext('2d');
    this.canvas.width=320;this.canvas.height=320;
    const saveNameInput=document.getElementById('cc-save-name');
    if(saveNameInput){
      saveNameInput.addEventListener('input',e=>this.setOrbName(e.target.value));
    }
    const importNameInput=document.getElementById('cc-orbfight-name');
    if(importNameInput){
      importNameInput.addEventListener('input',e=>this.setOrbName(e.target.value));
    }
    const enemyHpPreset=document.getElementById('cc-enemy-hp-preset');
    if(enemyHpPreset){
      enemyHpPreset.addEventListener('change',()=>this.syncEnemyHpPreset());
    }
    this.testCanvas=document.getElementById('creator-test-canvas');
    if(this.testCanvas){
      this.testCtx=this.testCanvas.getContext('2d');
      this.testCanvas.addEventListener('click',e=>this.onTestClick(e));
    }
    window.addEventListener('resize',()=>{
      if(this.active)this.syncOverlayLayout();
    });
    this.setupTabs();
    this.switchTab('appearance');
    this.render();
  },

  uiClick(){ if(SFX.uiClick) SFX.uiClick(); },

  setOrbName(name){
    this.config.name=(name||'').replace(/\s+/g,' ').trim().slice(0,32);
    const saveNameInput=document.getElementById('cc-save-name');
    if(saveNameInput&&saveNameInput.value!==this.config.name)saveNameInput.value=this.config.name;
    const importNameInput=document.getElementById('cc-orbfight-name');
    if(importNameInput&&importNameInput.value!==this.config.name)importNameInput.value=this.config.name;
  },

  getOrbName(){
    return (this.config.name||'').trim();
  },

  getSizeRadius(scale=1){
    const sizeMap=[60,78,102,132];
    return (sizeMap[this.config.size]||78)*scale;
  },

  createDefaultConfig(){
    return {
      name:'',
      size:1,
      mainColor:'#4488ff',
      glowColor:'#3366ff',
      animation:'pulse',
      decorations:[],
      effects:[],
      combat:{
        health:180,
        damage:22,
        behavior:'aggressive',
        targeting:'closest',
        classification:'regular',
        bossMode:false,
        canSummon:false,
        minionCount:3,
        minionRate:3,
        minionPower:12,
        abilities:['shield','none','none','none']
      },
      attacks:[
        {id:'laser',label:'Laser Beam',enabled:true,damage:24,cooldown:1.4,range:560},
        {id:'missile',label:'Missile Launch',enabled:false,damage:40,cooldown:3.6,range:620},
        {id:'pulse',label:'Energy Pulse',enabled:true,damage:16,cooldown:2.1,range:280},
        {id:'shockwave',label:'Shockwave',enabled:false,damage:34,cooldown:4.8,range:240},
        {id:'chain',label:'Chain Lightning',enabled:false,damage:20,cooldown:2.7,range:450},
        {id:'projectile',label:'Projectile Blast',enabled:false,damage:18,cooldown:1.0,range:500}
      ]
    };
  },

  syncEnemyHpPreset(){
    const hpPreset=document.getElementById('cc-enemy-hp-preset');
    const hpInput=document.getElementById('cc-enemy-hp');
    if(!hpPreset||!hpInput)return;
    if(hpPreset.value!=='custom')hpInput.value=hpPreset.value;
  },

  toggleEnemyPanel(){
    const panel=document.getElementById('creator-enemy-panel');
    if(!panel)return;
    panel.classList.toggle('show');
    if(panel.classList.contains('show'))this.syncEnemyHpPreset();
    this.uiClick();
  },

  closeEnemyPanel(playSound=true){
    const panel=document.getElementById('creator-enemy-panel');
    if(panel)panel.classList.remove('show');
    if(playSound)this.uiClick();
  },

  startTestArena(){
    this.closeEnemyPanel(false);
    this.testOrb({autoSpawn:true,maxEnemies:14,info:'TEST ARENA - Click to spawn enemy - ESC to exit'});
  },

  quickBattle(){
    this.closeEnemyPanel(false);
    this.testOrb({autoSpawn:false,maxEnemies:10,info:'QUICK BATTLE - Enemy wave deployed - ESC to exit'});
    this.spawnEnemyWave({type:'raider',hp:140,count:3,showToast:false});
    this.spawnEnemyWave({type:'swift',hp:110,count:2,showToast:false});
    this.spawnEnemyWave({type:'tank',hp:260,count:1,showToast:false});
    toast('Quick Battle started','#44ee88');
    this.uiClick();
  },

  getEnemyTemplate(typeKey='raider'){
    const templates={
      raider:{r:18,speed:1.4,color:'#ff7b90',core:'#7a2440',glow:'#ffb2bf'},
      swift:{r:14,speed:2.1,color:'#ffb366',core:'#8a4f1d',glow:'#ffd1a1'},
      tank:{r:26,speed:0.85,color:'#d48dff',core:'#4f246b',glow:'#efc7ff'},
      drone:{r:16,speed:1.7,color:'#84e8ff',core:'#1f5875',glow:'#b8f5ff'}
    };
    return templates[typeKey]||templates.raider;
  },

  spawnTestEnemy(options={}){
    if(!this.testCanvas)return null;
    const template=this.getEnemyTemplate(options.type);
    const hp=Math.max(10,Math.round(options.hp||140));
    const r=options.r||template.r;
    const width=this.testCanvas.width||window.innerWidth;
    const height=this.testCanvas.height||window.innerHeight;
    let x=options.x;
    let y=options.y;
    if(x==null||y==null){
      const margin=r+24;
      const edge=Math.floor(Math.random()*4);
      if(edge===0){x=Math.random()*width;y=margin;}
      else if(edge===1){x=width-margin;y=Math.random()*height;}
      else if(edge===2){x=Math.random()*width;y=height-margin;}
      else{x=margin;y=Math.random()*height;}
    }
    x=Math.max(r,Math.min(width-r,x));
    y=Math.max(r,Math.min(height-r,y));
    const angle=options.angle==null?Math.random()*Math.PI*2:options.angle;
    const speed=options.speed==null?template.speed:options.speed;
    return {
      x,y,
      hp,maxHp:hp,
      r,
      vx:Math.cos(angle)*speed,
      vy:Math.sin(angle)*speed,
      type:options.type||'raider',
      color:template.color,
      core:template.core,
      glow:template.glow
    };
  },

  spawnEnemyWave({type='raider',hp=140,count=1,showToast=true}={}){
    if(!this.testActive){
      this.testOrb({autoSpawn:false,maxEnemies:24,info:'TEST ARENA - Custom enemy wave loaded - ESC to exit'});
    }
    const total=Math.max(1,Math.min(20,parseInt(count)||1));
    const radius=Math.min(this.testCanvas.width,this.testCanvas.height)*0.34;
    for(let i=0;i<total;i++){
      const angle=(Math.PI*2/total)*i+Math.random()*0.28;
      const x=this.testOrb.x+Math.cos(angle)*radius;
      const y=this.testOrb.y+Math.sin(angle)*radius;
      const enemy=this.spawnTestEnemy({type,hp,x,y,angle:angle+Math.PI});
      if(enemy)this.testEnemies.push(enemy);
    }
    if(showToast)toast(`Spawned ${total} ${type}${total===1?'':'s'}`,'#7dcfff');
  },

  spawnConfiguredEnemies(){
    this.syncEnemyHpPreset();
    const hpInput=document.getElementById('cc-enemy-hp');
    const typeInput=document.getElementById('cc-enemy-type');
    const countInput=document.getElementById('cc-enemy-count');
    const hp=Math.max(10,parseInt(hpInput?.value)||140);
    const count=Math.max(1,Math.min(20,parseInt(countInput?.value)||1));
    const type=typeInput?.value||'raider';
    this.closeEnemyPanel(false);
    this.spawnEnemyWave({type,hp,count});
    this.uiClick();
  },

  randomizeOrb(){
    const palettes=[
      {main:'#ff5f6d',glow:'#ffc371'},
      {main:'#33d17a',glow:'#9bffcb'},
      {main:'#4d96ff',glow:'#77d8ff'},
      {main:'#b26bff',glow:'#f0a6ff'},
      {main:'#f5c842',glow:'#fff1a8'},
      {main:'#f7fbff',glow:'#9ec7ff'}
    ];
    const animations=['pulse','energyswirl','staticglow','orbiting','storm'];
    const decorations=['rings','orbitingstars','energyspikes','halo','techpanels'];
    const effects=['outerglow','spark','aura','trail'];
    const palette=palettes[Math.floor(Math.random()*palettes.length)];
    this.config.size=Math.floor(Math.random()*4);
    this.config.mainColor=palette.main;
    this.config.glowColor=palette.glow;
    this.config.animation=animations[Math.floor(Math.random()*animations.length)];
    this.config.decorations=decorations.filter(()=>Math.random()>.52);
    this.config.effects=effects.filter(eff=>eff!=='trail'&&Math.random()>.58);
    this.refreshUI();
    this.render();
    toast('Orb appearance randomized','#7dcfff');
    this.uiClick();
  },

  duplicateOrb(){
    const clone=JSON.parse(JSON.stringify(this.config));
    const baseName=(clone.name||'Custom Orb').trim()||'Custom Orb';
    clone.name=`${baseName} Copy`.slice(0,32);
    this.config=clone;
    this.refreshUI();
    this.render();
    toast('Orb configuration duplicated','#7dcfff');
    this.uiClick();
  },

  resetOrb(){
    this.config=this.createDefaultConfig();
    if(this.testActive)this.stopTest();
    this.closeEnemyPanel(false);
    this.refreshUI();
    this.render();
    toast('Orb reset to defaults','#ffcc66');
    this.uiClick();
  },

  exportOrb(){
    this.showSavePrompt();
  },

  importOrb(){
    this.showLoadPrompt();
  },

  cloneExportConfig(){
    return JSON.parse(JSON.stringify({
      name:this.getOrbName(),
      size:this.config.size,
      mainColor:this.config.mainColor,
      glowColor:this.config.glowColor,
      animation:this.config.animation,
      decorations:this.config.decorations,
      effects:this.config.effects
    }));
  },

  promptAddToOrbFight(){
    const prompt=document.getElementById('cc-orbfight-prompt');
    if(!prompt)return;
    const input=document.getElementById('cc-orbfight-name');
    if(input)input.value=this.getOrbName();
    prompt.classList.add('show');
    if(input)setTimeout(()=>input.focus(),0);
    this.uiClick();
  },

  hideOrbFightPrompt(){
    document.getElementById('cc-orbfight-prompt')?.classList.remove('show');
    this.uiClick();
  },

  confirmAddToOrbFight(){
    const rawName=document.getElementById('cc-orbfight-name')?.value||'';
    const name=rawName.replace(/\s+/g,' ').trim().slice(0,32);
    if(!name){
      toast('Type a name before importing to Orb Fight','#ff6655');
      document.getElementById('cc-orbfight-name')?.focus();
      return;
    }
    this.setOrbName(name);
    this.hideOrbFightPrompt();
    this.addToOrbFight(name);
  },

  syncOverlayLayout(){
    const overlay=document.getElementById('creator-overlay');
    if(!overlay)return;
    const headerHeight=els.header?Math.ceil(els.header.getBoundingClientRect().height):0;
    overlay.style.setProperty('--creator-top',`${headerHeight}px`);
  },

  setupTabs(){
    document.querySelectorAll('#creator-tabs .cc-tab').forEach(btn=>{
      btn.addEventListener('click',()=>{
        this.switchTab(btn.getAttribute('data-tab'));
        this.uiClick();
      });
    });
  },

  switchTab(tabName){
    if(!this.config.combat){
      this.config.combat={
        health:180,damage:22,behavior:'aggressive',targeting:'closest',classification:'regular',bossMode:false,
        canSummon:false,minionCount:3,minionRate:3,minionPower:12,abilities:['shield','none','none','none']
      };
    }
    if(!Array.isArray(this.config.attacks)){
      this.config.attacks=[
        {id:'laser',label:'Laser Beam',enabled:true,damage:24,cooldown:1.4,range:560},
        {id:'missile',label:'Missile Launch',enabled:false,damage:40,cooldown:3.6,range:620},
        {id:'pulse',label:'Energy Pulse',enabled:true,damage:16,cooldown:2.1,range:280},
        {id:'shockwave',label:'Shockwave',enabled:false,damage:34,cooldown:4.8,range:240},
        {id:'chain',label:'Chain Lightning',enabled:false,damage:20,cooldown:2.7,range:450},
        {id:'projectile',label:'Projectile Blast',enabled:false,damage:18,cooldown:1.0,range:500}
      ];
    }
    this.currentTab=tabName;
    document.querySelectorAll('#creator-tabs .cc-tab').forEach(btn=>{
      btn.classList.toggle('active',btn.getAttribute('data-tab')===tabName);
    });
    this.buildUI();
  },

  buildUI(){
    if(this.currentTab==='appearance') this.buildAppearanceUI();
    else if(this.currentTab==='orbfight') this.buildCombatUI();
    else this.buildSaveUI();
  },

  buildAppearanceUI(){
    const panels=document.getElementById('creator-panels');
    if(!panels)return;
    panels.innerHTML=`
      <div class="cc-panel">
        <div class="cc-panel-title">Size</div>
        <div class="cc-control">
          <div class="cc-label">Orb Size</div>
          <input id="cc-size-slider" class="cc-slider" type="range" min="0" max="3" value="${this.config.size}">
          <div id="cc-size-label" class="cc-value-display">${['Small','Medium','Large','Titan'][this.config.size]}</div>
        </div>
      </div>
      <div class="cc-panel">
        <div class="cc-panel-title">Color</div>
        <div class="cc-control">
          <div class="cc-label">Main / Glow</div>
          <div class="cc-color-picker-container">
            <input id="cc-color-main" class="cc-color-input" type="color" value="${this.config.mainColor}">
            <input id="cc-color-glow" class="cc-color-input" type="color" value="${this.config.glowColor}">
          </div>
        </div>
        <div class="cc-control">
          <div class="cc-label">Presets</div>
          <div id="cc-color-presets" class="cc-preset-grid"></div>
        </div>
      </div>
      <div class="cc-panel">
        <div class="cc-panel-title">Animation</div>
        <div id="cc-animation-group" class="cc-toggle-group"></div>
      </div>
      <div class="cc-panel">
        <div class="cc-panel-title">Decoration</div>
        <div id="cc-decoration-group" class="cc-toggle-group"></div>
      </div>
      <div class="cc-panel">
        <div class="cc-panel-title">Effects</div>
        <div id="cc-effects-group" class="cc-toggle-group"></div>
      </div>
    `;

    document.getElementById('cc-size-slider').oninput=()=>{this.updateSize();};
    document.getElementById('cc-color-main').oninput=()=>{this.updateColor();};
    document.getElementById('cc-color-glow').oninput=()=>{this.updateColor();};

    const colorPresets=[
      {name:'Crimson', main:'#ff4455', glow:'#ff6677'},
      {name:'Emerald', main:'#44ee88', glow:'#66ff99'},
      {name:'Azure', main:'#4488ff', glow:'#6699ff'},
      {name:'Gold', main:'#f5c842', glow:'#ffdd77'},
      {name:'Violet', main:'#cc44ff', glow:'#ee77ff'},
      {name:'White', main:'#ffffff', glow:'#ccccff'},
    ];
    const grid=document.getElementById('cc-color-presets');
    colorPresets.forEach(({name,main,glow})=>{
      const btn=document.createElement('button');
      btn.className='cc-preset-btn';
      btn.textContent=name;
      btn.style.background=main;
      btn.style.opacity='0.5';
      btn.onclick=()=>{
        document.getElementById('cc-color-main').value=main;
        document.getElementById('cc-color-glow').value=glow;
        document.querySelectorAll('#cc-color-presets .cc-preset-btn').forEach(b=>b.classList.remove('selected'));
        btn.classList.add('selected');
        this.updateColor();
        this.uiClick();
      };
      grid.appendChild(btn);
    });

    const animations=[
      'Pulse','Energy Swirl','Static Glow','Orbiting','Storm'
    ];
    const animGroup=document.getElementById('cc-animation-group');
    animations.forEach((anim,i)=>{
      const btn=document.createElement('button');
      btn.className='cc-toggle-btn';
      if(i===0)btn.classList.add('active');
      btn.textContent=anim;
      const key=anim.toLowerCase().replace(/\s+/g,'');
      btn.onclick=()=>{
        document.querySelectorAll('#cc-animation-group .cc-toggle-btn').forEach(b=>b.classList.remove('active'));
        btn.classList.add('active');
        this.config.animation=key;
        this.render();
        this.uiClick();
      };
      animGroup.appendChild(btn);
    });

    const decorations=[
      'Rings','Orbiting Stars','Energy Spikes','Halo','Tech Panels'
    ];
    const decorGroup=document.getElementById('cc-decoration-group');
    decorations.forEach(dec=>{
      const btn=document.createElement('button');
      btn.className='cc-toggle-btn';
      btn.textContent=dec;
      const key=dec.toLowerCase().replace(/\s+/g,'');
      btn.onclick=()=>{
        btn.classList.toggle('active');
        if(btn.classList.contains('active')){
          if(!this.config.decorations.includes(key))this.config.decorations.push(key);
        }else{
          this.config.decorations=this.config.decorations.filter(d=>d!==key);
        }
        this.render();
        this.uiClick();
      };
      decorGroup.appendChild(btn);
    });

    const effects=[
      'Outer Glow','Spark','Aura','Trail'
    ];
    const effectsGroup=document.getElementById('cc-effects-group');
    effects.forEach(eff=>{
      const btn=document.createElement('button');
      btn.className='cc-toggle-btn';
      btn.textContent=eff;
      const key=eff.toLowerCase().replace(/\s+/g,'');
      btn.onclick=()=>{
        btn.classList.toggle('active');
        if(btn.classList.contains('active')){
          if(!this.config.effects.includes(key))this.config.effects.push(key);
        }else{
          this.config.effects=this.config.effects.filter(e=>e!==key);
        }
        this.render();
        this.uiClick();
      };
      effectsGroup.appendChild(btn);
    });
  },

  buildCombatUI(){
    const c=this.config.combat;
    const panels=document.getElementById('creator-panels');
    if(!panels)return;

    const attackCards=this.config.attacks.map((a,idx)=>`
      <div class="cc-attack-card ${a.enabled?'active':''}" data-attack="${idx}">
        <div class="cc-attack-head">
          <span>${a.label}</span>
          <label><input type="checkbox" class="cc-attack-enable" data-attack="${idx}" ${a.enabled?'checked':''}> Enable</label>
        </div>
        <div class="cc-mini-grid">
          <div><div class="cc-label">Damage</div><input type="number" min="1" max="2000" class="cc-attack-dmg" data-attack="${idx}" value="${a.damage}"></div>
          <div><div class="cc-label">Cooldown</div><input type="number" step="0.1" min="0.1" max="20" class="cc-attack-cd" data-attack="${idx}" value="${a.cooldown}"></div>
          <div><div class="cc-label">Range</div><input type="number" min="80" max="2000" class="cc-attack-range" data-attack="${idx}" value="${a.range}"></div>
        </div>
      </div>
    `).join('');

    const abilityOptions=['none','shield','gravity field','healing pulse','teleport burst','berserk mode'];
    const abilitySlots=[0,1,2,3].map(i=>{
      const locked=i===3&&!c.bossMode;
      const opts=abilityOptions.map(op=>`<option value="${op}" ${(c.abilities[i]===op)?'selected':''}>${op.toUpperCase()}</option>`).join('');
      return `<div class="cc-ability-slot ${locked?'locked':''}" data-slot="${i}"><div class="cc-label">Slot ${i+1}${i===3?' (Boss)':''}</div><select class="cc-ability-select" data-slot="${i}" ${locked?'disabled':''}>${opts}</select></div>`;
    }).join('');

    panels.innerHTML=`
      <div class="cc-panel">
        <div class="cc-panel-title">Stats</div>
        <div class="cc-control">
          <div class="cc-label">Health</div>
          <div class="cc-slider-group"><input class="cc-slider" id="cc-combat-health" type="range" min="10" max="5000" value="${c.health}"><input id="cc-combat-health-num" type="number" min="10" max="5000" value="${c.health}"></div>
        </div>
        <div class="cc-control">
          <div class="cc-label">Base Attack Damage</div>
          <div class="cc-slider-group"><input class="cc-slider" id="cc-combat-damage" type="range" min="1" max="600" value="${c.damage}"><input id="cc-combat-damage-num" type="number" min="1" max="600" value="${c.damage}"></div>
        </div>
      </div>
      <div class="cc-panel">
        <div class="cc-panel-title">Attacks</div>
        <div class="cc-note">Enable multiple attack presets and adjust damage, cooldown, and range for each.</div>
        <div class="cc-attack-grid">${attackCards}</div>
      </div>
      <div class="cc-panel">
        <div class="cc-panel-title">Abilities</div>
        <div class="cc-note">Boss Mode unlocks the fourth ability slot.</div>
        <div class="cc-ability-grid">${abilitySlots}</div>
      </div>
      <div class="cc-panel">
        <div class="cc-panel-title">Behavior</div>
        <div class="cc-control"><div class="cc-label">Combat Behavior</div><select id="cc-behavior"><option value="aggressive" ${c.behavior==='aggressive'?'selected':''}>Aggressive</option><option value="defensive" ${c.behavior==='defensive'?'selected':''}>Defensive</option><option value="summoner" ${c.behavior==='summoner'?'selected':''}>Summoner</option><option value="sniper" ${c.behavior==='sniper'?'selected':''}>Long-Range Sniper</option></select></div>
        <div class="cc-control"><div class="cc-label">Targeting Rule</div><select id="cc-targeting"><option value="closest" ${c.targeting==='closest'?'selected':''}>Closest Enemy</option><option value="strongest" ${c.targeting==='strongest'?'selected':''}>Strongest Enemy</option><option value="weakest" ${c.targeting==='weakest'?'selected':''}>Weakest Enemy</option><option value="random" ${c.targeting==='random'?'selected':''}>Random Enemy</option></select></div>
      </div>
      <div class="cc-panel">
        <div class="cc-panel-title">Classification</div>
        <div class="cc-control"><div class="cc-label">Category</div><select id="cc-classification"><option value="regular" ${c.classification==='regular'?'selected':''}>Regular Orb</option><option value="celestial" ${c.classification==='celestial'?'selected':''}>Celestial Orb</option><option value="boss" ${c.classification==='boss'?'selected':''}>Boss</option></select></div>
        <label class="cc-checkbox-label"><input id="cc-bossmode" type="checkbox" ${c.bossMode?'checked':''}><span>Boss Mode</span></label>
      </div>
      <div class="cc-panel">
        <div class="cc-panel-title">Minions</div>
        <label class="cc-checkbox-label"><input id="cc-minion-toggle" type="checkbox" ${c.canSummon?'checked':''}><span>Enable Minion Summoning</span></label>
        <div class="cc-mini-grid" style="margin-top:8px;"><div><div class="cc-label">Count</div><input id="cc-minion-count" type="number" min="0" max="20" value="${c.minionCount}"></div><div><div class="cc-label">Spawn Rate (s)</div><input id="cc-minion-rate" type="number" min="0.4" max="20" step="0.1" value="${c.minionRate}"></div><div><div class="cc-label">Power</div><input id="cc-minion-power" type="number" min="1" max="500" value="${c.minionPower}"></div></div>
      </div>
    `;

    const bindPair=(sliderId,inputId,key)=>{
      const sl=document.getElementById(sliderId), inp=document.getElementById(inputId);
      const sync=v=>{ c[key]=v; sl.value=v; inp.value=v; };
      sl.addEventListener('input',()=>{sync(parseFloat(sl.value)||0);this.uiClick();});
      inp.addEventListener('input',()=>{sync(parseFloat(inp.value)||0);});
    };
    bindPair('cc-combat-health','cc-combat-health-num','health');
    bindPair('cc-combat-damage','cc-combat-damage-num','damage');

    document.querySelectorAll('.cc-attack-enable').forEach(el=>el.addEventListener('change',e=>{
      const i=parseInt(e.target.getAttribute('data-attack'));
      this.config.attacks[i].enabled=e.target.checked;
      e.target.closest('.cc-attack-card').classList.toggle('active',e.target.checked);
      this.uiClick();
    }));
    document.querySelectorAll('.cc-attack-dmg').forEach(el=>el.addEventListener('input',e=>{const i=parseInt(e.target.getAttribute('data-attack'));this.config.attacks[i].damage=Math.max(1,parseFloat(e.target.value)||1);}));
    document.querySelectorAll('.cc-attack-cd').forEach(el=>el.addEventListener('input',e=>{const i=parseInt(e.target.getAttribute('data-attack'));this.config.attacks[i].cooldown=Math.max(.1,parseFloat(e.target.value)||.1);}));
    document.querySelectorAll('.cc-attack-range').forEach(el=>el.addEventListener('input',e=>{const i=parseInt(e.target.getAttribute('data-attack'));this.config.attacks[i].range=Math.max(80,parseFloat(e.target.value)||80);}));
    document.querySelectorAll('.cc-ability-select').forEach(el=>el.addEventListener('change',e=>{const slot=parseInt(e.target.getAttribute('data-slot'));c.abilities[slot]=e.target.value;this.uiClick();}));

    document.getElementById('cc-behavior').addEventListener('change',e=>{c.behavior=e.target.value;this.uiClick();});
    document.getElementById('cc-targeting').addEventListener('change',e=>{c.targeting=e.target.value;this.uiClick();});
    document.getElementById('cc-classification').addEventListener('change',e=>{c.classification=e.target.value;this.uiClick();});
    document.getElementById('cc-bossmode').addEventListener('change',e=>{c.bossMode=e.target.checked;if(!c.bossMode)c.abilities[3]='none';this.uiClick();this.buildCombatUI();});
    document.getElementById('cc-minion-toggle').addEventListener('change',e=>{c.canSummon=e.target.checked;this.uiClick();});
    document.getElementById('cc-minion-count').addEventListener('input',e=>{c.minionCount=Math.max(0,parseInt(e.target.value)||0);});
    document.getElementById('cc-minion-rate').addEventListener('input',e=>{c.minionRate=Math.max(0.4,parseFloat(e.target.value)||0.4);});
    document.getElementById('cc-minion-power').addEventListener('input',e=>{c.minionPower=Math.max(1,parseInt(e.target.value)||1);});
  },

  buildSaveUI(){
    const panels=document.getElementById('creator-panels');
    if(!panels)return;
    panels.innerHTML=`
      <div class="cc-panel">
        <div class="cc-panel-title">Save / Load</div>
        <div class="cc-note">Store your appearance and Orb Fight combat settings as a shareable code.</div>
        <div class="cc-button-row" style="grid-template-columns:1fr 1fr;">
          <button class="cc-action-btn" id="cc-open-save">Open Save Dialog</button>
          <button class="cc-action-btn" id="cc-open-load">Open Load Dialog</button>
        </div>
      </div>
    `;
    document.getElementById('cc-open-save').addEventListener('click',()=>{this.showSavePrompt();this.uiClick();});
    document.getElementById('cc-open-load').addEventListener('click',()=>{this.showLoadPrompt();this.uiClick();});
  },

  updateSize(){
    const val=parseInt(document.getElementById('cc-size-slider').value);
    this.config.size=val;
    document.getElementById('cc-size-label').textContent=['Small','Medium','Large','Titan'][val];
    this.render();
  },

  updateColor(){
    this.config.mainColor=document.getElementById('cc-color-main').value;
    this.config.glowColor=document.getElementById('cc-color-glow').value;
    this.render();
  },

  refreshUI(){
    this.buildUI();
  },

  showSavePrompt(){
    const code=this.generateSaveCode();
    document.getElementById('cc-save-code').textContent=code;
    document.getElementById('cc-save-name').value=this.getOrbName();
    document.getElementById('cc-save-prompt').classList.add('show');
    this.uiClick();
  },

  hideSavePrompt(){
    document.getElementById('cc-save-prompt').classList.remove('show');
    this.uiClick();
  },

  copySaveCode(){
    const code=document.getElementById('cc-save-code').textContent;
    navigator.clipboard.writeText(code);
    toast('✓ Save code copied!','#44ee88');
    this.uiClick();
  },

  showLoadPrompt(){
    document.getElementById('cc-load-code').value='';
    document.getElementById('cc-load-prompt').classList.add('show');
    this.uiClick();
  },

  hideLoadPrompt(){
    document.getElementById('cc-load-prompt').classList.remove('show');
    this.uiClick();
  },

  loadFromCode(){
    const code=document.getElementById('cc-load-code').value.trim();
    if(this.loadFromSaveCode(code)){
      this.hideLoadPrompt();
      toast('✓ Orb loaded!','#44ee88');
      this.buildUI();
    }
  },

  addToOrbFight(nameOverride){
    const key='custom_creator_orb';
    const c=this.config.combat||{};
    const toPrefix=(hex)=>{
      const h=(hex||'#4488ff').replace('#','');
      const r=parseInt(h.slice(0,2),16)||68;
      const g=parseInt(h.slice(2,4),16)||136;
      const b=parseInt(h.slice(4,6),16)||255;
      return `rgba(${r},${g},${b},`;
    };

    const behavior=(c.behavior||'aggressive');
    const spdMap={aggressive:1.25,defensive:0.85,summoner:0.95,sniper:1.1};
    const baseR=this.getSizeRadius();
    const isBoss=(c.classification==='boss')||!!c.bossMode;
    const isCelestial=(c.classification==='celestial');
    const label=(nameOverride||this.getOrbName()).trim();
    if(!label){
      toast('Type a name before importing to Orb Fight','#ff6655');
      this.promptAddToOrbFight();
      return;
    }

    this.setOrbName(label);

    OF.TYPES[key]={
      label,
      r:isBoss?Math.round(baseR*1.2):baseR,
      hp:Math.max(10,Math.round(c.health||180)),
      dmg:Math.max(1,Math.round(c.damage||22)),
      spd:spdMap[behavior]||1.0,
      color:this.config.mainColor,
      glow:toPrefix(this.config.glowColor),
      team:null,
      ability:'basic',
      isBoss,
      isCelestial,
      creatorConfig:this.cloneExportConfig()
    };

    const gridId=isCelestial?'of-grid-celestial':(isBoss?'of-grid-boss':'of-grid-basic');
    const grid=document.getElementById(gridId);
    if(!grid){
      toast('Orb Fight grid not found','#ff6655');
      return;
    }

    const existing=grid.querySelector(`[data-key="${key}"]`);
    const cls=['of-spawn-btn'];
    if(isBoss)cls.push('of-boss-btn');
    if(isCelestial)cls.push('of-celestial-btn');
    const text=(isCelestial?'✨ ':(isBoss?'☠ ':'✦ '))+label;

    if(existing){
      existing.className=cls.join(' ');
      existing.textContent=text;
    }else{
      const btn=document.createElement('button');
      btn.className=cls.join(' ');
      btn.setAttribute('data-key',key);
      btn.textContent=text;
      btn.onclick=()=>ofSelectOrb(key);
      grid.appendChild(btn);
    }

    this.uiClick();
    toast(`✓ Added to Orb Fight (${isCelestial?'Celestial':isBoss?'Bosses':'Basic'})`,'#44ee88');
  },

  enter(){
    this.active=true;
    const overlay=document.getElementById('creator-overlay');
    this.syncOverlayLayout();
    overlay.classList.add('show');
    const tabs=document.getElementById('creator-tabs');
    if(tabs){
      tabs.style.display='flex';
      tabs.style.opacity='1';
      tabs.style.visibility='visible';
    }
    // Reset simulation overlays so the tab bar cannot be accidentally covered
    if(this.testCanvas)this.testCanvas.style.display='none';
    const testInfo=document.getElementById('creator-test-info');
    if(testInfo)testInfo.style.display='none';
    [els.red,els.blue,els.green].forEach(e=>e.classList.add('hidden'));
    const tick=()=>{
      if(this.active){
        this.render();
        this.renderLoop=requestAnimationFrame(tick);
      }
    };
    tick();
  },

  exit(){
    this.active=false;
    if(this.renderLoop)cancelAnimationFrame(this.renderLoop);
    if(this.testActive)this.stopTest();
    const overlay=document.getElementById('creator-overlay');
    overlay.classList.remove('show');
    overlay.style.setProperty('--creator-top','0px');
    [els.red,els.blue,els.green].forEach(e=>e.classList.remove('hidden'));
  },

  render(){
    if(!this.ctx||!this.canvas)return;
    this.animT+=0.03;
    const ctx=this.ctx,cvs=this.canvas;
    const cx=cvs.width/2, cy=cvs.height/2;
    const r=this.getSizeRadius(1.05);

    // Clear
    ctx.fillStyle='#0a0f1e';
    ctx.fillRect(0,0,cvs.width,cvs.height);

    // Draw custom orb
    this._drawCustomOrb(ctx,cx,cy,r);
  },

  _drawCustomOrb(ctx,x,y,r,cfg=this.config,animT=this.animT){
    const t=animT;
    const anim=cfg.animation;
    const pulse=0.90+0.10*Math.sin(t*1.5);
    const rPulse=r*pulse;
    const mainCol=cfg.mainColor;
    const glowCol=cfg.glowColor;

    ctx.save();

    // Outer glow
    if(cfg.effects.includes('outerglow')){
      const gg=ctx.createRadialGradient(x,y,0,x,y,rPulse*3);
      gg.addColorStop(0,'rgba(255,255,255,0.1)');
      gg.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=gg;ctx.beginPath();ctx.arc(x,y,rPulse*3,0,Math.PI*2);ctx.fill();
    }

    // Main glow
    const gg=ctx.createRadialGradient(x,y,0,x,y,rPulse*2);
    gg.addColorStop(0,'rgba(200,200,255,0.15)');
    gg.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=gg;ctx.beginPath();ctx.arc(x,y,rPulse*2,0,Math.PI*2);ctx.fill();

    // Body
    const bg=ctx.createRadialGradient(x,y,0,x,y,rPulse);
    bg.addColorStop(0,mainCol);bg.addColorStop(0.5,glowCol);bg.addColorStop(1,'#000000');
    ctx.fillStyle=bg;ctx.beginPath();ctx.arc(x,y,rPulse,0,Math.PI*2);ctx.fill();
    ctx.shadowColor=glowCol;ctx.shadowBlur=25;ctx.strokeStyle=glowCol;ctx.lineWidth=2;ctx.stroke();

    // Animation: Pulse
    if(anim==='pulse'){
      const innerGlow=ctx.createRadialGradient(x,y,0,x,y,rPulse*.3);
      innerGlow.addColorStop(0,glowCol);innerGlow.addColorStop(1,'rgba(255,255,255,0)');
      ctx.fillStyle=innerGlow;ctx.beginPath();ctx.arc(x,y,rPulse*.3,0,Math.PI*2);ctx.fill();
    }
    // Animation: Energy Swirl
    else if(anim==='energyswirl'){
      for(let i=0;i<3;i++){
        const a=t*0.5+i*(Math.PI*2/3);
        const sx=x+Math.cos(a)*rPulse*.5, sy=y+Math.sin(a)*rPulse*.5;
        const sz=rPulse*.1;
        ctx.fillStyle=glowCol;ctx.globalAlpha=0.6;ctx.beginPath();ctx.arc(sx,sy,sz,0,Math.PI*2);ctx.fill();
      }
    }
    // Animation: Static Glow
    else if(anim==='staticglow'){
      ctx.fillStyle=glowCol;ctx.globalAlpha=0.3;ctx.beginPath();ctx.arc(x,y,rPulse*.4,0,Math.PI*2);ctx.fill();
    }
    // Animation: Orbiting Particles
    else if(anim==='orbiting'){
      for(let i=0;i<8;i++){
        const a=t+i*(Math.PI*2/8);
        const px=x+Math.cos(a)*rPulse*.6, py=y+Math.sin(a)*rPulse*.6;
        ctx.fillStyle=glowCol;ctx.globalAlpha=0.8;ctx.beginPath();ctx.arc(px,py,rPulse*.06,0,Math.PI*2);ctx.fill();
      }
    }
    // Animation: Storm Core (lightning arcs)
    else if(anim==='storm'){
      for(let i=0;i<5;i++){
        const a=t*0.8+i*(Math.PI*2/5);
        const ex=x+Math.cos(a)*rPulse*.7, ey=y+Math.sin(a)*rPulse*.7;
        ctx.strokeStyle=glowCol;ctx.lineWidth=1.5;ctx.globalAlpha=0.7;
        ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(ex,ey);ctx.stroke();
      }
    }

    ctx.globalAlpha=1;

    // Decorations
    if(cfg.decorations.includes('rings')){
      ctx.strokeStyle=glowCol;ctx.globalAlpha=0.5;ctx.lineWidth=1.5;
      for(let i=1;i<=2;i++){
        ctx.beginPath();ctx.arc(x,y,rPulse*(0.5+i*0.15),0,Math.PI*2);ctx.stroke();
      }
    }
    if(cfg.decorations.includes('orbitingstars')){
      for(let i=0;i<6;i++){
        const a=t*0.4+i*(Math.PI*2/6);
        const sx=x+Math.cos(a)*rPulse*.75, sy=y+Math.sin(a)*rPulse*.75;
        ctx.fillStyle=glowCol;ctx.globalAlpha=0.8;ctx.beginPath();ctx.arc(sx,sy,rPulse*.04,0,Math.PI*2);ctx.fill();
      }
    }
    if(cfg.decorations.includes('energyspikes')){
      ctx.strokeStyle=glowCol;ctx.lineWidth=2;ctx.globalAlpha=0.7;
      for(let i=0;i<8;i++){
        const a=i*(Math.PI*2/8);
        const sx=x+Math.cos(a)*rPulse, sy=y+Math.sin(a)*rPulse;
        ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(sx,sy);ctx.stroke();
      }
    }
    if(cfg.decorations.includes('halo')){
      ctx.strokeStyle=glowCol;ctx.globalAlpha=0.4;ctx.lineWidth=2 ;
      ctx.beginPath();ctx.arc(x,y,rPulse*1.3,0,Math.PI*2);ctx.stroke();
    }
    if(cfg.decorations.includes('techpanels')){
      const angle=t*0.3;
      ctx.strokeStyle=glowCol;ctx.lineWidth=1;ctx.globalAlpha=0.5;ctx.save();ctx.translate(x,y);ctx.rotate(angle);
      for(let i=0;i<4;i++){
        ctx.strokeRect(-rPulse*.4,-rPulse*.4,rPulse*.2,rPulse*.2);
        ctx.rotate(Math.PI/2);
      }
      ctx.restore();
    }

    // Effects
    if(cfg.effects.includes('spark')){
      for(let i=0;i<5;i++){
        const a=Math.random()*Math.PI*2;
        const sx=x+Math.cos(a)*(rPulse+Math.random()*20), sy=y+Math.sin(a)*(rPulse+Math.random()*20);
        ctx.fillStyle=glowCol;ctx.globalAlpha=Math.random()*0.6;ctx.beginPath();ctx.arc(sx,sy,1.5,0,Math.PI*2);ctx.fill();
      }
    }
    if(cfg.effects.includes('aura')){
      const auraGrad=ctx.createRadialGradient(x,y,rPulse,x,y,rPulse*2);
      auraGrad.addColorStop(0,glowCol);auraGrad.addColorStop(1,'rgba(255,255,255,0)');
      ctx.fillStyle=auraGrad;ctx.globalAlpha=0.3;ctx.beginPath();ctx.arc(x,y,rPulse*2,0,Math.PI*2);ctx.fill();
    }

    ctx.globalAlpha=1;
    ctx.restore();
  },

  generateSaveCode(){
    const cfg=this.config;
    const code=JSON.stringify(cfg);
    return btoa(code).replace(/\+/g,'-').replace(/\//g,'_').replace(/=/g,'');
  },

  loadFromSaveCode(code){
    try{
      const decoded=atob(code.replace(/-/g,'+').replace(/_/g,'/')+('==').slice(0,(4-code.length%4)%4));
      const cfg=JSON.parse(decoded);
      this.config={...this.config,...cfg};
      if(typeof this.config.name!=='string')this.config.name='';
      if(!this.config.combat)this.config.combat={
        health:180,damage:22,behavior:'aggressive',targeting:'closest',classification:'regular',bossMode:false,
        canSummon:false,minionCount:3,minionRate:3,minionPower:12,abilities:['shield','none','none','none']
      };
      if(!Array.isArray(this.config.attacks)){
        this.config.attacks=[
          {id:'laser',label:'Laser Beam',enabled:true,damage:24,cooldown:1.4,range:560},
          {id:'missile',label:'Missile Launch',enabled:false,damage:40,cooldown:3.6,range:620},
          {id:'pulse',label:'Energy Pulse',enabled:true,damage:16,cooldown:2.1,range:280},
          {id:'shockwave',label:'Shockwave',enabled:false,damage:34,cooldown:4.8,range:240},
          {id:'chain',label:'Chain Lightning',enabled:false,damage:20,cooldown:2.7,range:450},
          {id:'projectile',label:'Projectile Blast',enabled:false,damage:18,cooldown:1.0,range:500}
        ];
      }
      this.refreshUI();
      this.render();
      return true;
    }catch(e){
      toast('Invalid orb code!','#ff6655');
      return false;
    }
  },

  testOrb(options={}){
    if(!this.testCanvas)return;
    this.testActive=true;
    this.testCanvas.style.display='block';
    this.testCanvas.width=window.innerWidth;
    this.testCanvas.height=window.innerHeight;
    this.testSettings={
      autoSpawn:options.autoSpawn!==undefined?options.autoSpawn:true,
      maxEnemies:options.maxEnemies||14,
      info:options.info||'COMBAT SIMULATION - Click to spawn enemy - ESC to exit'
    };
    const testInfo=document.getElementById('creator-test-info');
    testInfo.style.display='block';
    testInfo.textContent=this.testSettings.info;
    this.uiClick();
    this.simClock=0;
    this.attackState={};
    this.minionState={lastSpawn:0};
    this.testEnemies=[];
    this.testMinions=[];
    this.testFx=[];
    this.testOrb={x:this.testCanvas.width/2,y:this.testCanvas.height/2,hp:this.config.combat.health,maxHp:this.config.combat.health};
    this.runTest();
  },

  stopTest(){
    this.testActive=false;
    this.testCanvas.style.display='none';
    document.getElementById('creator-test-info').style.display='none';
    this.closeEnemyPanel(false);
  },

  onTestClick(e){
    if(!this.testActive)return;
    const rect=this.testCanvas.getBoundingClientRect();
    const x=e.clientX-rect.left;
    const y=e.clientY-rect.top;
    const enemy=this.spawnTestEnemy({x,y,type:'raider',hp:140});
    if(enemy)this.testEnemies.push(enemy);
    SFX.orbLand();
  },

  pickTarget(enemies){
    if(!enemies.length)return null;
    const mode=this.config.combat.targeting;
    if(mode==='random')return enemies[Math.floor(Math.random()*enemies.length)];
    if(mode==='strongest')return enemies.slice().sort((a,b)=>b.hp-a.hp)[0];
    if(mode==='weakest')return enemies.slice().sort((a,b)=>a.hp-b.hp)[0];
    return enemies.slice().sort((a,b)=>Math.hypot(a.x-this.testOrb.x,a.y-this.testOrb.y)-Math.hypot(b.x-this.testOrb.x,b.y-this.testOrb.y))[0];
  },

  runTest(){
    if(!this.testActive)return;
    const ctx=this.testCtx, cvs=this.testCanvas;
    ctx.fillStyle='#07080f';ctx.fillRect(0,0,cvs.width,cvs.height);
    const dt=16;
    this.simClock+=dt;
    this.animT+=0.04;

    if(this.testSettings.autoSpawn&&this.simClock%1200<16&&this.testEnemies.length<this.testSettings.maxEnemies){
      const autoType=['raider','swift','tank','drone'][Math.floor(Math.random()*4)];
      const enemy=this.spawnTestEnemy({type:autoType,hp:120+Math.random()*120});
      if(enemy)this.testEnemies.push(enemy);
    }

    this.testEnemies.forEach(e=>{
      e.x+=e.vx;e.y+=e.vy;
      if(e.x<e.r||e.x>cvs.width-e.r)e.vx*=-1;
      if(e.y<e.r||e.y>cvs.height-e.r)e.vy*=-1;
      e.x=Math.max(e.r,Math.min(cvs.width-e.r,e.x));
      e.y=Math.max(e.r,Math.min(cvs.height-e.r,e.y));
    });

    if(this.config.combat.canSummon){
      const spawnGap=this.config.combat.minionRate*1000;
      if(this.simClock-this.minionState.lastSpawn>=spawnGap&&this.testMinions.length<this.config.combat.minionCount){
        this.minionState.lastSpawn=this.simClock;
        const a=Math.random()*Math.PI*2;
        this.testMinions.push({x:this.testOrb.x+Math.cos(a)*80,y:this.testOrb.y+Math.sin(a)*80,hp:40+this.config.combat.minionPower,power:this.config.combat.minionPower,cd:0});
      }
    }

    const target=this.pickTarget(this.testEnemies.filter(e=>e.hp>0));
    this.config.attacks.filter(a=>a.enabled).forEach(att=>{
      const last=this.attackState[att.id]||0;
      if(this.simClock-last<att.cooldown*1000||!target)return;
      const d=Math.hypot(target.x-this.testOrb.x,target.y-this.testOrb.y);
      if(d>att.range)return;
      this.attackState[att.id]=this.simClock;
      target.hp-=(att.damage+this.config.combat.damage*0.35);
      this.testFx.push({x1:this.testOrb.x,y1:this.testOrb.y,x2:target.x,y2:target.y,t:220,type:att.id});
      SFX.laser();
    });

    this.testMinions.forEach(m=>{
      const t=this.pickTarget(this.testEnemies.filter(e=>e.hp>0));
      if(!t)return;
      const ang=Math.atan2(t.y-m.y,t.x-m.x);
      m.x+=Math.cos(ang)*1.2;
      m.y+=Math.sin(ang)*1.2;
      m.cd-=dt;
      if(m.cd<=0&&Math.hypot(t.x-m.x,t.y-m.y)<220){m.cd=900;t.hp-=m.power*0.35;}
    });

    this.testEnemies=this.testEnemies.filter(e=>e.hp>0);
    this.testFx=this.testFx.filter(f=>{f.t-=dt;return f.t>0;});

    this.testEnemies.forEach(e=>{
      const eg=ctx.createRadialGradient(e.x,e.y,0,e.x,e.y,e.r*1.8);
      eg.addColorStop(0,e.glow||'#ff8888');eg.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=eg;ctx.beginPath();ctx.arc(e.x,e.y,e.r*1.8,0,Math.PI*2);ctx.fill();
      ctx.fillStyle=e.core||'#772233';ctx.beginPath();ctx.arc(e.x,e.y,e.r,0,Math.PI*2);ctx.fill();
      ctx.strokeStyle=e.color||'#ff6677';ctx.lineWidth=1.5;ctx.stroke();
      const bw=e.r*2.1;
      ctx.fillStyle='rgba(255,255,255,.15)';ctx.fillRect(e.x-bw/2,e.y-e.r-12,bw,4);
      ctx.fillStyle='#ff6677';ctx.fillRect(e.x-bw/2,e.y-e.r-12,Math.max(0,(e.hp/e.maxHp))*bw,4);
    });

    this.testFx.forEach(f=>{
      ctx.strokeStyle=f.type==='shockwave'?'rgba(255,220,120,.75)':'rgba(120,220,255,.8)';
      ctx.lineWidth=2.2;ctx.beginPath();ctx.moveTo(f.x1,f.y1);ctx.lineTo(f.x2,f.y2);ctx.stroke();
    });

    this.testMinions.forEach(m=>{ctx.fillStyle='rgba(120,255,190,.9)';ctx.beginPath();ctx.arc(m.x,m.y,6,0,Math.PI*2);ctx.fill();});

    let drawR=this.getSizeRadius(1.35);
    if(this.config.combat.bossMode)drawR*=1.28;
    this._drawCustomOrb(ctx,this.testOrb.x,this.testOrb.y,drawR);

    if(this.config.combat.bossMode){
      const w=Math.min(520,cvs.width*0.58),x=(cvs.width-w)/2,y=24;
      ctx.fillStyle='rgba(6,10,24,.85)';ctx.fillRect(x,y,w,16);
      ctx.strokeStyle='rgba(120,220,255,.55)';ctx.strokeRect(x,y,w,16);
      const hpPct=Math.max(0,this.testOrb.hp/this.testOrb.maxHp);
      ctx.fillStyle='rgba(255,90,110,.85)';ctx.fillRect(x,y,w*hpPct,16);
    }

    requestAnimationFrame(()=>this.runTest());
  },
};

window.addEventListener('keydown',e=>{
  if(e.key==='Escape'&&CREATOR.testActive)CREATOR.stopTest();
});

