function ofBossIntroPreset(key,overrides={}){
  return {...(OF_BOSS_INTRO_PRESETS[key]||{label:'Boss',subtitle:'ENCOUNTER INITIALIZING',scale:1/3,color:'#ffffff',accent:'#88ccff'}),...overrides};
}
const OF_BOSS_INTRO={
  active:false,bossKey:null,config:null,time:0,
  start(config){
    this.active=true;
    this.bossKey=config.bossKey||'boss';
    this.config={duration:2600,zoomHold:0.68,letterbox:0.16,...config};
    this.time=0;
  },
  stop(){ this.active=false; this.bossKey=null; this.config=null; this.time=0; },
  update(){
    if(!this.active||!this.config) return;
    this.time++;
    const maxFrames=Math.max(1,Math.round(this.config.duration/16));
    if(this.time>=maxFrames) this.stop();
  },
  _easeOut(t){ return 1-Math.pow(1-t,3); },
  _easeInOut(t){ return t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2; },
  _resolveCameraScale(preset){
    const val=Number(preset);
    if(!Number.isFinite(val)||val<=0) return 1;
    if(val>=0.62) return 1.16; // 1/1.5 - slightly zoomed in
    if(val>=0.48) return 1.08; // 1/2 - moderately zoomed in
    if(val>=0.31) return 0.98; // 1/3 - medium framing
    if(val>=0.23) return 0.86; // 1/4 - slightly zoomed out
    return 0.74; // 1/5 - far zoomed out
  },
  _progress(){
    if(!this.active||!this.config) return 1;
    const maxFrames=Math.max(1,Math.round(this.config.duration/16));
    return Math.max(0,Math.min(1,this.time/maxFrames));
  },
  _focus(){
    if(!this.config) return {x:OF.W*0.5,y:OF.H*0.5};
    if(typeof this.config.track==='function'){
      const next=this.config.track();
      if(next&&Number.isFinite(next.x)&&Number.isFinite(next.y)) return next;
    }
    return {x:this.config.focusX??OF.W*0.5,y:this.config.focusY??OF.H*0.5};
  },
  getCamera(){
    if(!this.active||!this.config) return {scale:1,focusX:OF.W*0.5,focusY:OF.H*0.5,overlay:0,letterbox:0};
    const progress=this._progress();
    const hold=Math.max(.35,Math.min(.86,this.config.zoomHold??.68));
    const focus=this._focus();
    const targetScale=this._resolveCameraScale(this.config.scale??1);
    let scale=targetScale;
    if(progress<0.24) scale=1+(targetScale-1)*this._easeOut(progress/0.24);
    else if(progress>hold){
      const outT=(progress-hold)/Math.max(.01,1-hold);
      scale=targetScale+(1-targetScale)*this._easeInOut(Math.min(1,outT));
    }
    const overlay=progress<0.2?0.5*this._easeOut(progress/0.2):progress>hold?0.5*(1-Math.min(1,(progress-hold)/Math.max(.01,1-hold))):0.5;
    const letterbox=(this.config.letterbox||0.16)*Math.sin(Math.min(1,progress)*Math.PI);
    return {scale,focusX:focus.x,focusY:focus.y,overlay,letterbox};
  },
  getManifest(){
    if(!this.active||!this.config) return {alpha:1,scale:1};
    const reveal=Math.min(1,this._progress()/0.58);
    return {alpha:0.12+0.88*this._easeOut(reveal),scale:0.42+0.58*this._easeOut(reveal)};
  },
  drawWorld(ctx){
    if(!this.active||!this.config) return;
    const progress=this._progress();
    const t=this.time*0.06;
    const focus=this._focus();
    const color=this.config.color||'#ffffff';
    const key=this.bossKey;
    const maxDim=Math.max(OF.W,OF.H);
    ctx.save();
    if(key==='singularity_core'||key==='boss_void'){
      const grad=ctx.createRadialGradient(focus.x,focus.y,8,focus.x,focus.y,maxDim*0.3);
      grad.addColorStop(0,'rgba(10,0,20,.92)');grad.addColorStop(.32,'rgba(60,20,110,.38)');grad.addColorStop(1,'rgba(0,0,0,0)');
      ctx.beginPath();ctx.arc(focus.x,focus.y,maxDim*0.3,0,Math.PI*2);ctx.fillStyle=grad;ctx.fill();
      for(let i=0;i<7;i++){
        const base=(i/7)*Math.PI*2-t*(1.1+i*0.08);
        ctx.strokeStyle=i%2===0?'rgba(182,128,255,.34)':'rgba(235,235,255,.22)';
        ctx.lineWidth=2.2;ctx.beginPath();
        for(let s=0;s<26;s++){
          const prog=s/25; const ang=base+prog*2.1; const rr=maxDim*(0.28-prog*0.22);
          const px=focus.x+Math.cos(ang)*rr, py=focus.y+Math.sin(ang)*rr;
          s===0?ctx.moveTo(px,py):ctx.lineTo(px,py);
        }
        ctx.stroke();
      }
    } else if(key==='boss_tyrant'){
      for(let i=0;i<3;i++){
        ctx.beginPath();ctx.arc(focus.x,focus.y,90+i*42+Math.sin(t*2.4+i)*6,0,Math.PI*2);
        ctx.strokeStyle='rgba(255,226,130,.28)';ctx.lineWidth=8-i*2;ctx.shadowColor='#ffe386';ctx.shadowBlur=18;ctx.stroke();
      }
    } else if(key==='boss_giant'){
      for(let i=0;i<4;i++){
        const rr=110+i*34;
        ctx.beginPath();ctx.arc(focus.x,focus.y,rr,0,Math.PI*2);ctx.strokeStyle=`rgba(255,150,70,${0.25-i*0.04})`;ctx.lineWidth=10-i*2;ctx.shadowColor='#ff9a52';ctx.shadowBlur=18;ctx.stroke();
      }
    } else if(key==='boss_rainbow'){
      for(let i=0;i<8;i++){
        const ang=t*0.7+i*(Math.PI/4), dist=120+Math.sin(t*2+i)*20;
        ctx.beginPath();ctx.arc(focus.x+Math.cos(ang)*dist,focus.y+Math.sin(ang)*dist,12,0,Math.PI*2);
        ctx.fillStyle=`hsla(${i*45+t*40},100%,70%,.7)`;ctx.shadowColor=`hsl(${i*45+t*40},100%,70%)`;ctx.shadowBlur=20;ctx.fill();
      }
    } else if(key==='boss_ultimate'){
      for(let i=0;i<5;i++){
        ctx.save();ctx.translate(focus.x,focus.y);ctx.rotate(t*(0.35+i*0.12));ctx.strokeStyle=`hsla(${260+i*18},100%,75%,${0.28-i*0.03})`;ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,120+i*38,0,Math.PI*2);ctx.stroke();ctx.restore();
      }
    } else if(key==='mission_boss_spire'){
      for(let i=0;i<6;i++){
        const ang=t*0.8+i*(Math.PI/3);
        ctx.strokeStyle='rgba(255,142,214,.28)';ctx.lineWidth=3;ctx.beginPath();
        ctx.moveTo(focus.x+Math.cos(ang)*28,focus.y+Math.sin(ang)*28);
        ctx.lineTo(focus.x+Math.cos(ang+0.7)*170,focus.y+Math.sin(ang+0.7)*170);
        ctx.stroke();
      }
    } else if(key==='mission_boss_eclipse'){
      const grad=ctx.createRadialGradient(focus.x,focus.y,10,focus.x,focus.y,maxDim*0.34);
      grad.addColorStop(0,'rgba(0,0,0,.84)');grad.addColorStop(.4,'rgba(40,40,90,.32)');grad.addColorStop(1,'rgba(0,0,0,0)');
      ctx.beginPath();ctx.arc(focus.x,focus.y,maxDim*0.34,0,Math.PI*2);ctx.fillStyle=grad;ctx.fill();
      ctx.beginPath();ctx.arc(focus.x,focus.y,148+Math.sin(t*2)*10,0,Math.PI*2);ctx.strokeStyle='rgba(170,190,255,.24)';ctx.lineWidth=6;ctx.stroke();
    } else if(key==='mission_boss_cataclysm'){
      for(let i=0;i<5;i++){
        const x=OF.W*(0.55+0.38*((Math.sin(t*0.8+i*1.1)+1)/2));
        ctx.beginPath();ctx.moveTo(x,0);
        for(let s=1;s<=5;s++){ const yy=(OF.H/5)*s; ctx.lineTo(x+Math.sin(t*2+s+i)*18,yy); }
        ctx.strokeStyle='rgba(255,166,90,.32)';ctx.lineWidth=4;ctx.shadowColor='#ffb15a';ctx.shadowBlur=16;ctx.stroke();
      }
    } else if(key==='tempest_leviathan'){
      for(let i=0;i<5;i++){
        const bx=OF.W*(0.56+0.34*((Math.sin(t*1.2+i*1.6)+1)/2));
        ctx.beginPath();ctx.moveTo(bx,0);
        for(let s=1;s<=7;s++){
          const yy=OF.H*(s/7);
          const xx=bx+Math.sin(t*2.4+s+i)*34;
          ctx.lineTo(xx,yy);
        }
        ctx.strokeStyle=`rgba(255,255,255,${0.18+0.14*Math.sin(t*4+i)})`;
        ctx.lineWidth=3;
        ctx.shadowColor='#9aefff';
        ctx.shadowBlur=18;
        ctx.stroke();
      }
      for(let i=0;i<4;i++){
        ctx.beginPath();
        ctx.arc(focus.x,focus.y,124+i*34+Math.sin(t*2+i)*10,0,Math.PI*2);
        ctx.strokeStyle='rgba(114,233,255,.18)';
        ctx.lineWidth=5-i;
        ctx.stroke();
      }
    } else if(key==='mirror_monarch'){
      for(let i=0;i<6;i++){
        const ox=Math.sin(t*1.4+i*1.2)*96;
        const oy=Math.cos(t*1.1+i*1.5)*78;
        ctx.save();
        ctx.globalAlpha=0.14+0.08*Math.sin(t*3+i);
        ctx.translate(focus.x+ox,focus.y+oy);
        ctx.rotate(t*0.6+i);
        ctx.strokeStyle=i%2===0?'#d9c3ff':'#fff0ff';
        ctx.lineWidth=3;
        ctx.strokeRect(-46,-46,92,92);
        ctx.restore();
      }
      for(let i=0;i<8;i++){
        const ang=(i/8)*Math.PI*2+t*0.38;
        const dist=168-progress*100;
        ctx.save();
        ctx.translate(focus.x+Math.cos(ang)*dist,focus.y+Math.sin(ang)*dist);
        ctx.rotate(ang+t);
        ctx.beginPath();ctx.moveTo(0,-22);ctx.lineTo(16,0);ctx.lineTo(0,22);ctx.lineTo(-16,0);ctx.closePath();
        ctx.fillStyle=i%2===0?'rgba(217,195,255,.34)':'rgba(255,240,255,.28)';
        ctx.shadowColor='#e8d8ff';
        ctx.shadowBlur=16;
        ctx.fill();
        ctx.restore();
      }
    } else if(key==='gravebloom_titan'){
      const grad=ctx.createRadialGradient(focus.x,focus.y,12,focus.x,focus.y,maxDim*0.32);
      grad.addColorStop(0,'rgba(45,80,18,.82)');
      grad.addColorStop(.46,'rgba(120,190,74,.28)');
      grad.addColorStop(1,'rgba(0,0,0,0)');
      ctx.beginPath();ctx.arc(focus.x,focus.y,maxDim*0.32,0,Math.PI*2);ctx.fillStyle=grad;ctx.fill();
      for(let i=0;i<7;i++){
        const ang=t*0.42+i*(Math.PI*2/7);
        const dist=150+i*16;
        ctx.beginPath();
        ctx.arc(focus.x+Math.cos(ang)*dist,focus.y+Math.sin(ang)*dist,7+i*1.3,0,Math.PI*2);
        ctx.fillStyle=i%2===0?'rgba(172,236,114,.78)':'rgba(255,230,150,.72)';
        ctx.shadowColor='#b6ee7a';
        ctx.shadowBlur=18;
        ctx.fill();
      }
      for(let i=0;i<5;i++){
        ctx.save();
        ctx.translate(focus.x,focus.y);
        ctx.rotate(t*0.35+i*(Math.PI*2/5));
        ctx.fillStyle='rgba(138,214,98,.16)';
        ctx.beginPath();
        ctx.ellipse(0,-94-i*18,24,68,0,0,Math.PI*2);
        ctx.fill();
        ctx.restore();
      }
    } else if(key==='mothership'||key==='oblivion_mothership'){
      const warm=key==='mothership'?'rgba(255,130,60,.22)':'rgba(255,90,30,.24)';
      for(let i=0;i<3;i++){ ctx.beginPath();ctx.arc(focus.x,focus.y,120+i*46+Math.sin(t*2+i)*8,0,Math.PI*2);ctx.strokeStyle=warm;ctx.lineWidth=8-i*2;ctx.shadowColor=color;ctx.shadowBlur=22;ctx.stroke(); }
    } else if(key==='apex'){
      for(let i=0;i<8;i++){
        ctx.save();ctx.translate(focus.x,focus.y);ctx.rotate(t*0.8+i*(Math.PI/4));ctx.strokeStyle=`hsla(${(t*80+i*45)%360},100%,70%,.28)`;ctx.lineWidth=3;ctx.shadowBlur=18;ctx.shadowColor=`hsl(${(t*80+i*45)%360},100%,70%)`;ctx.beginPath();ctx.moveTo(50,0);ctx.bezierCurveTo(140,-90,240,90,320,0);ctx.stroke();ctx.restore();
      }
    }
    ctx.restore();
  },
  drawOverlay(ctx){
    if(!this.active||!this.config) return;
    const camera=this.getCamera();
    const progress=this._progress();
    const titleAlpha=Math.min(1,Math.sin(Math.min(1,progress/.82)*Math.PI));
    ctx.save();
    ctx.fillStyle=`rgba(0,0,0,${camera.overlay})`;
    ctx.fillRect(0,0,OF.W,OF.H);
    const barH=Math.round(OF.H*camera.letterbox);
    if(barH>0){ ctx.fillStyle='rgba(0,0,0,.78)'; ctx.fillRect(0,0,OF.W,barH); ctx.fillRect(0,OF.H-barH,OF.W,barH); }
    const grad=ctx.createRadialGradient(OF.W*0.5,OF.H*0.5,Math.min(OF.W,OF.H)*0.05,OF.W*0.5,OF.H*0.5,Math.max(OF.W,OF.H)*0.72);
    grad.addColorStop(0,'rgba(255,255,255,0)');grad.addColorStop(.7,'rgba(0,0,0,0)');grad.addColorStop(1,'rgba(0,0,0,.45)');
    ctx.fillStyle=grad;ctx.fillRect(0,0,OF.W,OF.H);
    ctx.textAlign='center';
    ctx.globalAlpha=titleAlpha;
    ctx.font='900 18px Orbitron,monospace';
    ctx.fillStyle=this.config.accent||'#ffffff';
    ctx.fillText((this.config.subtitle||'BOSS INTRODUCTION').toUpperCase(),OF.W*0.5,Math.max(44,OF.H*0.12));
    ctx.font='900 34px Orbitron,monospace';
    ctx.fillStyle=this.config.color||'#ffffff';
    ctx.shadowColor=this.config.color||'#ffffff';
    ctx.shadowBlur=24;
    ctx.fillText((this.config.label||'BOSS').toUpperCase(),OF.W*0.5,Math.max(78,OF.H*0.17));
    ctx.restore();
  },
};

